INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('66fe9102-7150-5d27-a8d5-6325f648ae68', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 7, 7, 'and give him no rest, until he establishes, and until he makes Jerusalem a praise in the earth.'),
  ('fcc148ad-0f74-5f98-ac74-8a8c9316f4a7', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 8, 8, 'Yahweh has sworn by his right hand, and by the arm of his strength, "Surely I will no more give your grain to be food for your enemies; and foreigners shall not drink your new wine, for which you have labored:'),
  ('5fc97f22-0333-59ff-a632-260c3e651a30', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 9, 9, 'but those who have garnered it shall eat it, and praise Yahweh; and those who have gathered it shall drink it in the courts of my sanctuary."'),
  ('96d771e3-6e73-5e89-a2dc-ef97f01362d5', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 10, 10, 'Go through, go through the gates! Prepare the way of the people! Cast up, cast up the highway! Gather out the stones! Lift up a banner for the peoples.'),
  ('8e6a3537-ceb5-5c6a-a10a-510041694341', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 11, 11, 'Behold, Yahweh has proclaimed to the end of the earth, "Say to the daughter of Zion, ''Behold, your salvation comes. Behold, his reward is with him, and his recompense before him.''"'),
  ('7dd84429-18e7-5f62-abe6-0d08b2a3c15f', 'dfa73dce-050e-5cfe-afc4-eb7abe4880db', NULL, 12, 12, 'They shall call them The holy people, The redeemed of Yahweh: and you shall be called Sought out, A city not forsaken.'),
  ('02469ca4-87c4-54c2-a366-ba0437466404', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 1, 1, 'Who is this who comes from Edom, with dyed garments from Bozrah? this who is glorious in his clothing, marching in the greatness of his strength? "It is I who speak in righteousness, mighty to save."'),
  ('1f983c6c-3138-5f2c-a842-4d0308a1a07f', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 2, 2, 'Why are you red in your clothing, and your garments like him who treads in the wine vat?'),
  ('86a956c1-ca95-528c-a100-1af10c315b5f', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 3, 3, '"I have trodden the winepress alone; and of the peoples there was no man with me: yes, I trod them in my anger, and trampled them in my wrath; and their lifeblood is sprinkled on my garments, and I have stained all my clothing.'),
  ('08543003-d1a5-5e94-ad78-8ffbb8793f9e', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 4, 4, 'For the day of vengeance was in my heart, and the year of my redeemed is come.'),
  ('24f7c515-9516-5696-a9f0-2242b2d2b725', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 5, 5, 'I looked, and there was none to help; and I wondered that there was none to uphold: therefore my own arm brought salvation to me; and my wrath, it upheld me.'),
  ('1c6f8c20-c15e-5760-a0b2-a6e0f355558e', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 6, 6, 'I trod down the peoples in my anger, and made them drunk in my wrath, and I poured out their lifeblood on the earth."'),
  ('4c736f4a-267c-517a-a042-d3f9d88ee00c', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 7, 7, 'I will make mention of the loving kindnesses of Yahweh, [and] the praises of Yahweh, according to all that Yahweh has bestowed on us, and the great goodness toward the house of Israel, which he has bestowed on them according to his mercies, and according to the multitude of his loving kindnesses.'),
  ('d809cb95-3cb4-5e1a-ad03-fb17bf06f0f5', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 8, 8, 'For he said, "Surely, they are my people, children who will not deal falsely:" so he was their Savior.'),
  ('f16b12fe-a818-5596-a6dc-622ee75e84b2', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 9, 9, 'In all their affliction he was afflicted, and the angel of his presence saved them: in his love and in his pity he redeemed them; and he bore them, and carried them all the days of old.'),
  ('f5e088f2-8d4b-5dc6-a391-11822dd16bcc', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 10, 10, 'But they rebelled, and grieved his holy Spirit: therefore he was turned to be their enemy, [and] himself fought against them.'),
  ('1a56421a-a99e-5cb2-a794-32f53d933011', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 11, 11, 'Then he remembered the days of old, Moses [and] his people, [saying], Where is he who brought them up out of the sea with the shepherds of his flock? where is he who put his holy Spirit in the midst of them?'),
  ('457aa5ae-b1bb-55ae-a6f5-e2a4ff9dcbbe', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 12, 12, 'who caused his glorious arm to go at the right hand of Moses? who divided the waters before them, to make himself an everlasting name?'),
  ('6c302f87-4cbf-550b-ac70-82b490f1417e', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 13, 13, 'who led them through the depths, as a horse in the wilderness, so that they didn''t stumble?'),
  ('15f79bec-8d67-5420-a31c-286e826cc902', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 14, 14, 'As the livestock that go down into the valley, the Spirit of Yahweh caused them to rest; so you led your people, to make yourself a glorious name.'),
  ('f405677d-37d3-5518-a772-62dd625f6338', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 15, 15, 'Look down from heaven, and see from the habitation of your holiness and of your glory: where are your zeal and your mighty acts? the yearning of your heart and your compassion is restrained toward me.'),
  ('6c3ff7f8-e419-52f1-ac37-77da620f85c1', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 16, 16, 'For you are our Father, though Abraham doesn''t know us, and Israel does not acknowledge us: you, Yahweh, are our Father; our Redeemer from everlasting is your name.'),
  ('a8181003-4e90-56c0-af18-9edb5ff92e14', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 17, 17, 'O Yahweh, why do you make us to err from your ways, and harden our heart from your fear? Return for your servants'' sake, the tribes of your inheritance.'),
  ('7b2ab4d6-54ea-5146-a568-e6f53a375481', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 18, 18, 'Your holy people possessed [it] but a little while: our adversaries have trodden down your sanctuary.'),
  ('4b84861a-a176-5cd3-ac2d-cae67c993b37', '0c868e9a-c8e8-5987-ae44-1b404a4df4d5', NULL, 19, 19, 'We have become as they over whom you never bear rule, as those who were not called by your name.'),
  ('73b2f32b-9552-58be-a0eb-6bb9983de66d', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 1, 1, 'Oh that you would tear the heavens, that you would come down, that the mountains might quake at your presence,'),
  ('1332333a-aadd-58d4-ae45-827b9b1aca35', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 2, 2, 'as when fire kindles the brushwood, [and] the fire causes the waters to boil; to make your name known to your adversaries, that the nations may tremble at your presence!'),
  ('1623370f-cfef-5a56-a98f-ab913ef0fbf8', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 3, 3, 'When you did awesome things which we didn''t look for, you came down, the mountains quaked at your presence.'),
  ('9c145fea-5bdc-5411-a6e6-6120511a4094', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 4, 4, 'For from of old men have not heard, nor perceived by the ear, neither has the eye seen a God besides you, who works for him who waits for him.'),
  ('c1eb4ab0-94b0-5709-a173-d38b7fd5ed43', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 5, 5, 'You meet him who rejoices and works righteousness, those who remember you in your ways. Behold, you were angry, and we sinned. We have been in sin for a long time; and shall we be saved?'),
  ('ef65d5a5-63c4-5c82-a379-f2a850e39117', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 6, 6, 'For we have all become as one who is unclean, and all our righteousness is as a polluted garment: and we all fade as a leaf; and our iniquities, like the wind, take us away.'),
  ('b0b635e1-0b29-5961-a185-fcb05b361ed2', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 7, 7, 'There is none who calls on your name, who stirs up himself to take hold of you; for you have hidden your face from us, and have consumed us by means of our iniquities.'),
  ('abbedf66-2da4-5d06-a72c-da17d0cd79cc', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 8, 8, 'But now, Yahweh, you are our Father; we are the clay, and you our potter; and we all are the work of your hand.'),
  ('ad7bfd9b-35c2-5e41-a708-977df6c39718', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 9, 9, 'Don''t be furious, Yahweh, neither remember iniquity forever: see, look, we beg you, we are all your people.'),
  ('dad7b1c0-c533-5a1c-ac0a-5caf6daa5aa5', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 10, 10, 'Your holy cities are become a wilderness, Zion is become a wilderness, Jerusalem a desolation.'),
  ('489aa7c3-2756-58ea-a625-1d83440ff738', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 11, 11, 'Our holy and our beautiful house, where our fathers praised you, is burned with fire; and all our pleasant places are laid waste.'),
  ('11df49e7-6122-50a3-ab2a-4fe0f7d295aa', 'e87d7ce7-c3f1-592d-a9d7-e838f8627c34', NULL, 12, 12, 'Will you refrain yourself for these things, Yahweh? Will you hold your peace, and afflict us very severely?'),
  ('73f8ef6a-7756-5297-a2ab-8f70ff0d6342', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 1, 1, '"I am inquired of by those who didn''t ask; I am found by those who didn''t seek me: I said, See me, see me, to a nation that was not called by my name.'),
  ('a4f69798-212d-566e-a2cd-8cecaca87f13', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 2, 2, 'I have spread out my hands all the day to a rebellious people, who walk in a way that is not good, after their own thoughts;'),
  ('27d76db1-d3a0-5c26-a02d-aa93dbc2012f', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 3, 3, 'a people who provoke me to my face continually, sacrificing in gardens, and burning incense on bricks;'),
  ('ebaed386-f70a-5dd9-a46f-675867c988f5', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 4, 4, 'who sit among the graves, and lodge in the secret places; who eat pig''s flesh, and broth of abominable things is in their vessels;'),
  ('1762c1be-37d4-5338-afee-d09e730bcc17', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 5, 5, 'who say, Stand by yourself, don''t come near to me, for I am holier than you. These are a smoke in my nose, a fire that burns all the day.'),
  ('7e11a466-9708-5f9c-aacf-ad6292004c1f', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 6, 6, '"Behold, it is written before me: I will not keep silence, but will recompense, yes, I will recompense into their bosom,'),
  ('ec4412cb-cea4-594d-a5c2-9f9214974251', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 7, 7, 'your own iniquities, and the iniquities of your fathers together," says Yahweh, "who have burned incense on the mountains, and blasphemed me on the hills; therefore will I first measure their work into their bosom."'),
  ('15114384-4a5a-59c3-a1bf-6cf097852c54', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 8, 8, 'Thus says Yahweh, "As the new wine is found in the cluster, and one says, ''Don''t destroy it, for a blessing is in it:'' so will I do for my servants'' sake, that I may not destroy them all.'),
  ('e61ab4cc-38a2-52de-a057-d9238fd5ecbb', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 9, 9, 'I will bring forth a seed out of Jacob, and out of Judah an inheritor of my mountains; and my chosen shall inherit it, and my servants shall dwell there.'),
  ('7a318d03-478f-51f4-ae7d-09cb219660ba', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 10, 10, 'Sharon shall be a fold of flocks, and the valley of Achor a place for herds to lie down in, for my people who have sought me.'),
  ('d0b03a52-7a3e-5ccb-a132-1f1a6e83ef72', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 11, 11, '"But you who forsake Yahweh, who forget my holy mountain, who prepare a table for Fortune, and who fill up mixed wine to Destiny;'),
  ('2aafc648-d7ff-5330-a152-bc1b76f96e80', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 12, 12, 'I will destine you to the sword, and you shall all bow down to the slaughter; because when I called, you did not answer; when I spoke, you did not hear; but you did that which was evil in my eyes, and chose that in which I didn''t delight."'),
  ('30598074-abf6-51d1-a69b-d77897e6af15', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 13, 13, 'Therefore thus says the Lord Yahweh, "Behold, my servants shall eat, but you shall be hungry; behold, my servants shall drink, but you shall be thirsty; behold, my servants shall rejoice, but you shall be disappointed;'),
  ('97a1569b-ad3f-5eeb-ad17-c6799f1e71b0', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 14, 14, 'behold, my servants shall sing for joy of heart, but you shall cry for sorrow of heart, and shall wail for anguish of spirit.'),
  ('51423730-3c94-5d14-a9b9-8a2ad604bb11', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 15, 15, 'You shall leave your name for a curse to my chosen; and the Lord Yahweh will kill you; and he will call his servants by another name:'),
  ('ce00fbad-bd8c-501d-a53c-6ec944424449', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 16, 16, 'so that he who blesses himself in the earth shall bless himself in the God of truth; and he who swears in the earth shall swear by the God of truth; because the former troubles are forgotten, and because they are hidden from my eyes.'),
  ('6f819260-c6b8-5f43-a19d-744109a07372', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 17, 17, '"For, behold, I create new heavens and a new earth; and the former things shall not be remembered, nor come into mind.'),
  ('bc057f8a-9e30-59ea-afe6-d29dad07db63', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 18, 18, 'But be you glad and rejoice forever in that which I create; for, behold, I create Jerusalem a rejoicing, and her people a joy.'),
  ('19d30644-841d-5b2c-a8c6-2f330045b6a0', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 19, 19, 'I will rejoice in Jerusalem, and joy in my people; and there shall be heard in her no more the voice of weeping and the voice of crying.'),
  ('3a878bdf-17af-539d-a72c-fe350f4955f3', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 20, 20, '"There shall be no more there an infant of days, nor an old man who has not filled his days; for the child shall die one hundred years old, and the sinner being one hundred years old shall be accursed.'),
  ('7da2abe5-c985-5723-a0ca-30ba26ed422b', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 21, 21, 'They shall build houses, and inhabit them; and they shall plant vineyards, and eat the fruit of them.'),
  ('2f5b75c1-0c09-5e3f-a201-06764f0bed6e', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 22, 22, 'They shall not build, and another inhabit; they shall not plant, and another eat: for as the days of a tree shall be the days of my people, and my chosen shall long enjoy the work of their hands.'),
  ('d7fc9ee4-b274-5c7d-a518-81ff92325b12', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 23, 23, 'They shall not labor in vain, nor bring forth for calamity; for they are the seed of the blessed of Yahweh, and their offspring with them.'),
  ('a9760ec0-85ce-5794-a74a-9dc532ef078b', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 24, 24, 'It shall happen that, before they call, I will answer; and while they are yet speaking, I will hear.'),
  ('744b16ad-88e7-55ca-a0c7-cb89106dc35a', '95beca38-911b-573c-a6d3-8af8bac07984', NULL, 25, 25, 'The wolf and the lamb shall feed together, and the lion shall eat straw like the ox; and dust shall be the serpent''s food. They shall not hurt nor destroy in all my holy mountain," says Yahweh.'),
  ('584b8bdc-5f7b-5ca3-ab2e-1ec44271cfcd', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 1, 1, 'Thus says Yahweh, "Heaven is my throne, and the earth is my footstool: what kind of house will you build to me? and what place shall be my rest?'),
  ('03658aba-8bc8-5e5f-ab9f-78b83b5b9f38', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 2, 2, 'For all these things has my hand made, and [so] all these things came to be," says Yahweh: "but to this man will I look, even to him who is poor and of a contrite spirit, and who trembles at my word.'),
  ('3cd4bf45-bd10-5a08-affe-36fe05ffab86', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 3, 3, 'He who kills an ox is as he who kills a man; he who sacrifices a lamb, as he who breaks a dog''s neck; he who offers an offering, [as he who offers] pig''s blood; he who burns frankincense, as he who blesses an idol. Yes, they have chosen their own ways, and their soul delights in their abominations:'),
  ('ff8e3492-13c6-5be5-a189-f47b279bcdd1', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 4, 4, 'I also will choose their delusions, and will bring their fears on them; because when I called, none did answer; when I spoke, they did not hear: but they did that which was evil in my eyes, and chose that in which I didn''t delight."'),
  ('e6a30f08-2a28-58b6-a155-7ea8d87b2e44', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 5, 5, 'Hear the word of Yahweh, you who tremble at his word: "Your brothers who hate you, who cast you out for my name''s sake, have said, ''Let Yahweh be glorified, that we may see your joy;'' but it is those who shall be disappointed.'),
  ('edf73b32-ef75-5d93-a48a-c22354d27313', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 6, 6, 'A voice of tumult from the city, a voice from the temple, a voice of Yahweh that renders recompense to his enemies.'),
  ('8c00d8f3-2391-5214-a6a1-3d604cab23f3', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 7, 7, '"Before she travailed, she brought forth; before her pain came, she delivered a son.'),
  ('e9345798-0e51-50ac-a1fe-6893088f52f7', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 8, 8, 'Who has heard such a thing? who has seen such things? Shall a land be born in one day? shall a nation be brought forth at once? for as soon as Zion travailed, she brought forth her children.'),
  ('8170af13-fd31-5343-a434-bd3c3a79ef8c', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 9, 9, 'Shall I bring to the birth, and not cause to bring forth?" says Yahweh: "shall I who cause to bring forth shut [the womb]?" says your God.'),
  ('6b6733cc-0e87-5068-ad69-e60d8d92f598', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 10, 10, '"Rejoice with Jerusalem, and be glad for her, all you who love her: rejoice for joy with her, all you who mourn over her;'),
  ('9a9ec258-e9f3-567e-a9b8-f3b8f7096aa5', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 11, 11, 'that you may nurse and be satisfied at the comforting breasts; that you may drink deeply, and be delighted with the abundance of her glory."'),
  ('7f67ade7-df7f-54f8-a162-798e1a9c390a', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 12, 12, 'For thus says Yahweh, "Behold, I will extend peace to her like a river, and the glory of the nations like an overflowing stream: and you will nurse. You will be carried on her side, and will be dandled on her knees.'),
  ('d03d9f33-bdb2-5923-a3ae-5c6d9d2c3a20', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 13, 13, 'As one whom his mother comforts, so will I comfort you; and you will be comforted in Jerusalem."'),
  ('d1e5c87b-e879-5e5d-aeb9-cec6e2ed454c', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 14, 14, 'You will see [it], and your heart shall rejoice, and your bones shall flourish like the tender grass: and the hand of Yahweh shall be known toward his servants; and he will have indignation against his enemies.'),
  ('e19a7c1a-c7a8-51e0-a090-9c950215dbd0', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 15, 15, 'For, behold, Yahweh will come with fire, and his chariots shall be like the whirlwind; to render his anger with fierceness, and his rebuke with flames of fire.'),
  ('2acbccf7-60a0-543d-ab8b-5e7c69266782', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 16, 16, 'For by fire will Yahweh execute judgment, and by his sword, on all flesh; and the slain of Yahweh shall be many.'),
  ('ce6632f5-b5b6-561e-aa97-28f891ce625c', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 17, 17, '"Those who sanctify themselves and purify themselves [to go] to the gardens, behind one in the midst, eating pig''s flesh, and the abomination, and the mouse, they shall come to an end together," says Yahweh.'),
  ('76268a01-adbb-5fd0-a278-060341e5b014', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 18, 18, '"For I [know] their works and their thoughts: [the time] comes, that I will gather all nations and languages; and they shall come, and shall see my glory.'),
  ('f57bf2ea-6f1d-5c48-a244-115df5ec7cae', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 19, 19, '"I will set a sign among them, and I will send such as escape of them to the nations, to Tarshish, Pul, and Lud, who draw the bow, to Tubal and Javan, to the islands afar off, who have not heard my fame, neither have seen my glory; and they shall declare my glory among the nations.'),
  ('53f5787b-9def-583d-ad38-1fa94bcaed06', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 20, 20, 'They shall bring all your brothers out of all the nations for an offering to Yahweh, on horses, and in chariots, and in litters, and on mules, and on dromedaries, to my holy mountain Jerusalem, says Yahweh, as the children of Israel bring their offering in a clean vessel into the house of Yahweh.'),
  ('6e4f7098-0d12-5324-a391-f5f0d804bb8f', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 21, 21, 'Of them also will I take for priests [and] for Levites," says Yahweh.'),
  ('dbbe4fa3-82d3-5345-a3e9-18ef70cdf3f7', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 22, 22, '"For as the new heavens and the new earth, which I will make, shall remain before me," says Yahweh, "so your seed and your name shall remain.'),
  ('b4018dff-37fa-5d37-a925-5018898a06f3', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 23, 23, 'It shall happen, that from one new moon to another, and from one Sabbath to another, shall all flesh come to worship before me," says Yahweh.'),
  ('5071f4b4-a26d-5e18-afa3-6964b9addfa4', '7ce8528f-6aa4-57d1-ae92-d052f5f37b86', NULL, 24, 24, '"They shall go forth, and look on the dead bodies of the men who have transgressed against me: for their worm shall not die, neither shall their fire be quenched; and they will be loathsome to all mankind."'),
  ('ca359796-0643-5c1f-a1ca-f0006b103557', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 1, 1, 'The words of Jeremiah the son of Hilkiah, of the priests who were in Anathoth in the land of Benjamin:'),
  ('94a4cdea-829f-54db-aa11-ff5cc5d6f4f2', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 2, 2, 'to whom the word of Yahweh came in the days of Josiah the son of Amon, king of Judah, in the thirteenth year of his reign.'),
  ('02c08642-6486-538a-a13f-cd4205e42fa9', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 3, 3, 'It came also in the days of Jehoiakim the son of Josiah, king of Judah, to the end of the eleventh year of Zedekiah, the son of Josiah, king of Judah, to the carrying away of Jerusalem captive in the fifth month.'),
  ('4eb76f58-fd8c-5f48-a8fd-a00ade829947', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 4, 4, 'Now the word of Yahweh came to me, saying,'),
  ('5d9a363b-da4d-5635-adf0-03ab347fa5df', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 5, 5, '"Before I formed you in the belly, I knew you. Before you came forth out of the womb, I sanctified you. I have appointed you a prophet to the nations."'),
  ('57d27ee3-6096-543e-ab07-918510093b3b', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 6, 6, 'Then I said, "Ah, Lord Yahweh! Behold, I don''t know how to speak; for I am a child."'),
  ('8ecafd9a-4f75-556f-aacb-007b237bbb65', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 7, 7, 'But Yahweh said to me, "Don''t say, ''I am a child;'' for to whoever I shall send you, you shall go, and whatever I shall command you, you shall speak.'),
  ('28665dc2-db56-5bea-a333-263fe0f9f38f', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 8, 8, 'Don''t be afraid because of them; for I am with you to deliver you," says Yahweh.'),
  ('c8f571b4-93d1-5bf7-ad5d-1eafd01008ed', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 9, 9, 'Then Yahweh put forth his hand, and touched my mouth; and Yahweh said to me, "Behold, I have put my words in your mouth.'),
  ('0fd407d6-c8cf-5898-af9f-b3f9e1f989d8', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 10, 10, 'Behold, I have this day set you over the nations and over the kingdoms, to pluck up and to break down and to destroy and to overthrow, to build and to plant."'),
  ('5004c552-329f-50eb-a2f6-a27576595475', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 11, 11, 'Moreover the word of Yahweh came to me, saying, "Jeremiah, what do you see?" I said, "I see a branch of an almond tree."'),
  ('c1092895-e962-53f7-a400-e1ed24f69e2b', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 12, 12, 'Then Yahweh said to me, "You have seen well; for I watch over my word to perform it."'),
  ('863dd8de-e448-5534-a0c1-fae6ed7668fe', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 13, 13, 'The word of Yahweh came to me the second time, saying, "What do you see?" I said, "I see a boiling caldron; and it is tipping away from the north."'),
  ('c72526da-4887-5e7d-aecb-f9668a23a2a3', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 14, 14, 'Then Yahweh said to me, "Out of the north evil will break out on all the inhabitants of the land.'),
  ('05378646-a1a9-5461-a9f8-419116b0b039', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 15, 15, 'For, behold, I will call all the families of the kingdoms of the north," says Yahweh; "and they shall come, and they shall each set his throne at the entrance of the gates of Jerusalem, and against all its walls all around, and against all the cities of Judah.'),
  ('66a7a2c6-c5f1-51e1-a866-92846a8de39e', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 16, 16, 'I will utter my judgments against them touching all their wickedness, in that they have forsaken me, and have burned incense to other gods, and worshiped the works of their own hands.'),
  ('9285322d-7a02-508c-a878-2da7ba6a6705', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 17, 17, '"You therefore put your belt on your waist, arise, and speak to them all that I command you. Don''t be dismayed at them, lest I dismay you before them.'),
  ('7e0bedc2-5d97-5dda-a0af-b98d038c6843', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 18, 18, 'For, behold, I have made you this day a fortified city, and an iron pillar, and bronze walls, against the whole land, against the kings of Judah, against its princes, against its priests, and against the people of the land.'),
  ('e285d4ca-1f86-52d5-a727-72f216fa3ea9', '2b48a747-5387-57be-a02c-af0a79dead37', NULL, 19, 19, 'They will fight against you; but they will not prevail against you; for I am with you," says Yahweh, "to deliver you."'),
  ('1b1ff3b8-7743-54cd-ac65-4a544dff5ca9', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('5500d407-5df9-59f2-a3fb-1d1dc72f935c', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 2, 2, '"Go, and cry in the ears of Jerusalem, saying, ''Thus says Yahweh, "I remember for you the kindness of your youth, the love of your weddings; how you went after me in the wilderness, in a land that was not sown.'),
  ('417d0927-5240-5d3e-a2b2-00ff3a797fa6', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 3, 3, 'Israel [was] holiness to Yahweh, the first fruits of his increase. All who devour him shall be held guilty. Evil shall come on them,"'' says Yahweh."'),
  ('cb2613ee-d40e-5075-afdc-d81272f365a9', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 4, 4, 'Hear the word of Yahweh, O house of Jacob, and all the families of the house of Israel!'),
  ('b50b5021-b123-5209-ac82-8ea07bfc9e61', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 5, 5, 'Thus says Yahweh, "What unrighteousness have your fathers found in me, that they have gone far from me, and have walked after vanity, and are become vain?'),
  ('21a4f1d8-ed7c-5e39-a105-a65a28a5175f', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 6, 6, 'Neither did they say, ''Where is Yahweh who brought us up out of the land of Egypt, who led us through the wilderness, through a land of deserts and of pits, through a land of drought and of the shadow of death, through a land that none passed through, and where no man lived?'''),
  ('ccdb08a0-6937-580c-a187-1920d768f83c', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 7, 7, 'I brought you into a plentiful land, to eat its fruit and its goodness; but when you entered, you defiled my land, and made my heritage an abomination.'),
  ('b948088c-871d-527a-ae90-1c431062ebde', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 8, 8, 'The priests didn''t say, ''Where is Yahweh?'' and those who handle the law didn''t know me. The rulers also transgressed against me, and the prophets prophesied by Baal, and walked after things that do not profit.'),
  ('784e0fea-75aa-5bf3-a3e0-13707aa4f47b', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 9, 9, '"Therefore I will yet contend with you," says Yahweh, "and I will contend with your children''s children.'),
  ('ad5c78e1-8258-5e37-ac78-3e8bc270736e', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 10, 10, 'For pass over to the islands of Kittim, and see; and send to Kedar, and consider diligently; and see if there has been such a thing.'),
  ('45c60a2b-851d-51dd-a851-2a748c4c5c07', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 11, 11, 'Has a nation changed [its] gods, which really are no gods? But my people have changed their glory for that which does not profit.'),
  ('d9481501-c492-5ec6-a6a7-441449c5514e', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 12, 12, '"Be astonished, you heavens, at this, and be horribly afraid. Be very desolate," says Yahweh.'),
  ('51f2da35-2849-57bf-abb0-dddc592e2478', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 13, 13, '"For my people have committed two evils: they have forsaken me, the spring of living waters, and cut them out cisterns, broken cisterns, that can hold no water.'),
  ('8e258367-961f-5312-af94-495f4f1b0c5e', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 14, 14, 'Is Israel a servant? Is he a native-born [slave]? Why has he become a prey?'),
  ('6584cc12-2d92-5a8c-a7d8-2976a42d8e16', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 15, 15, 'The young lions have roared at him, and yelled. They have made his land waste. His cities are burned up, without inhabitant.'),
  ('22539305-3759-569f-a151-b79fb3e29a7d', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 16, 16, 'The children also of Memphis and Tahpanhes have broken the crown of your head.'),
  ('f80b872d-9b97-5bf1-a431-572d63a3bdf3', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 17, 17, '"Haven''t you procured this to yourself, in that you have forsaken Yahweh your God, when he led you by the way?'),
  ('1f13ece6-43e4-5c7d-ad09-f807c4d5e900', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 18, 18, 'Now what have you to do in the way to Egypt, to drink the waters of the Shihor? Or what have you to do in the way to Assyria, to drink the waters of the River?'),
  ('09374374-d470-5f6b-a597-bbcd3b270578', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 19, 19, '"Your own wickedness shall correct you, and your backsliding shall reprove you. Know therefore and see that it is an evil thing and a bitter, that you have forsaken Yahweh your God, and that my fear is not in you," says the Lord, Yahweh of Armies.'),
  ('271064b0-08dd-544b-ae88-05b47c696610', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 20, 20, '"For of old time I have broken your yoke, and burst your bonds; and you said, ''I will not serve;'' for on every high hill and under every green tree you bowed yourself, playing the prostitute.'),
  ('b3ff8ce5-7980-5e7e-a65f-b78106cb1c3b', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 21, 21, 'Yet I had planted you a noble vine, wholly a right seed. How then have you turned into the degenerate branches of a foreign vine to me?'),
  ('66c1c32c-519a-596d-af71-bfbb758cefda', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 22, 22, 'For though you wash yourself with lye, and use much soap, yet your iniquity is marked before me," says the Lord Yahweh.'),
  ('7c411d05-3332-55ba-a988-6ebdf4205b34', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 23, 23, '"How can you say, ''I am not defiled. I have not gone after the Baals''? See your way in the valley. Know what you have done. [You are] a swift dromedary traversing her ways;'),
  ('ddcdbdc7-8da5-587e-a112-e498c7701c98', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 24, 24, 'a wild donkey used to the wilderness, that snuffs up the wind in her desire. When she is in heat, who can turn her away? All those who seek her will not weary themselves. In her month, they will find her.'),
  ('3005af16-e3b4-5b12-a15f-622d9be905b0', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 25, 25, '"Withhold your foot from being unshod, and your throat from thirst. But you said, ''It is in vain. No, for I have loved strangers, and I will go after them.'''),
  ('ae0319a9-a841-5857-a286-72afe254ce20', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 26, 26, 'As the thief is ashamed when he is found, so is the house of Israel ashamed; they, their kings, their princes, and their priests, and their prophets;'),
  ('7aff23fb-28bd-5b66-a335-435b5f212eb8', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 27, 27, 'who tell wood, ''You are my father;'' and a stone, ''You have brought me out:'' for they have turned their back to me, and not their face; but in the time of their trouble they will say, ''Arise, and save us.'''),
  ('d62babd0-4cf6-50a7-a328-a3e06f922990', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 28, 28, '"But where are your gods that you have made for yourselves? Let them arise, if they can save you in the time of your trouble: for according to the number of your cities are your gods, Judah.'),
  ('78d603ba-a77a-5de2-a5d4-4bca036bc3e7', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 29, 29, '"Why will you contend with me? You all have transgressed against me," says Yahweh.'),
  ('86f7feb9-3a24-5d7c-a260-deb8b16c060d', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 30, 30, '"I have struck your children in vain. They received no correction. Your own sword has devoured your prophets, like a destroying lion.'),
  ('f1ee4e4c-608b-5b48-a253-5a7524b653ef', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 31, 31, 'Generation, consider the word of Yahweh. Have I been a wilderness to Israel? Or a land of thick darkness? Why do my people say, ''We have broken loose. We will come to you no more?'''),
  ('b23a530d-58a3-54e3-a165-7fd95a648118', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 32, 32, '"Can a virgin forget her ornaments, or a bride her attire? Yet my people have forgotten me for days without number.'),
  ('a86325ac-ebcf-5cf5-a0ba-fe552bd9a5bb', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 33, 33, 'How well you prepare your way to seek love! Therefore you have taught even the wicked women your ways.'),
  ('524d8f33-07df-5255-a8ee-8c076ab33bf9', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 34, 34, 'Also the blood of the souls of the innocent poor is found in your skirts. You did not find them breaking in; but it is because of all these things.'),
  ('9339a48b-9d26-58c4-affb-fe34ea495f55', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 35, 35, '"Yet you said, ''I am innocent. Surely his anger has turned away from me.'' "Behold, I will judge you, because you say, ''I have not sinned.'''),
  ('6d1bb025-8aaa-5d29-a555-7e030825c874', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 36, 36, 'Why do you go about so much to change your way? You will be ashamed of Egypt also, as you were ashamed of Assyria.'),
  ('cf94eea4-7f68-54ba-a9c0-ec004b48969b', '8dc8e65e-f2bb-5ea8-abed-4e9e542d0aef', NULL, 37, 37, 'From there also you shall go forth, with your hands on your head; for Yahweh has rejected those in whom you trust, and you shall not prosper with them.'),
  ('44b2a6d4-8fb8-5d88-a2a3-7dc176d98aa9', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 1, 1, '"They say, ''If a man puts away his wife, and she goes from him, and become another man''s, will he return to her again?'' Wouldn''t that land be greatly polluted? But you have played the prostitute with many lovers; yet return again to me," says Yahweh.'),
  ('6d463096-eb43-5d99-a896-69cb247b0805', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 2, 2, '"Lift up your eyes to the bare heights, and see! Where have you not been lain with? You have sat for them by the ways, as an Arabian in the wilderness. You have polluted the land with your prostitution and with your wickedness.'),
  ('4efa7aea-9da8-5461-a511-b4ee4b81abdf', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 3, 3, 'Therefore the showers have been withheld, and there has been no latter rain; yet you have a prostitute''s forehead, you refused to be ashamed.'),
  ('541e4cad-9bac-5395-ae4e-15bc01e75292', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 4, 4, 'Will you not from this time cry to me, ''My Father, you are the guide of my youth?'''),
  ('92cad8ca-5111-595b-a332-4ce340456ab5', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 5, 5, '"''Will he retain [his anger] forever? Will he keep it to the end?'' Behold, you have spoken and have done evil things, and have had your way."'),
  ('259362b3-f187-54d8-a065-4fe154e46c68', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 6, 6, 'Moreover, Yahweh said to me in the days of Josiah the king, "Have you seen that which backsliding Israel has done? She has gone up on every high mountain and under every green tree, and there has played the prostitute.'),
  ('d8fd23d3-f857-5498-aa7c-6542ba8139f7', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 7, 7, 'I said after she had done all these things, ''She will return to me;'' but she didn''t return; and her treacherous sister Judah saw it.'),
  ('b25af4a4-fab8-5d7c-a150-8854b3015bc0', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 8, 8, 'I saw, when, for this very cause that backsliding Israel had committed adultery, I had put her away and given her a bill of divorce, yet treacherous Judah, her sister, didn''t fear; but she also went and played the prostitute.'),
  ('a7a74eb6-0fa3-5230-a932-b096c0cfbf49', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 9, 9, 'It happened through the lightness of her prostitution, that the land was polluted, and she committed adultery with stones and with stocks.'),
  ('eb7734f3-956b-53ad-aed4-49a25d48513f', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 10, 10, 'Yet for all this her treacherous sister, Judah, has not returned to me with her whole heart, but only in pretense," says Yahweh.'),
  ('e6d96cc3-9b44-5a8f-a473-d3d7c819a621', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 11, 11, 'Yahweh said to me, "Backsliding Israel has shown herself more righteous than treacherous Judah.'),
  ('70db85f9-2539-5ab9-a43c-210da3459556', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 12, 12, 'Go, and proclaim these words toward the north, and say, ''Return, you backsliding Israel,'' says Yahweh; ''I will not look in anger on you; for I am merciful,'' says Yahweh. ''I will not keep [anger] forever.'),
  ('301b7f95-a171-5a8c-aef9-7823415a472c', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 13, 13, 'Only acknowledge your iniquity, that you have transgressed against Yahweh your God, and have scattered your ways to the strangers under every green tree, and you have not obeyed my voice,'' says Yahweh."'),
  ('d98bd2cd-8ffd-58c0-a478-9240202a00dc', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 14, 14, '"Return, backsliding children," says Yahweh; "for I am a husband to you. I will take you one of a city, and two of a family, and I will bring you to Zion.'),
  ('70069d68-dc04-5020-a535-4f8e3ea773c8', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 15, 15, 'I will give you shepherds according to my heart, who shall feed you with knowledge and understanding.'),
  ('183e9fda-7efc-5327-aaae-a737cc34528f', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 16, 16, 'It shall come to pass, when you are multiplied and increased in the land, in those days," says Yahweh, "they shall say no more, ''The ark of the covenant of Yahweh!'' neither shall it come to mind; neither shall they remember it; neither shall they miss it; neither shall it be made any more.'),
  ('d35e436d-b443-5a9e-ab4d-5920bdeec14e', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 17, 17, 'At that time they shall call Jerusalem ''The throne of Yahweh;'' and all the nations shall be gathered to it, to the name of Yahweh, to Jerusalem. Neither shall they walk any more after the stubbornness of their evil heart.'),
  ('9659918e-3ffc-5196-a306-6b23030d1cf3', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 18, 18, 'In those days the house of Judah shall walk with the house of Israel, and they shall come together out of the land of the north to the land that I gave for an inheritance to your fathers.'),
  ('e07ca15e-bc42-5357-aebd-16b492d3880f', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 19, 19, '"But I said, ''How I would put you among the children, and give you a pleasant land, a goodly heritage of the armies of the nations!'' and I said, ''You shall call me "My Father," and shall not turn away from following me.'''),
  ('6eeebecd-d24b-548c-afb0-56227698741c', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 20, 20, '"Surely as a wife treacherously departs from her husband, so you have dealt treacherously with me, house of Israel," says Yahweh.'),
  ('056e025e-f1a7-5574-a4f5-c76b2a3314aa', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 21, 21, 'A voice is heard on the bare heights, the weeping [and] the petitions of the children of Israel; because they have perverted their way, they have forgotten Yahweh their God.'),
  ('932f2c60-c2f4-5a5e-a71e-79ac46427d87', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 22, 22, 'Return, you backsliding children, I will heal your backsliding. "Behold, we have come to you; for you are Yahweh our God.'),
  ('dbbcef43-b388-5485-a73b-e74863079557', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 23, 23, 'Truly in vain is [the help that is looked for] from the hills, the tumult on the mountains. Truly the salvation of Israel is in Yahweh our God.'),
  ('a3af5cbc-4087-5761-a0c9-521de707e81c', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 24, 24, 'But the shameful thing has devoured the labor of our fathers from our youth, their flocks and their herds, their sons and their daughters.'),
  ('0d7f1c82-5841-5d3a-a896-d928596f641b', '2b11c145-0d93-5faa-a044-9fb29fb3129f', NULL, 25, 25, 'Let us lie down in our shame, and let our confusion cover us; for we have sinned against Yahweh our God, we and our fathers, from our youth even to this day. We have not obeyed the voice of Yahweh our God."'),
  ('624f6ccb-0a54-55e2-ab9b-a1d95c18e626', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 1, 1, '"If you will return, Israel," says Yahweh, "if you will return to me, and if you will put away your abominations out of my sight; then you shall not be removed;'),
  ('f18990e7-c888-5a21-a742-31e6603bfbd0', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 2, 2, 'and you shall swear, ''As Yahweh lives,'' in truth, in justice, and in righteousness. The nations shall bless themselves in him, and in him shall they glory."'),
  ('882f52bb-9626-5a62-a049-9d90a9030d4f', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 3, 3, 'For thus says Yahweh to the men of Judah and to Jerusalem, "Break up your fallow ground, and don''t sow among thorns.'),
  ('7e1208ec-c329-5152-aabc-ac4f2d576005', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 4, 4, 'Circumcise yourselves to Yahweh, and take away the foreskins of your heart, you men of Judah and inhabitants of Jerusalem; lest my wrath go forth like fire, and burn so that none can quench it, because of the evil of your doings.'),
  ('beeb0a39-45da-5e7c-a051-267d29882909', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 5, 5, 'Declare in Judah, and publish in Jerusalem; and say, ''Blow the trumpet in the land!'' Cry aloud and say, ''Assemble yourselves! Let us go into the fortified cities!'''),
  ('a0de3688-4c75-5858-abb2-787cea5778d6', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 6, 6, 'Set up a standard toward Zion. Flee for safety! Don''t wait; for I will bring evil from the north, and a great destruction."'),
  ('5fd9fc50-0826-57eb-abd4-70314e5000b3', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 7, 7, 'A lion is gone up from his thicket, and a destroyer of nations; he is on his way, he is gone forth from his place, to make your land desolate, that your cities be laid waste, without inhabitant.'),
  ('dcab4ba3-f802-5597-a5ca-3d2f5295e86f', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 8, 8, 'For this clothe yourself with sackcloth, lament and wail; for the fierce anger of Yahweh hasn''t turned back from us.'),
  ('18000e63-c013-52d1-a4e0-f3f48a85dc70', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 9, 9, '"It shall happen at that day," says Yahweh, "that the heart of the king shall perish, and the heart of the princes; and the priests shall be astonished, and the prophets shall wonder."'),
  ('fb0335dd-97cd-5ba9-a13a-b710898602a0', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 10, 10, 'Then I said, "Ah, Lord Yahweh! Surely you have greatly deceived this people and Jerusalem, saying, ''You shall have peace;'' whereas the sword reaches to the heart."'),
  ('53fd617e-a8fd-51e1-a41e-0eea3660ea99', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 11, 11, 'At that time shall it be said to this people and to Jerusalem, "A hot wind from the bare heights in the wilderness toward the daughter of my people, not to winnow, nor to cleanse;'),
  ('4a6e208d-5fc3-5611-aecd-a03a6458e86d', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 12, 12, 'a full wind from these shall come for me. Now I will also utter judgments against them."'),
  ('f12b9196-83b6-5765-a02a-b71cba2dc98a', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 13, 13, 'Behold, he shall come up as clouds, and his chariots [shall be] as the whirlwind: his horses are swifter than eagles. Woe to us! For we are ruined.'),
  ('aff07570-0b1d-58e4-ad12-e1ebd470f4d7', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 14, 14, 'Jerusalem, wash your heart from wickedness, that you may be saved. How long shall your evil thoughts lodge within you?'),
  ('f4f77a45-92c3-58ee-a6a5-a7c6ee00bc87', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 15, 15, 'For a voice declares from Dan, and publishes evil from the hills of Ephraim:'),
  ('67a8916c-a86f-59f7-a949-33ff68e40f22', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 16, 16, '"Tell the nations; behold, publish against Jerusalem, ''Watchers come from a far country, and raise their voice against the cities of Judah.'),
  ('990284c1-ea70-597d-a60e-98c40d9e651f', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 17, 17, 'As keepers of a field, they are against her all around, because she has been rebellious against me,''" says Yahweh.'),
  ('15446332-fec2-5e5b-ad0a-560bf890df77', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 18, 18, '"Your way and your doings have brought these things to you. This is your wickedness; for it is bitter, for it reaches to your heart."'),
  ('0b64e6d3-450b-501f-aa9f-ec30aa1d9058', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 19, 19, 'My anguish, my anguish! I am pained at my very heart; my heart is disquieted in me; I can''t hold my peace; because you have heard, O my soul, the sound of the trumpet, the alarm of war.'),
  ('e425feb6-443d-5e21-a478-10a31e4abe06', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 20, 20, 'Destruction on destruction is cried; for the whole land is laid waste: suddenly are my tents destroyed, [and] my curtains in a moment.'),
  ('3556a6b7-cdb8-5a4e-a96f-dbcc5d00fc10', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 21, 21, 'How long shall I see the standard, and hear the sound of the trumpet?'),
  ('9733a722-1983-513d-a5c5-ee260741bb6e', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 22, 22, '"For my people are foolish, they don''t know me. They are foolish children, and they have no understanding. They are skillful in doing evil, but to do good they have no knowledge."'),
  ('e7e51dae-2ef8-5812-af2f-60ee978cbed0', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 23, 23, 'I saw the earth, and, behold, it was waste and void; and the heavens, and they had no light.'),
  ('d67538e4-a9c3-5b71-a061-4ec084c97618', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 24, 24, 'I saw the mountains, and behold, they trembled, and all the hills moved back and forth.'),
  ('ec17cfe3-242c-5352-a9f6-e09d9e8f6236', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 25, 25, 'I saw, and behold, there was no man, and all the birds of the sky had fled.'),
  ('aff107cf-4f7b-5356-a848-fa991be4167f', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 26, 26, 'I saw, and behold, the fruitful field was a wilderness, and all its cities were broken down at the presence of Yahweh, [and] before his fierce anger.'),
  ('c558fadc-e8dc-5453-a5eb-27843daf8734', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 27, 27, 'For thus says Yahweh, "The whole land shall be a desolation; yet will I not make a full end.'),
  ('8b68c780-09b3-5577-a43f-3bc8f5479ac5', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 28, 28, 'For this the earth will mourn, and the heavens above be black; because I have spoken it, I have purposed it, and I have not repented, neither will I turn back from it."'),
  ('ab58271c-05d5-5ac6-a505-9b8f202f64a5', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 29, 29, 'Every city flees for the noise of the horsemen and archers; they go into the thickets, and climb up on the rocks: every city is forsaken, and not a man dwells therein.'),
  ('e6d7dc46-9173-5bf2-a719-5e1797f19b10', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 30, 30, 'You, when you are made desolate, what will you do? Though you clothe yourself with scarlet, though you deck you with ornaments of gold, though you enlarge your eyes with paint, in vain do you make yourself beautiful; [your] lovers despise you, they seek your life.'),
  ('a524775c-2085-5d74-a2e3-ed5b5b05b8b9', 'ab2c9582-1d27-55b7-a763-588b2c334fa9', NULL, 31, 31, 'For I have heard a voice as of a woman in travail, the anguish as of her who brings forth her first child, the voice of the daughter of Zion, who gasps for breath, who spreads her hands, [saying], "Woe is me now! For my soul faints before the murderers."'),
  ('fd846195-9584-5772-af00-65cfb151c2cd', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 1, 1, '"Run back and forth through the streets of Jerusalem, and see now, and know, and seek in the broad places of it, if you can find a man, if there are any who does justly, who seeks truth; and I will pardon her.'),
  ('af412371-7c1a-5387-a205-118f892be473', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 2, 2, 'Though they say, ''As Yahweh lives;'' surely they swear falsely."'),
  ('68b02862-2574-51b2-a857-4a77f08b5a0c', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 3, 3, 'O Yahweh, don''t your eyes look on truth? You have stricken them, but they were not grieved. You have consumed them, but they have refused to receive correction. They have made their faces harder than a rock. They have refused to return.'),
  ('315913c1-88d4-537b-a937-b2f80884e4ee', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 4, 4, 'Then I said, "Surely these are poor. They are foolish; for they don''t know the way of Yahweh, nor the law of their God.'),
  ('879d13b7-9fe3-536a-ada2-086251e4f92e', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 5, 5, 'I will go to the great men, and will speak to them; for they know the way of Yahweh, and the law of their God." But these with one accord have broken the yoke, and burst the bonds.'),
  ('97c62ee9-c8c2-5680-aa78-7ad5cc97b9d9', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 6, 6, 'Therefore a lion out of the forest shall kill them, a wolf of the evenings shall destroy them, a leopard shall watch against their cities; everyone who goes out there shall be torn in pieces; because their transgressions are many, [and] their backsliding is increased.'),
  ('2e461996-5a43-5a4d-a802-d12c7d4ddeff', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 7, 7, '"How can I pardon you? Your children have forsaken me, and sworn by what are no gods. When I had fed them to the full, they committed adultery, and assembled themselves in troops at the prostitutes'' houses.'),
  ('f8a34c5b-b0a1-55e4-a1fb-bf0accf7e6c8', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 8, 8, 'They were as fed horses roaming at large: everyone neighed after his neighbor''s wife.'),
  ('6e649613-e0ff-5ab1-a453-f99aebe483a4', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 9, 9, 'Shouldn''t I punish them for these things?" says Yahweh; "and shouldn''t my soul be avenged on such a nation as this?'),
  ('66fa97bc-afc7-5394-aa8a-224f57024f13', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 10, 10, '"Go up on her walls, and destroy; but don''t make a full end. Take away her branches; for they are not Yahweh''s.'),
  ('0cf24b20-bd97-55cc-aecc-692fcf98c3fb', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 11, 11, 'For the house of Israel and the house of Judah have dealt very treacherously against me," says Yahweh.'),
  ('b53db19f-772a-548c-a7d6-24bb5886ab7a', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 12, 12, 'They have denied Yahweh, and said, "It is not he; neither shall evil come on us; neither shall we see sword nor famine.'),
  ('bff5ec76-f65e-5947-ad22-0fe5e0bbf5e5', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 13, 13, 'The prophets shall become wind, and the word is not in them. Thus shall it be done to them."'),
  ('24be43b4-231f-5a6d-a103-8eaec0d97582', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 14, 14, 'Therefore thus says Yahweh, the God of Armies, "Because you speak this word, behold, I will make my words in your mouth fire, and this people wood, and it shall devour them.'),
  ('35bc1f70-e93e-57e4-a45b-203c525e3124', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 15, 15, 'Behold, I will bring a nation on you from far, house of Israel," says Yahweh. "It is a mighty nation. It is an ancient nation, a nation whose language you don''t know, neither understand what they say.'),
  ('f9bca73e-ceeb-574c-a873-2b97ca318663', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 16, 16, 'Their quiver is an open tomb, they are all mighty men.'),
  ('160d5010-f5f6-5c4f-a22e-15426ee8be77', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 17, 17, 'They shall eat up your harvest, and your bread, [which] your sons and your daughters should eat. They shall eat up your flocks and your herds. They shall eat up your vines and your fig trees. They shall beat down your fortified cities, in which you trust, with the sword.'),
  ('70cbe3dc-d576-522f-ab22-73f35b9d9c26', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 18, 18, '"But even in those days," says Yahweh, "I will not make a full end with you.'),
  ('7d03ca07-46b7-5185-a619-eeaba428607d', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 19, 19, 'It will happen, when you say, ''Why has Yahweh our God done all these things to us?'' Then you shall say to them, ''Just like you have forsaken me, and served foreign gods in your land, so you shall serve strangers in a land that is not yours.'''),
  ('468244a3-d3e3-5d58-a68c-74e221b9d293', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 20, 20, '"Declare this in the house of Jacob, and publish it in Judah, saying,'),
  ('1595ffd0-1876-553a-a1d0-c96dff7dc018', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 21, 21, '''Hear now this, foolish people, and without understanding; who have eyes, and don''t see; who have ears, and don''t hear:'),
  ('1a5171e2-3e73-5b58-ac41-7a4312e80f07', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 22, 22, 'Don''t you fear me?'' says Yahweh ''Won''t you tremble at my presence, who have placed the sand for the bound of the sea, by a perpetual decree, that it can''t pass it? and though its waves toss themselves, yet they can''t prevail; though they roar, yet they can''t pass over it.'''),
  ('6afedb78-6a64-5c84-a4f4-3de6245e33ce', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 23, 23, '"But this people has a revolting and a rebellious heart; they have revolted and gone.'),
  ('c7b945e7-bf79-5e9c-ab28-7dbf97480e0f', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 24, 24, 'Neither do they say in their heart, ''Let us now fear Yahweh our God, who gives rain, both the former and the latter, in its season; who preserves to us the appointed weeks of the harvest.'''),
  ('8967fda2-c89d-546a-a8df-75ddd5f9dcf9', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 25, 25, '"Your iniquities have turned away these things, and your sins have withheld good from you.'),
  ('3b8f4fac-7e3f-58e3-a28b-ee4183f36e13', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 26, 26, 'For among my people are found wicked men. They watch, as fowlers lie in wait. They set a trap. They catch men.'),
  ('09bbad12-5dba-5c84-ab03-1f6939e726cb', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 27, 27, 'As a cage is full of birds, so are their houses full of deceit. Therefore they have become great, and grew rich.'),
  ('b37aeb42-6523-5000-a55d-34df49fe99f8', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 28, 28, 'They have grown fat. They shine; yes, they excell in deeds of wickedness. They don''t plead the cause, the cause of the fatherless, that they may prosper; and they don''t judge the right of the needy.'),
  ('49ccb8a4-2dc8-54bc-a906-7e10cb747022', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 29, 29, '"Shall I not punish for these things?" says Yahweh. "Shall not my soul be avenged on such a nation as this?'),
  ('ea8f325b-d89c-55ae-a0ea-687fd471744b', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 30, 30, '"An astonishing and horrible thing has happened in the land.'),
  ('3fa638e3-587f-5e63-aee9-3479cc33156a', '50405780-8eaa-5706-afcd-fa3d31b5bcf8', NULL, 31, 31, 'The prophets prophesy falsely, and the priests rule by their own authority; and my people love to have it so. What will you do in the end of it?'),
  ('b95a322f-5dba-5027-a1d2-bf7b40c06714', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 1, 1, '"Flee for safety, you children of Benjamin, out of the midst of Jerusalem, and blow the trumpet in Tekoa, and raise up a signal on Beth Haccherem; for evil looks forth from the north, and a great destruction.'),
  ('e7081f12-19ce-538f-aa54-2750b221c29f', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 2, 2, 'The comely and delicate one, the daughter of Zion, will I cut off.'),
  ('5a392900-c2e5-5992-a63a-4f770db4860d', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 3, 3, 'Shepherds with their flocks shall come to her; they shall pitch their tents against her all around; they shall feed everyone in his place."'),
  ('feb89ca2-7181-5a7e-aba1-56737140f14c', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 4, 4, '"Prepare war against her; arise, and let us go up at noon. Woe to us! For the day declines, for the shadows of the evening are stretched out.'),
  ('22f458d9-894e-5301-a1a2-1575702ed4ae', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 5, 5, 'Arise, and let us go up by night, and let us destroy her palaces."'),
  ('01f06239-0cb9-54a9-a5f9-e037fc53e12d', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 6, 6, 'For Yahweh of Armies said, "Cut down trees, and cast up a mound against Jerusalem: this is the city to be visited; she is wholly oppression in the midst of her.'),
  ('ea257f75-97b5-5b90-a48a-af15e7681199', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 7, 7, 'As a well casts forth its waters, so she casts forth her wickedness: violence and destruction is heard in her; before me continually is sickness and wounds.'),
  ('dd435ff2-7bf2-58b2-aee3-36444ed4bb23', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 8, 8, 'Be instructed, Jerusalem, lest my soul be alienated from you; lest I make you a desolation, a land not inhabited."'),
  ('6e72012e-a839-5b51-ae85-4fc849cff117', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 9, 9, 'Thus says Yahweh of Armies, "They shall thoroughly glean the remnant of Israel like a vine. Turn again your hand as a grape gatherer into the baskets."'),
  ('dbce06a9-1069-572c-abe1-78db41b81515', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 10, 10, 'To whom shall I speak and testify, that they may hear? Behold, their ear is uncircumcised, and they can''t listen. Behold, the word of Yahweh has become a reproach to them. They have no delight in it.'),
  ('185f86ff-87f8-5910-a850-027d110aec5e', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 11, 11, 'Therefore I am full of the wrath of Yahweh. I am weary with holding in. "Pour it out on the children in the street, and on the assembly of young men together; for even the husband with the wife shall be taken, the aged with him who is full of days.'),
  ('dc39384b-dfa8-56a4-af73-6bfba0c8a1b5', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 12, 12, 'Their houses shall be turned to others, their fields and their wives together; for I will stretch out my hand on the inhabitants of the land, says Yahweh."'),
  ('616d45fe-9f93-5ba0-a37f-3a1c42d9a116', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 13, 13, '"For from the least of them even to the greatest of them, everyone is given to covetousness; and from the prophet even to the priest, everyone deals falsely.'),
  ('f29b11be-da48-5fce-a2fe-6191fbb92803', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 14, 14, 'They have healed also the hurt of my people superficially, saying, ''Peace, peace!'' when there is no peace.'),
  ('7d3adfd5-bd71-5238-aebf-5ce6adad18ec', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 15, 15, 'Were they ashamed when they had committed abomination? No, they were not at all ashamed, neither could they blush. Therefore they shall fall among those who fall; at the time that I visit them, they shall be cast down," says Yahweh.'),
  ('0bc2435a-1110-5970-aa45-7d58b1e94c53', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 16, 16, 'Thus says Yahweh, "Stand in the ways and see, and ask for the old paths, ''Where is the good way?'' and walk in it, and you will find rest for your souls. But they said, ''We will not walk in it.'''),
  ('72c507e5-a3ad-5294-a590-a0d13938e2e8', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 17, 17, 'I set watchmen over you, saying, ''Listen to the sound of the trumpet!'' But they said, ''We will not listen!'''),
  ('b414e10f-78ad-5c82-a024-a6ce8caf3c24', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 18, 18, 'Therefore hear, you nations, and know, congregation, what is among them.'),
  ('49893d72-f7b1-54f6-aa80-83fef3f44a2b', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 19, 19, 'Hear, earth! Behold, I will bring evil on this people, even the fruit of their thoughts, because they have not listened to my words; and as for my law, they have rejected it.'),
  ('bb628afa-1450-5e8d-a879-8bb26a3a4f8c', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 20, 20, 'To what purpose comes there to me frankincense from Sheba, and the sweet cane from a far country? your burnt offerings are not acceptable, nor your sacrifices pleasing to me."'),
  ('0fb081ed-ae26-59cf-a22e-51253b1e5e91', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 21, 21, 'Therefore thus says Yahweh, "Behold, I will lay stumbling blocks before this people. The fathers and the sons together shall stumble against them. The neighbor and his friend shall perish."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ceb768cf-4e03-52c2-a13f-1f5175df2d06', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 22, 22, 'Thus says Yahweh, "Behold, a people comes from the north country. A great nation shall be stirred up from the uttermost parts of the earth.'),
  ('922d449b-f781-509c-ac81-7024105e9349', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 23, 23, 'They take hold of bow and spear. They are cruel, and have no mercy. Their voice roars like the sea, and they ride on horses, everyone set in array, as a man to the battle, against you, daughter of Zion."'),
  ('945c7445-c2c1-53eb-ac8f-caeb4efc2a89', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 24, 24, 'We have heard its report; our hands wax feeble: anguish has taken hold of us, [and] pangs as of a woman in travail.'),
  ('3ab918ae-00bf-55fc-aa6a-a5fa574b98bf', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 25, 25, 'Don''t go forth into the field, nor walk by the way; for the sword of the enemy, [and] terror, are on every side.'),
  ('4e2c62ee-1b81-5c70-a8ad-56521c898ec4', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 26, 26, 'Daughter of my people, clothe yourself with sackcloth, and wallow in ashes! Mourn, as for an only son, most bitter lamentation; for the destroyer shall suddenly come on us.'),
  ('22fd0677-a5c9-5781-a385-dec3a31a0d6e', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 27, 27, '"I have made you a tester of metals [and] a fortress among my people; that you may know and try their way.'),
  ('c01e8caf-5221-5aae-a925-8d0c3fee3733', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 28, 28, 'They are all grievous rebels, going about with slanders; they are brass and iron: they all of them deal corruptly.'),
  ('f2582c20-c021-5126-a084-0a4b7fc5f766', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 29, 29, 'The bellows blow fiercely; the lead is consumed of the fire: in vain do they go on refining; for the wicked are not plucked away.'),
  ('a8612b96-584d-554a-a766-41816fd09d7e', '544409f9-0f67-5ae5-af6a-5b441ba9ede1', NULL, 30, 30, 'Men will call them rejected silver, because Yahweh has rejected them."'),
  ('4e7a15e0-29f1-5d27-a85a-1e9aa1aa61c2', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 1, 1, 'The word that came to Jeremiah from Yahweh, saying,'),
  ('d1621470-354b-5224-ac28-46a8deb39b1b', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 2, 2, '"Stand in the gate of Yahweh''s house, and proclaim there this word, and say, ''Hear the word of Yahweh, all you of Judah, who enter in at these gates to worship Yahweh.'),
  ('2df5e783-7849-58de-ad87-a606bc8281b8', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 3, 3, 'Thus says Yahweh of Armies, the God of Israel, Amend your ways and your doings, and I will cause you to dwell in this place.'),
  ('8a8e0df0-3836-518c-ad16-2e520d3b81d4', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 4, 4, 'Don''t trust in lying words, saying, The temple of Yahweh, the temple of Yahweh, the temple of Yahweh, are these.'),
  ('4fe8705b-6452-55d3-a388-7fa8b1f1c75f', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 5, 5, 'For if you thoroughly amend your ways and your doings; if you thoroughly execute justice between a man and his neighbor;'),
  ('f080db55-6b65-5ecc-accf-ea45622fe3b2', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 6, 6, 'if you don''t oppress the foreigner, the fatherless, and the widow, and don''t shed innocent blood in this place, neither walk after other gods to your own hurt:'),
  ('398263ad-3980-5087-a585-c913e0ce0ce9', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 7, 7, 'then will I cause you to dwell in this place, in the land that I gave to your fathers, from of old even forevermore.'),
  ('1bda3b6d-7bc5-59e9-ad98-a63c74e996f9', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 8, 8, 'Behold, you trust in lying words, that can''t profit.'),
  ('f1f17bfc-28e7-5ecc-a869-35192dce2781', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 9, 9, 'Will you steal, murder, and commit adultery, and swear falsely, and burn incense to Baal, and walk after other gods that you have not known,'),
  ('564bb820-4f2a-5631-a486-981842c03249', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 10, 10, 'and come and stand before me in this house, which is called by my name, and say, We are delivered; that you may do all these abominations?'),
  ('6382e456-ed4f-510e-a453-74c33ea80d32', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 11, 11, 'Is this house, which is called by my name, become a den of robbers in your eyes? Behold, I, even I, have seen it, says Yahweh.'),
  ('d1aa725e-2a03-521b-a4e9-19fc9030c514', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 12, 12, 'But go now to my place which was in Shiloh, where I caused my name to dwell at the first, and see what I did to it for the wickedness of my people Israel.'),
  ('452e9843-7259-527a-a248-06c1f0e0a2cc', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 13, 13, 'Now, because you have done all these works, says Yahweh, and I spoke to you, rising up early and speaking, but you didn''t hear; and I called you, but you didn''t answer:'),
  ('f62c8389-1b21-5eb2-a21e-4aa2eee70f31', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 14, 14, 'therefore will I do to the house which is called by my name, in which you trust, and to the place which I gave to you and to your fathers, as I did to Shiloh.'),
  ('7238a809-1dc7-543f-a91f-64d49894f998', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 15, 15, 'I will cast you out of my sight, as I have cast out all your brothers, even the whole seed of Ephraim.'),
  ('bda300f9-a1e4-555f-a5bb-ec8aaec38e72', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 16, 16, 'Therefore don''t pray for this people, neither lift up a cry nor prayer for them, neither make intercession to me; for I will not hear you.'),
  ('8495626a-3166-55cd-a3f8-ff98e1358bcc', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 17, 17, 'Don''t you see what they do in the cities of Judah and in the streets of Jerusalem?'),
  ('152fc3f2-704f-5ceb-a71c-682a16142b2b', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 18, 18, 'The children gather wood, and the fathers kindle the fire, and the women knead the dough, to make cakes to the queen of the sky, and to pour out drink offerings to other gods, that they may provoke me to anger.'),
  ('3fd98444-7d46-5354-a5cb-7470244a0dad', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 19, 19, 'Do they provoke me to anger? says Yahweh; [do they] not [provoke] themselves, to the confusion of their own faces?'),
  ('a941c161-68d2-59cf-a1c3-7481c8803d86', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 20, 20, 'Therefore thus says the Lord Yahweh: Behold, my anger and my wrath shall be poured out on this place, on man, and on animal, and on the trees of the field, and on the fruit of the ground; and it shall burn, and shall not be quenched.'),
  ('985e961a-491e-5424-aeef-ff182a243e42', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 21, 21, 'Thus says Yahweh of Armies, the God of Israel: Add your burnt offerings to your sacrifices, and eat meat.'),
  ('82e9419f-653d-5c5f-ac21-1851fa9f3e87', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 22, 22, 'For I didn''t speak to your fathers, nor command them in the day that I brought them out of the land of Egypt, concerning burnt offerings or sacrifices:'),
  ('ec1b0363-4415-5249-a6e7-1479cebfb4cf', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 23, 23, 'but this thing I commanded them, saying, Listen to my voice, and I will be your God, and you shall be my people; and walk in all the way that I command you, that it may be well with you.'),
  ('ad2c6bad-654a-506c-a46a-b89ac8159008', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 24, 24, 'But they didn''t listen nor turn their ear, but walked in [their own] counsels [and] in the stubbornness of their evil heart, and went backward, and not forward.'),
  ('74a4c1b6-d6dd-58ed-a566-1cd4b56a46ae', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 25, 25, 'Since the day that your fathers came forth out of the land of Egypt to this day, I have sent to you all my servants the prophets, daily rising up early and sending them:'),
  ('587f90df-390b-5033-ad2e-7d2030fa694d', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 26, 26, 'yet they didn''t listen to me, nor inclined their ear, but made their neck stiff: they did worse than their fathers.'),
  ('f7aa13f6-6d94-5fdb-a31d-9d1b35debbe0', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 27, 27, 'You shall speak all these words to them; but they will not listen to you: you shall also call to them; but they will not answer you.'),
  ('0e1bb1aa-a07d-5d1f-a92f-21555ab1e288', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 28, 28, 'You shall tell them, This is the nation that has not listened to the voice of Yahweh their God, nor received instruction: truth is perished, and is cut off from their mouth.'),
  ('3b8787c2-2eca-5cbd-afa0-66ad10d0e1ff', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 29, 29, 'Cut off your hair, [Jerusalem], and cast it away, and take up a lamentation on the bare heights; for Yahweh has rejected and forsaken the generation of his wrath.'),
  ('612d8e93-7e93-5144-a9a5-8854f0c77a86', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 30, 30, 'For the children of Judah have done that which is evil in my sight, says Yahweh: they have set their abominations in the house which is called by my name, to defile it.'),
  ('3c456164-c0ef-510b-ac11-96b88fe10ea8', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 31, 31, 'They have built the high places of Topheth, which is in the valley of the son of Hinnom, to burn their sons and their daughters in the fire; which I didn''t command, nor did it come into my mind.'),
  ('4e3d0627-f073-5220-a821-74d106fe2512', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 32, 32, 'Therefore, behold, the days come, says Yahweh, that it shall no more be called Topheth, nor The valley of the son of Hinnom, but The valley of Slaughter: for they shall bury in Topheth, until there be no place [to bury].'),
  ('5c9f20b1-9623-5f98-a625-6ee1a25ea2b8', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 33, 33, 'The dead bodies of this people shall be food for the birds of the sky, and for the animals of the earth; and none shall frighten them away.'),
  ('fe6ac82c-1617-5346-ab37-533ba47bba9c', 'd09561f1-54e2-5d05-a27e-589e27b915ba', NULL, 34, 34, 'Then will I cause to cease from the cities of Judah, and from the streets of Jerusalem, the voice of mirth and the voice of gladness, the voice of the bridegroom and the voice of the bride; for the land shall become a waste.'),
  ('5021c3b4-1f27-54d3-a833-2810e9befeca', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 1, 1, 'At that time, says Yahweh, they shall bring out the bones of the kings of Judah, and the bones of his princes, and the bones of the priests, and the bones of the prophets, and the bones of the inhabitants of Jerusalem, out of their graves;'),
  ('b4de2bec-5aad-51d5-a171-673b926bb25e', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 2, 2, 'and they shall spread them before the sun, and the moon, and all the army of the sky, which they have loved, and which they have served, and after which they have walked, and which they have sought, and which they have worshiped: they shall not be gathered, nor be buried, they shall be for dung on the surface of the earth.'),
  ('493cea39-9898-5488-a8a3-72e2e4e20c3d', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 3, 3, 'Death shall be chosen rather than life by all the residue that remain of this evil family, that remain in all the places where I have driven them, says Yahweh of Armies.'),
  ('517fe2ce-1178-5fec-abc9-a3223d76ca8a', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 4, 4, 'Moreover you shall tell them, Thus says Yahweh: Shall men fall, and not rise up again? Shall one turn away, and not return?'),
  ('d71d8d9d-f1b8-5f60-a2ef-5b84ca932edd', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 5, 5, 'Why then is this people of Jerusalem slidden back by a perpetual backsliding? they hold fast deceit, they refuse to return.'),
  ('0163e407-eec5-5466-a4a1-9406fb42401c', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 6, 6, 'I listened and heard, but they didn''t speak aright: no man repents him of his wickedness, saying, What have I done? everyone turns to his course, as a horse that rushes headlong in the battle.'),
  ('109110ee-8635-58e9-a2b8-66232c23a206', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 7, 7, 'Yes, the stork in the sky knows her appointed times; and the turtledove and the swallow and the crane observe the time of their coming; but my people don''t know Yahweh''s law.'),
  ('f30a1048-c7b5-5754-a5f9-f5fd5df30a8e', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 8, 8, 'How do you say, We are wise, and the law of Yahweh is with us? But, behold, the false pen of the scribes has worked falsely.'),
  ('38a7feab-b2ba-51bd-aab0-30f2331e578f', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 9, 9, 'The wise men are disappointed, they are dismayed and taken: behold, they have rejected the word of Yahweh; and what kind of wisdom is in them?'),
  ('0bd83c26-6305-5a6b-acc7-67b6e3f77007', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 10, 10, 'Therefore will I give their wives to others, and their fields to those who shall possess them: for everyone from the least even to the greatest is given to covetousness; from the prophet even to the priest every one deals falsely.'),
  ('0ea63f77-dbf1-5d32-a7c0-80098e404049', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 11, 11, 'They have healed the hurt of the daughter of my people slightly, saying, Peace, peace; when there is no peace.'),
  ('309cb634-747a-5da3-a323-2e99c5165a5b', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 12, 12, 'Were they ashamed when they had committed abomination? nay, they were not at all ashamed, neither could they blush: therefore shall they fall among those who fall; in the time of their visitation they shall be cast down, says Yahweh.'),
  ('553af732-2da6-58a5-a535-1aa8ef4ed083', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 13, 13, 'I will utterly consume them, says Yahweh: no grapes shall be on the vine, nor figs on the fig tree, and the leaf shall fade; and [the things that] I have given them shall pass away from them.'),
  ('8ff6c655-0c1f-5500-abfd-a96b0a202475', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 14, 14, 'Why do we sit still? Assemble yourselves, and let us enter into the fortified cities, and let us be silent there; for Yahweh our God has put us to silence, and given us water of gall to drink, because we have sinned against Yahweh.'),
  ('99ab3c8b-0b78-5217-aa55-dd8121de4533', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 15, 15, 'We looked for peace, but no good came; [and] for a time of healing, and behold, dismay!'),
  ('7d3c5f66-6235-519e-a75b-6accebced623', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 16, 16, 'The snorting of his horses is heard from Dan: at the sound of the neighing of his strong ones the whole land trembles; for they are come, and have devoured the land and all that is in it; the city and those who dwell therein.'),
  ('b8b8e09d-198f-59db-acbf-59836c45cac2', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 17, 17, 'For, behold, I will send serpents, adders, among you, which will not be charmed; and they shall bite you, says Yahweh.'),
  ('a3309223-769f-5613-a76d-e3c2f30ea9d6', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 18, 18, 'Oh that I could comfort myself against sorrow! My heart is faint within me.'),
  ('e4cfea7e-77c6-5ba8-ad6b-99e5a452dacc', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 19, 19, 'Behold, the voice of the cry of the daughter of my people from a land that is very far off: isn''t Yahweh in Zion? Isn''t her King in her? Why have they provoked me to anger with their engraved images, and with foreign vanities?'),
  ('da6cf6cb-0b13-5b6c-abdf-4d873a1930b6', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 20, 20, 'The harvest is past, the summer is ended, and we are not saved.'),
  ('49a207a7-8a6c-503f-ae64-2674e8e6b995', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 21, 21, 'For the hurt of the daughter of my people am I hurt: I mourn; dismay has taken hold on me.'),
  ('a95a9244-d7f8-5ee2-a510-d4c9a4bd770e', 'aec69adc-c4d3-5392-a8e6-bf7f69cc9035', NULL, 22, 22, 'Is there no balm in Gilead? is there no physician there? why then isn''t the health of the daughter of my people recovered?'),
  ('ba8f402d-5af6-57f0-a797-06b82f04a085', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 1, 1, 'Oh that my head were waters, and my eyes a spring of tears, that I might weep day and night for the slain of the daughter of my people!'),
  ('93ff6350-3476-5454-af6c-27fad4c8fc2d', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 2, 2, 'Oh that I had in the wilderness a lodging place of wayfaring men; that I might leave my people, and go from them! for they are all adulterers, an assembly of treacherous men.'),
  ('cdb9a31f-015b-5b5e-a89a-f84d878bcb66', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 3, 3, 'They bend their tongue, [as it were] their bow, for falsehood; and they are grown strong in the land, but not for truth: for they proceed from evil to evil, and they don''t know me, says Yahweh.'),
  ('d9980320-0391-5147-a39c-11f12733d034', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 4, 4, 'Take heed everyone of his neighbor, and don''t trust in any brother; for every brother will utterly supplant, and every neighbor will go about with slanders.'),
  ('099604a8-239c-5835-a59e-f1b18a233879', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 5, 5, 'They will deceive everyone his neighbor, and will not speak the truth: they have taught their tongue to speak lies; they weary themselves to commit iniquity.'),
  ('52fe444a-6323-5b30-ad8d-964cb6b77a8e', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 6, 6, 'Your habitation is in the midst of deceit; through deceit they refuse to know me, says Yahweh.'),
  ('f0c3296f-7efc-5af1-a3a7-08392bec5871', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 7, 7, 'Therefore thus says Yahweh of Armies, Behold, I will melt them, and try them; for how [else] should I do, because of the daughter of my people?'),
  ('ca8bbefc-8674-559e-aca3-205c1a9d7aef', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 8, 8, 'Their tongue is a deadly arrow; it speaks deceit: one speaks peaceably to his neighbor with his mouth, but in his heart he lays wait for him.'),
  ('76bce731-7638-5c12-a305-e1773457c2c4', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 9, 9, 'Shall I not visit them for these things? says Yahweh; shall not my soul be avenged on such a nation as this?'),
  ('4c3c12c0-b875-5833-abb5-a05105cfb5ce', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 10, 10, 'For the mountains will I take up a weeping and wailing, and for the pastures of the wilderness a lamentation, because they are burned up, so that none passes through; neither can men hear the voice of the livestock; both the birds of the sky and the animals are fled, they are gone.'),
  ('2ee36465-03c6-50ef-af59-d2ed04a03272', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 11, 11, 'I will make Jerusalem heaps, a dwelling place of jackals; and I will make the cities of Judah a desolation, without inhabitant.'),
  ('94961904-80ed-58f6-a474-238a1f9ecaa9', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 12, 12, 'Who is the wise man, that may understand this? and [who is] he to whom the mouth of Yahweh has spoken, that he may declare it? why is the land perished and burned up like a wilderness, so that none passes through?'),
  ('050accdd-69c2-56c4-aa28-8fb2a134d7cc', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 13, 13, 'Yahweh says, Because they have forsaken my law which I set before them, and have not obeyed my voice, neither walked therein,'),
  ('942e93cc-ff72-569d-a9c6-a54dcfc1f4df', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 14, 14, 'but have walked after the stubbornness of their own heart, and after the Baals, which their fathers taught them;'),
  ('3453a152-d6bc-5bf7-a587-5cddf9e5d8cc', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 15, 15, 'therefore thus says Yahweh of Armies, the God of Israel, Behold, I will feed them, even this people, with wormwood, and give them water of gall to drink.'),
  ('338c4af2-2baf-5ed4-aa3b-8b60483f16ca', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 16, 16, 'I will scatter them also among the nations, whom neither they nor their fathers have known; and I will send the sword after them, until I have consumed them.'),
  ('a5688fbd-f667-5f90-a334-c8bf876fbfc1', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 17, 17, 'Thus says Yahweh of Armies, Consider, and call for the mourning women, that they may come; and send for the skillful women, that they may come:'),
  ('660679b3-30d9-5555-a7b1-22802d21545a', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 18, 18, 'and let them make haste, and take up a wailing for us, that our eyes may run down with tears, and our eyelids gush out with waters.'),
  ('11234288-33ce-526a-a557-57f7f8753394', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 19, 19, 'For a voice of wailing is heard out of Zion, How are we ruined! we are greatly confounded, because we have forsaken the land, because they have cast down our dwellings.'),
  ('a3816226-ac80-5147-ae8d-cb0005b983a4', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 20, 20, 'Yet hear the word of Yahweh, you women, and let your ear receive the word of his mouth; and teach your daughters wailing, and everyone her neighbor lamentation.'),
  ('101e40f8-f5c9-5ab4-afe1-e60013c7a0cd', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 21, 21, 'For death is come up into our windows, it is entered into our palaces; to cut off the children from outside, [and] the young men from the streets.'),
  ('4ef37e60-7829-5734-a6b6-eb564b093e04', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 22, 22, 'Speak, Thus says Yahweh, The dead bodies of men shall fall as dung on the open field, and as the handful after the harvester; and none shall gather [them].'),
  ('e6bb69b2-2f87-575d-a8e4-841047a176cf', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 23, 23, 'Thus says Yahweh, Don''t let the wise man glory in his wisdom, neither let the mighty man glory in his might, don''t let the rich man glory in his riches;'),
  ('5bf13161-e17b-53ff-a5e8-a2a51aec3ad0', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 24, 24, 'but let him who glories glory in this, that he has understanding, and knows me, that I am Yahweh who exercises loving kindness, justice, and righteousness, in the earth: for in these things I delight, says Yahweh.'),
  ('4a7ca10b-3766-5327-a102-4bb7ab5876e8', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 25, 25, 'Behold, the days come, says Yahweh, that I will punish all those who are circumcised in [their] uncircumcision:'),
  ('771c469c-2311-59c4-a2ef-955446b9a0bf', '46366d5f-bf9f-5fe8-a696-045384f2cce3', NULL, 26, 26, 'Egypt, and Judah, and Edom, and the children of Ammon, and Moab, and all that have the corners [of their hair] cut off, who dwell in the wilderness; for all the nations are uncircumcised, and all the house of Israel are uncircumcised in heart.'),
  ('6a8c6419-7ea9-5804-ac38-240e92fd486b', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 1, 1, 'Hear the word which Yahweh speaks to you, house of Israel!'),
  ('b6f70163-16a0-583c-a8c7-3eea66448498', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 2, 2, 'Thus says Yahweh, "Don''t learn the way of the nations, and don''t be dismayed at the signs of the sky; for the nations are dismayed at them.'),
  ('a12a8db4-673d-54af-acb5-614bf97bcba2', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 3, 3, 'For the customs of the peoples are vanity; for one cuts a tree out of the forest, the work of the hands of the workman with the axe.'),
  ('3a53e8da-16d9-59ff-aab4-4ea58bfea121', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 4, 4, 'They deck it with silver and with gold; they fasten it with nails and with hammers, that it not move.'),
  ('56be7267-133a-5a60-aaf5-36f826e93939', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 5, 5, 'They are like a palm tree, of turned work, and don''t speak: they must be carried, because they can''t go. Don''t be afraid of them; for they can''t do evil, neither is it in them to do good."'),
  ('a3831ecb-b654-5ad7-a601-513203b8e863', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 6, 6, 'There is none like you, Yahweh; you are great, and your name is great in might.'),
  ('196d3c1f-655a-5294-ab0b-171271bc0512', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 7, 7, 'Who should not fear you, King of the nations? For it appertains to you; because among all the wise men of the nations, and in all their royal estate, there is none like you.'),
  ('14701f6d-ff7a-544a-a1aa-177604571aa0', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 8, 8, 'But they are together brutish and foolish: the instruction of idols! it is but a stock.'),
  ('3853d547-7d7e-5b9c-ae9e-a4298fd99d0c', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 9, 9, 'There is silver beaten into plates, which is brought from Tarshish, and gold from Uphaz, the work of the artificer and of the hands of the goldsmith; blue and purple for their clothing; they are all the work of skillful men.'),
  ('d682dfe2-a105-5ce9-a7f9-323dab2e60a3', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 10, 10, 'But Yahweh is the true God; he is the living God, and an everlasting King: at his wrath the earth trembles, and the nations are not able to withstand his indignation.'),
  ('7b2b5840-9ad8-55b6-a436-9353b5966074', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 11, 11, 'You shall say this to them: The gods that have not made the heavens and the earth, these shall perish from the earth, and from under the heavens.'),
  ('a45a995b-771e-500c-a30b-a6ba378a8211', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 12, 12, 'He has made the earth by his power, he has established the world by his wisdom, and by his understanding has he stretched out the heavens:'),
  ('a1fec3b0-3368-5cd9-ae02-3cb8ad7f82d4', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 13, 13, 'when he utters his voice, there is a tumult of waters in the heavens, and he causes the vapors to ascend from the ends of the earth; he makes lightnings for the rain, and brings forth the wind out of his treasuries.'),
  ('3e26a2c9-97a7-565f-a746-021f940f79b1', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 14, 14, 'Every man is become brutish [and is] without knowledge; every goldsmith is disappointed by his engraved image; for his molten image is falsehood, and there is no breath in them.'),
  ('9d59e3cd-60ce-5aca-abd6-ae5f899d0f93', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 15, 15, 'They are vanity, a work of delusion: in the time of their visitation they shall perish.'),
  ('a4c7a0eb-d470-5cdc-a83f-d45ccecfaa82', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 16, 16, 'The portion of Jacob is not like these; for he is the former of all things; and Israel is the tribe of his inheritance: Yahweh of Armies is his name.'),
  ('e5a3b8c3-dae0-5eee-ad23-f5f7b145b509', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 17, 17, 'Gather up your wares out of the land, you who live under siege.'),
  ('255ad059-03bb-5df2-a793-c85b0951b990', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 18, 18, 'For thus says Yahweh, Behold, I will sling out the inhabitants of the land at this time, and will distress them, that they may feel [it].'),
  ('24f862e2-915b-5f00-ab43-01768b50f444', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 19, 19, 'Woe is me because of my hurt! my wound is grievous: but I said, Truly this is [my] grief, and I must bear it.'),
  ('f5aed825-0304-5ade-aa9c-11c26725a135', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 20, 20, 'My tent is destroyed, and all my cords are broken: my children are gone forth from me, and they are no more: there is none to spread my tent any more, and to set up my curtains.'),
  ('ecfa52d1-053a-5b7a-a39a-54a9d4e944af', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 21, 21, 'For the shepherds are become brutish, and have not inquired of Yahweh: therefore they have not prospered, and all their flocks are scattered.'),
  ('8fd131c6-ec94-5cf4-a077-2e96fcf09982', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 22, 22, 'The voice of news, behold, it comes, and a great commotion out of the north country, to make the cities of Judah a desolation, a dwelling place of jackals.'),
  ('74bce607-adcf-53b2-abd1-c8fd0cd7be79', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 23, 23, 'Yahweh, I know that the way of man is not in himself: it is not in man who walks to direct his steps.'),
  ('b4ac1229-f864-5ad5-a214-6657020af85a', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 24, 24, 'Yahweh, correct me, but in measure: not in your anger, lest you bring me to nothing.'),
  ('9632e70e-d415-5d99-ab28-5fc9489f3c9b', 'b00bcf6d-8114-5c49-a17e-4afcd27f93c3', NULL, 25, 25, 'Pour out your wrath on the nations that don''t know you, and on the families that don''t call on your name: for they have devoured Jacob, yes, they have devoured him and consumed him, and have laid waste his habitation.'),
  ('884082f4-54e7-59e9-aa02-cb05e5677092', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 1, 1, 'The word that came to Jeremiah from Yahweh, saying,'),
  ('e6bbeed6-93bb-5972-ab29-ee6de0465b2d', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 2, 2, 'Hear the words of this covenant, and speak to the men of Judah, and to the inhabitants of Jerusalem;'),
  ('aeeff617-3733-5d20-a02a-14ec40189c34', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 3, 3, 'and say to them, Thus says Yahweh, the God of Israel: Cursed is the man who doesn''t hear the words of this covenant,'),
  ('84fdd1d3-b8b2-57ed-a073-6ed8d33d0fd3', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 4, 4, 'which I commanded your fathers in the day that I brought them forth out of the land of Egypt, out of the iron furnace, saying, Obey my voice, and do them, according to all which I command you: so you shall be my people, and I will be your God;'),
  ('ff8eca9b-2c58-51d6-acfc-fd1ec78865cb', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 5, 5, 'that I may establish the oath which I swore to your fathers, to give them a land flowing with milk and honey, as at this day. Then answered I, and said, Amen, Yahweh.'),
  ('72257f5d-8ffd-5b23-aa10-8e21b664d55b', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 6, 6, 'Yahweh said to me, Proclaim all these words in the cities of Judah, and in the streets of Jerusalem, saying, Hear the words of this covenant, and do them.'),
  ('9b70bef6-dac0-5d80-a634-ae130437f857', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 7, 7, 'For I earnestly protested to your fathers in the day that I brought them up out of the land of Egypt, even to this day, rising early and protesting, saying, Obey my voice.'),
  ('3e0ab44d-5bbc-5fac-a9b6-26c00e118cf1', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 8, 8, 'Yet they didn''t obey, nor turn their ear, but walked everyone in the stubbornness of their evil heart: therefore I brought on them all the words of this covenant, which I commanded them to do, but they didn''t do them.'),
  ('a264b893-1509-5554-a215-2e3e60d0eccf', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 9, 9, 'Yahweh said to me, A conspiracy is found among the men of Judah, and among the inhabitants of Jerusalem.'),
  ('cd63ea92-7299-5fc6-abb5-51cf4c87a731', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 10, 10, 'They are turned back to the iniquities of their forefathers, who refused to hear my words; and they are gone after other gods to serve them: the house of Israel and the house of Judah have broken my covenant which I made with their fathers.'),
  ('0e0e5d15-7c4b-5ac9-a759-735909b58db0', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 11, 11, 'Therefore thus says Yahweh, Behold, I will bring evil on them, which they shall not be able to escape; and they shall cry to me, but I will not listen to them.'),
  ('4780bd53-2585-5ac8-ab5b-001935f51af3', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 12, 12, 'Then shall the cities of Judah and the inhabitants of Jerusalem go and cry to the gods to which they offer incense: but they will not save them at all in the time of their trouble.'),
  ('37655108-4420-57e2-a056-a4542ee649f5', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 13, 13, 'For according to the number of your cities are your gods, Judah; and according to the number of the streets of Jerusalem have you set up altars to the shameful thing, even altars to burn incense to Baal.'),
  ('82f09800-d56a-5caa-afd0-a7b3b01484ed', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 14, 14, 'Therefore don''t pray for this people, neither lift up cry nor prayer for them; for I will not hear them in the time that they cry to me because of their trouble.'),
  ('43164ade-5f7b-5f4b-a30c-67dbd28e132f', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 15, 15, 'What has my beloved to do in my house, since she has worked lewdness [with] many, and the holy flesh is passed from you? when you do evil, then you rejoice.'),
  ('078f6150-cb8a-5904-a413-cd0f2c5b0b77', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 16, 16, 'Yahweh called your name, A green olive tree, beautiful with goodly fruit: with the noise of a great tumult he has kindled fire on it, and its branches are broken.'),
  ('18524d90-a6ba-5e60-a4e8-b76a6ee659fb', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 17, 17, 'For Yahweh of Armies, who planted you, has pronounced evil against you, because of the evil of the house of Israel and of the house of Judah, which they have worked for themselves in provoking me to anger by offering incense to Baal.'),
  ('c8c0ee57-20d5-51c4-a99a-15dc3695ce18', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 18, 18, 'Yahweh gave me knowledge of it, and I knew it: then you showed me their doings.'),
  ('883c7e1a-39da-53f7-a289-1b93dc0730f1', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 19, 19, 'But I was like a gentle lamb that is led to the slaughter; and I didn''t know that they had devised devices against me, [saying], Let us destroy the tree with its fruit, and let us cut him off from the land of the living, that his name may be no more remembered.'),
  ('13bf9e0b-efc4-57d0-a097-cec92ddadca0', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 20, 20, 'But, Yahweh of Armies, who judges righteously, who tests the heart and the mind, I shall see your vengeance on them; for to you have I revealed my cause.'),
  ('54c4cfe4-8aa8-5b15-a704-b1ab10784ec7', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 21, 21, 'Therefore thus says Yahweh concerning the men of Anathoth, who seek your life, saying, You shall not prophesy in the name of Yahweh, that you not die by our hand;'),
  ('3d32772d-2163-5b9e-a4ae-eb1ca4173f9e', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 22, 22, 'therefore thus says Yahweh of Armies, Behold, I will punish them: the young men shall die by the sword; their sons and their daughters shall die by famine;'),
  ('6f592f26-c748-54bc-aa54-3ddc0a698868', 'f5a2d307-af91-5779-a209-2e327b754b3e', NULL, 23, 23, 'and there shall be no remnant to them: for I will bring evil on the men of Anathoth, even the year of their visitation.'),
  ('1dc792a6-e3ca-51a5-a908-f2ffbc494f17', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 1, 1, 'You are righteous, Yahweh, when I contend with you; yet I would reason the cause with you: why does the way of the wicked prosper? why are all they at ease who deal very treacherously?'),
  ('67c24d91-5a31-50bb-a1d6-1c61b60d6ac4', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 2, 2, 'You have planted them, yes, they have taken root; they grow, yes, they bring forth fruit: you are near in their mouth, and far from their heart.'),
  ('2dd7b516-7288-5d3a-a441-b37acb17f7be', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 3, 3, 'But you, Yahweh, know me; you see me, and try my heart toward you: pull them out like sheep for the slaughter, and prepare them for the day of slaughter.'),
  ('8edaa2c2-fd9d-5cf6-aaf1-5b563698fa5a', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 4, 4, 'How long shall the land mourn, and the herbs of the whole country wither? for the wickedness of those who dwell therein, the animals are consumed, and the birds; because they said, He shall not see our latter end.'),
  ('86906359-1282-5ae8-a43a-2754079532bd', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 5, 5, 'If you have run with the footmen, and they have wearied you, then how can you contend with horses? and though in a land of peace you are secure, yet how will you do in the pride of the Jordan?'),
  ('5734f05f-c843-5767-a125-ee0e53ed3b47', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 6, 6, 'For even your brothers, and the house of your father, even they have dealt treacherously with you; even they have cried aloud after you: don''t believe them, though they speak beautiful words to you.'),
  ('24074d53-7064-538d-aa24-350d59872e12', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 7, 7, 'I have forsaken my house, I have cast off my heritage; I have given the dearly beloved of my soul into the hand of her enemies.'),
  ('74c85815-986e-50f3-ad40-f8ac1a0aebbc', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 8, 8, 'My heritage is become to me as a lion in the forest: she has uttered her voice against me; therefore I have hated her.'),
  ('efd6ad2d-9dc5-5f24-a12e-b82768f3bcc0', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 9, 9, 'Is my heritage to me as a speckled bird of prey? are the birds of prey against her all around? Go, assemble all the animals of the field, bring them to devour.'),
  ('d1134b9c-939b-551c-a27b-1bc18ecd6ce2', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 10, 10, 'Many shepherds have destroyed my vineyard, they have trodden my portion under foot, they have made my pleasant portion a desolate wilderness.'),
  ('870141b7-8022-5acd-ac8b-7f1b195e0e4d', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 11, 11, 'They have made it a desolation; it mourns to me, being desolate; the whole land is made desolate, because no man lays it to heart.'),
  ('a45b33d4-4ab0-5d47-a0e2-6ad0e2ff4bec', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 12, 12, 'Destroyers are come on all the bare heights in the wilderness; for the sword of Yahweh devours from the one end of the land even to the other end of the land: no flesh has peace.'),
  ('f939cdd8-de80-56fd-a738-2d14c15536bb', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 13, 13, 'They have sown wheat, and have reaped thorns; they have put themselves to pain, and profit nothing: and you shall be ashamed of your fruits, because of the fierce anger of Yahweh.'),
  ('027e8d7d-3df7-5ca9-af67-2b475d0431a8', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 14, 14, 'Thus says Yahweh against all my evil neighbors, who touch the inheritance which I have caused my people Israel to inherit: behold, I will pluck them up from off their land, and will pluck up the house of Judah from among them.'),
  ('5738110a-26fb-5715-aae9-a413e5d2dff5', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 15, 15, 'It shall happen, after that I have plucked them up, I will return and have compassion on them; and I will bring them again, every man to his heritage, and every man to his land.'),
  ('5f46b472-7625-56e8-a797-249b877b1ca3', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 16, 16, 'It shall happen, if they will diligently learn the ways of my people, to swear by my name, As Yahweh lives; even as they taught my people to swear by Baal; then shall they be built up in the midst of my people.'),
  ('cbabe2eb-2c0a-5a43-a754-f121d1459b83', '878fb47d-79ec-5a0b-a6f5-6cdf4ea50f98', NULL, 17, 17, 'But if they will not hear, then will I pluck up that nation, plucking up and destroying it, says Yahweh.'),
  ('3752dad3-f9df-5e19-a04a-7a4ac7ba31bf', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 1, 1, 'Thus says Yahweh to me, Go, and buy yourself a linen belt, and put it on your waist, and don''t put it in water.'),
  ('4066c266-6c5b-505d-a292-8df43060be59', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 2, 2, 'So I bought a belt according to the word of Yahweh, and put it on my waist.'),
  ('a3279675-5dde-5604-aa8c-5888d610ecb9', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 3, 3, 'The word of Yahweh came to me the second time, saying,'),
  ('002b1848-1901-5880-a1f9-ce57037379bd', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 4, 4, 'Take the belt that you have bought, which is on your waist, and arise, go to the Euphrates, and hide it there in a cleft of the rock.'),
  ('f94cc894-6a16-5447-a94b-87ea46b4b5b7', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 5, 5, 'So I went, and hid it by the Euphrates, as Yahweh commanded me.'),
  ('420c2cb9-cc51-5532-ace4-282e8b2a881a', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 6, 6, 'It happened after many days, that Yahweh said to me, Arise, go to the Euphrates, and take the belt from there, which I commanded you to hide there.'),
  ('45d5dc04-a409-5dc4-ad66-2f83ca75a318', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 7, 7, 'Then I went to the Euphrates, and dug, and took the belt from the place where I had hidden it; and behold, the belt was marred, it was profitable for nothing.'),
  ('7037da34-56f7-5aed-a491-f1c7a3c6e8ce', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 8, 8, 'Then the word of Yahweh came to me, saying,'),
  ('8f35d9b1-509f-5420-a7be-0de875c8affb', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 9, 9, 'Thus says Yahweh, In this way I will mar the pride of Judah, and the great pride of Jerusalem.'),
  ('09e51673-a749-51b4-a6a1-58f1eb88cbf1', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 10, 10, 'This evil people, who refuse to hear my words, who walk in the stubbornness of their heart, and are gone after other gods to serve them, and to worship them, shall even be as this belt, which is profitable for nothing.'),
  ('036b1bec-0c0f-5428-a4eb-9783a6ca8309', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 11, 11, 'For as the belt clings to the waist of a man, so have I caused to cling to me the whole house of Israel and the whole house of Judah, says Yahweh; that they may be to me for a people, and for a name, and for a praise, and for a glory: but they would not hear.'),
  ('9380b96a-0620-5f16-a49b-80f807325153', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 12, 12, 'Therefore you shall speak to them this word: Thus says Yahweh, the God of Israel, Every bottle shall be filled with wine: and they shall tell you, Do we not certainly know that every bottle shall be filled with wine?'),
  ('cae28378-37b5-5dec-ac6e-e31838379fc2', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 13, 13, 'Then you shall tell them, Thus says Yahweh, Behold, I will fill all the inhabitants of this land, even the kings who sit on David''s throne, and the priests, and the prophets, and all the inhabitants of Jerusalem, with drunkenness.'),
  ('7eaef6a5-18fb-5be8-a419-abf8e7f48f87', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 14, 14, 'I will dash them one against another, even the fathers and the sons together, says Yahweh: I will not pity, nor spare, nor have compassion, that I should not destroy them.'),
  ('1cb1408e-2cfc-53f9-a96a-67e781b077b0', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 15, 15, 'Hear, and give ear; don''t be proud; for Yahweh has spoken.'),
  ('673a1446-3392-532a-add9-414707987076', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 16, 16, 'Give glory to Yahweh your God, before he causes darkness, and before your feet stumble on the dark mountains, and, while you look for light, he turns it into the shadow of death, and makes it gross darkness.'),
  ('a87b9159-dcd9-5559-a718-0cd9a9dd777c', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 17, 17, 'But if you will not hear it, my soul shall weep in secret for [your] pride; and my eye shall weep bitterly, and run down with tears, because Yahweh''s flock is taken captive.'),
  ('44172c13-b68c-5e3e-ac78-f53dac3ec6b0', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 18, 18, 'Say to the king and to the queen mother, Humble yourselves, sit down; for your headdresses have come down, even the crown of your glory.'),
  ('3e0e913c-1dc9-5654-a8c2-0c9abb313bc7', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 19, 19, 'The cities of the South are shut up, and there is none to open them: Judah is carried away captive, all of it; it is wholly carried away captive.'),
  ('1d667123-2e9e-543f-a67c-65e90dd57e86', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 20, 20, 'Lift up your eyes, and see those who come from the north: where is the flock that was given you, your beautiful flock?'),
  ('bf1deccf-3cb0-515e-a879-9995595e8e10', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 21, 21, 'What will you say, when he shall set over you as head those whom you have yourself taught to be friends to you? shall not sorrows take hold of you, as of a woman in travail?'),
  ('f68362f7-2810-568a-af66-812451529de6', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 22, 22, 'If you say in your heart, Why are these things come on me? for the greatness of your iniquity are your skirts uncovered, and your heels suffer violence.'),
  ('3d0fe6e5-1ded-5713-a2b4-a09764d32a30', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 23, 23, 'Can the Ethiopian change his skin, or the leopard his spots? then may you also do good, who are accustomed to do evil.'),
  ('99034b51-a6b7-58b1-a471-8986c132cc1d', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 24, 24, 'Therefore will I scatter them, as the stubble that passes away, by the wind of the wilderness.'),
  ('a37eee5f-b29b-5201-a90b-e1e015a40c66', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 25, 25, 'This is your lot, the portion measured to you from me, says Yahweh; because you have forgotten me, and trusted in falsehood.'),
  ('f98a51ba-169d-5f0e-ad1f-eb3a837bb2f5', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 26, 26, 'Therefore will I also uncover your skirts on your face, and your shame shall appear.'),
  ('90cd714a-c2e9-5e96-a97d-eefda0abbbbb', '556b758d-933b-535e-ad1d-8d0049eb313f', NULL, 27, 27, 'I have seen your abominations, even your adulteries, and your neighing, the lewdness of your prostitution, on the hills in the field. Woe to you, Jerusalem! You will not be made clean; how long shall it yet be?'),
  ('af514814-c043-5d8f-acd1-8594812afe4a', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 1, 1, 'The word of Yahweh that came to Jeremiah concerning the drought.'),
  ('45d74671-dc23-5935-a2b8-44c3fd0f1ec8', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 2, 2, 'Judah mourns, and its gates languish, they sit in black on the ground; and the cry of Jerusalem is gone up.'),
  ('73dce9d0-3597-5065-ae39-772ffc267ba3', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 3, 3, 'Their nobles send their little ones to the waters: they come to the cisterns, and find no water; they return with their vessels empty; they are disappointed and confounded, and cover their heads.'),
  ('09640529-2396-5e73-a265-1429dd3e3152', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 4, 4, 'Because of the ground which is cracked, because no rain has been in the land, the plowmen are disappointed, they cover their heads.'),
  ('7fc74339-12ca-5dfb-af65-2a8b11f82f3d', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 5, 5, 'Yes, the hind also in the field calves, and forsakes [her young], because there is no grass.'),
  ('64495ef6-d438-5925-a4d8-15ca32595767', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 6, 6, 'The wild donkeys stand on the bare heights, they pant for air like jackals; their eyes fail, because there is no herbage.'),
  ('143e43a3-a2d2-5179-a754-029e7f542c12', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 7, 7, 'Though our iniquities testify against us, work for your name''s sake, Yahweh; for our backslidings are many; we have sinned against you.'),
  ('9d143ec4-2530-5ce7-a13e-056e753f89cb', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 8, 8, 'You hope of Israel, its Savior in the time of trouble, why should you be as a foreigner in the land, and as a wayfaring man who turns aside to stay for a night?'),
  ('930d1c37-1d64-585c-a083-59ecb9eb230d', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 9, 9, 'Why should you be like a scared man, as a mighty man who can''t save? Yet you, Yahweh, are in the midst of us, and we are called by your name; don''t leave us.'),
  ('28113dd0-76ba-5a41-ac62-f48db3d47acb', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 10, 10, 'Thus says Yahweh to this people, Even so have they loved to wander; they have not refrained their feet: therefore Yahweh does not accept them; now he will remember their iniquity, and visit their sins.'),
  ('0b3fabb4-24c8-5bb7-a4eb-5d629622cdff', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 11, 11, 'Yahweh said to me, Don''t pray for this people for [their] good.'),
  ('e4c9b6e7-c3b1-5fb1-ae7e-95a01826da8e', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 12, 12, 'When they fast, I will not hear their cry; and when they offer burnt offering and meal offering, I will not accept them; but I will consume them by the sword, and by the famine, and by the pestilence.'),
  ('2d3761f1-0799-5fd1-acc7-2dcce1365801', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 13, 13, 'Then I said, Ah, Lord Yahweh! behold, the prophets tell them, You shall not see the sword, neither shall you have famine; but I will give you assured peace in this place.'),
  ('fc83cf46-8cc3-549c-a5c4-8e5c2964b152', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 14, 14, 'Then Yahweh said to me, The prophets prophesy lies in my name; I didn''t send them, neither have I commanded them, neither spoke I to them: they prophesy to you a lying vision, and divination, and a thing of nothing, and the deceit of their own heart.'),
  ('5a227294-4467-5a3c-a7ab-6ffaf2676ab0', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 15, 15, 'Therefore thus says Yahweh concerning the prophets who prophesy in my name, and I didn''t send them, yet they say, Sword and famine shall not be in this land: By sword and famine shall those prophets be consumed.'),
  ('71b3e481-60de-5bcd-a551-8aa9642befd7', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 16, 16, 'The people to whom they prophesy shall be cast out in the streets of Jerusalem because of the famine and the sword; and they shall have none to bury them--them, their wives, nor their sons, nor their daughters: for I will pour their wickedness on them.'),
  ('e33d5f89-18b3-5fe6-a80e-0ec4781961d8', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 17, 17, 'You shall say this word to them, Let my eyes run down with tears night and day, and let them not cease; for the virgin daughter of my people is broken with a great breach, with a very grievous wound.'),
  ('b24799a6-3c9e-5bec-adb5-b9bea82cc216', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 18, 18, 'If I go forth into the field, then, behold, the slain with the sword! and if I enter into the city, then, behold, those who are sick with famine! for both the prophet and the priest go about in the land, and have no knowledge.'),
  ('8c98a6ad-770e-5932-af47-0b3b218cb02c', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 19, 19, 'Have you utterly rejected Judah? has your soul loathed Zion? why have you struck us, and there is no healing for us? We looked for peace, but no good came; and for a time of healing, and behold, dismay!'),
  ('95ef958c-a9d0-5618-af96-663afa7c8dc0', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 20, 20, 'We acknowledge, Yahweh, our wickedness, and the iniquity of our fathers; for we have sinned against you.'),
  ('e06a0c0a-39f9-5a81-a86d-801225383514', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 21, 21, 'Do not abhor [us], for your name''s sake; do not disgrace the throne of your glory: remember, don''t break your covenant with us.'),
  ('56bc0be8-228a-54bf-ad22-b6c2856a4a8f', 'eebc4831-c01f-56ae-aa7e-571c935f40f0', NULL, 22, 22, 'Are there any among the vanities of the nations that can cause rain? or can the sky give showers? Aren''t you he, Yahweh our God? therefore we will wait for you; for you have made all these things.'),
  ('18f6ecae-e134-5a0e-a63d-10636b361d0b', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 1, 1, 'Then Yahweh said to me, Though Moses and Samuel stood before me, yet my mind would not be toward this people: cast them out of my sight, and let them go forth.'),
  ('8e6fc5f3-da63-551c-abe6-104bf2e2cba5', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 2, 2, 'It shall happen, when they tell you, Where shall we go forth? Then you shall tell them, Thus says Yahweh: Such as are for death, to death; and such as are for the sword, to the sword; and such as are for the famine, to the famine; and such as are for captivity, to captivity.'),
  ('5ee4335e-64fb-538f-a6a8-a184aa26393f', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 3, 3, 'I will appoint over them four kinds, says Yahweh: the sword to kill, and the dogs to tear, and the birds of the sky, and the animals of the earth, to devour and to destroy.'),
  ('37bbb57b-0d7c-5eb8-a4d4-7d43b5e157c5', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 4, 4, 'I will cause them to be tossed back and forth among all the kingdoms of the earth, because of Manasseh, the son of Hezekiah, king of Judah, for that which he did in Jerusalem.'),
  ('0d9d2864-45ca-5f50-a063-93cb6b793ad7', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 5, 5, 'For who will have pity on you, Jerusalem? or who will bemoan you? or who will turn aside to ask of your welfare?'),
  ('8c1a3de1-a69e-5fd1-a4b6-e196959ae597', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 6, 6, 'You have rejected me, says Yahweh, you have gone backward: therefore have I stretched out my hand against you, and destroyed you; I am weary with repenting.'),
  ('48472a8f-9613-5f3b-aa95-369636654ee0', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 7, 7, 'I have winnowed them with a fan in the gates of the land; I have bereaved [them] of children, I have destroyed my people; they didn''t return from their ways.'),
  ('d4bed0cb-cb42-5ec6-ab07-66bc4d66a515', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 8, 8, 'Their widows are increased to me above the sand of the seas; I have brought on them against the mother of the young men a destroyer at noonday: I have caused anguish and terrors to fall on her suddenly.'),
  ('972f9e96-303b-54e8-ad2a-26c383b141ec', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 9, 9, 'She who has borne seven languishes; she has given up the spirit; her sun is gone down while it was yet day; she has been disappointed and confounded: and the residue of them will I deliver to the sword before their enemies, says Yahweh.'),
  ('6ad5b9b8-f0ce-50f3-a204-53ff582308f6', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 10, 10, 'Woe is me, my mother, that you have borne me a man of strife and a man of contention to the whole earth! I have not lent, neither have men lent to me; [yet] everyone of them does curse me.'),
  ('dfed1ee8-ed48-5b93-af83-070185fae1d8', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 11, 11, 'Yahweh said, Most certainly I will strengthen you for good; most certainly I will cause the enemy to make supplication to you in the time of evil and in the time of affliction.'),
  ('e8518e36-f6d3-53c9-a53c-f3f25a13d411', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 12, 12, 'Can one break iron, even iron from the north, and brass?'),
  ('62793ede-d97a-5ae5-a20e-3baca6f8ee45', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 13, 13, 'Your substance and your treasures will I give for a spoil without price, and that for all your sins, even in all your borders.'),
  ('ffb54827-b706-5dce-a785-406381125098', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 14, 14, 'I will make [them] to pass with your enemies into a land which you don''t know; for a fire is kindled in my anger, which shall burn on you.'),
  ('5aa7abed-1334-512a-a5c9-94f58c33f7e3', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 15, 15, 'Yahweh, you know; remember me, and visit me, and avenge me of my persecutors; don''t take me away in your longsuffering: know that for your sake I have suffered reproach.'),
  ('06d7007d-f2e9-55ca-ae7f-830ef597fa92', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 16, 16, 'Your words were found, and I ate them; and your words were to me a joy and the rejoicing of my heart: for I am called by your name, Yahweh, God of Armies.'),
  ('d9b160a5-b597-563f-afec-e3cca6c651de', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 17, 17, 'I didn''t sit in the assembly of those who make merry, nor rejoiced; I sat alone because of your hand; for you have filled me with indignation.'),
  ('efc2e335-f34b-5604-ad66-40e1e5a720be', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 18, 18, 'Why is my pain perpetual, and my wound incurable, which refuses to be healed? will you indeed be to me as a deceitful [brook], as waters that fail?'),
  ('7623ff72-2933-57ed-a029-1cefa55eb8a6', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 19, 19, 'Therefore thus says Yahweh, If you return, then will I bring you again, that you may stand before me; and if you take forth the precious from the vile, you shall be as my mouth: they shall return to you, but you shall not return to them.'),
  ('852b6ac2-c2cc-5088-a73b-d4319a03775a', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 20, 20, 'I will make you to this people a fortified bronze wall; and they shall fight against you, but they shall not prevail against you; for I am with you to save you and to deliver you, says Yahweh.'),
  ('aec28e6b-5411-50d6-abbc-7e9d20747c80', '9f571ce1-5ac8-5b28-aa79-76e8f77a6829', NULL, 21, 21, 'I will deliver you out of the hand of the wicked, and I will redeem you out of the hand of the terrible.'),
  ('b2156db9-201d-53ea-a82c-1281e50e4c85', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 1, 1, 'The word of Yahweh came also to me, saying,'),
  ('7c3d695b-0b4b-5f87-a8ca-4deb20608528', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 2, 2, 'You shall not take a wife, neither shall you have sons or daughters, in this place.'),
  ('276442b9-7df2-54b1-ab80-3012ff5de443', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 3, 3, 'For thus says Yahweh concerning the sons and concerning the daughters who are born in this place, and concerning their mothers who bore them, and concerning their fathers who became the father of them in this land:'),
  ('17570016-3570-5b7c-aca1-c7c4b131d5d0', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 4, 4, 'They shall die grievous deaths: they shall not be lamented, neither shall they be buried; they shall be as dung on the surface of the ground; and they shall be consumed by the sword, and by famine; and their dead bodies shall be food for the birds of the sky, and for the animals of the earth.'),
  ('b800c11a-d7d3-5ea3-ac4e-9984872614ad', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 5, 5, 'For thus says Yahweh, Don''t enter into the house of mourning, neither go to lament, neither bemoan them; for I have taken away my peace from this people, says Yahweh, even loving kindness and tender mercies.'),
  ('aeccfb97-d3db-5f37-a771-ce7c88372419', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 6, 6, 'Both great and small shall die in this land; they shall not be buried, neither shall men lament for them, nor cut themselves, nor make themselves bald for them;'),
  ('58a5b914-41c6-5b6d-aecc-8dcd4accc2f3', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 7, 7, 'neither shall men break [bread] for them in mourning, to comfort them for the dead; neither shall men give them the cup of consolation to drink for their father or for their mother.'),
  ('0873e83f-dda3-56da-aced-71a8393a6d6f', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 8, 8, 'You shall not go into the house of feasting to sit with them, to eat and to drink.'),
  ('4228272c-4278-52f2-a588-d397f49885f6', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 9, 9, 'For thus says Yahweh of Armies, the God of Israel: Behold, I will cause to cease out of this place, before your eyes and in your days, the voice of mirth and the voice of gladness, the voice of the bridegroom and the voice of the bride.'),
  ('22a54f6e-2062-5c71-a988-b363b31437a3', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 10, 10, 'It shall happen, when you shall show this people all these words, and they shall tell you, Why has Yahweh pronounced all this great evil against us? or what is our iniquity? or what is our sin that we have committed against Yahweh our God?'),
  ('d3089dd9-3cc4-5966-a323-e4c97f022792', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 11, 11, 'Then you shall tell them, Because your fathers have forsaken me, says Yahweh, and have walked after other gods, and have served them, and have worshiped them, and have forsaken me, and have not kept my law;'),
  ('18511bdc-603a-5a68-a54c-7528814118cd', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 12, 12, 'and you have done evil more than your fathers; for, behold, you walk every one after the stubbornness of his evil heart, so that you don''t listen to me:'),
  ('8b6e0582-67cd-5a61-a898-28885340f50f', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 13, 13, 'therefore will I cast you forth out of this land into the land that you have not known, neither you nor your fathers; and there you shall serve other gods day and night; for I will show you no favor.'),
  ('a47a380c-ee40-53e9-a609-6fd840ed406c', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 14, 14, 'Therefore, behold, the days come, says Yahweh, that it shall no more be said, As Yahweh lives, who brought up the children of Israel out of the land of Egypt;'),
  ('364289bd-2a33-5216-ad86-45b966cd3eec', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 15, 15, 'but, As Yahweh lives, who brought up the children of Israel from the land of the north, and from all the countries where he had driven them. I will bring them again into their land that I gave to their fathers.'),
  ('41bce79f-0f58-568a-a8ef-e6e194b59101', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 16, 16, 'Behold, I will send for many fishermen, says Yahweh, and they shall fish them up; and afterward I will send for many hunters, and they shall hunt them from every mountain, and from every hill, and out of the clefts of the rocks.'),
  ('b5d3361d-58cd-5db2-add5-219f8b1ca508', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 17, 17, 'For my eyes are on all their ways; they are not hidden from my face, neither is their iniquity concealed from my eyes.'),
  ('9aaec88d-7ffb-50d9-adab-7c33452024d7', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 18, 18, 'First I will recompense their iniquity and their sin double, because they have polluted my land with the carcasses of their detestable things, and have filled my inheritance with their abominations.'),
  ('3f45bf5c-4d32-565a-a471-5c28d6aa505e', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 19, 19, 'Yahweh, my strength, and my stronghold, and my refuge in the day of affliction, to you shall the nations come from the ends of the earth, and shall say, Our fathers have inherited nothing but lies, [even] vanity and things in which there is no profit.'),
  ('8dbdfa6a-6146-5d01-a0a9-fbad1040266c', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 20, 20, 'Shall a man make to himself gods, which yet are no gods?'),
  ('2b2b54e0-228d-5531-a818-0e74c545f316', '7aedc369-070f-54f1-ae2a-299f140031c6', NULL, 21, 21, 'Therefore, behold, I will cause them to know, this once will I cause them to know my hand and my might; and they shall know that my name is Yahweh.'),
  ('95e8b092-0660-5657-a7dd-30a945f66f3d', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 1, 1, 'The sin of Judah is written with a pen of iron, [and] with the point of a diamond: it is engraved on the tablet of their heart, and on the horns of your altars;'),
  ('eb9d525f-8fff-5859-aa03-fa645bda48cf', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 2, 2, 'while their children remember their altars and their Asherim by the green trees on the high hills.'),
  ('1bf932a6-c0e2-54d0-a519-04c1806ab4e8', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 3, 3, 'My mountain in the field, I will give your substance and all your treasures for a spoil, [and] your high places, because of sin, throughout all your borders.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c658dd4e-b2bb-5b7d-ae4d-ddf51a2e428e', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 4, 4, 'You, even of yourself, shall discontinue from your heritage that I gave you; and I will cause you to serve your enemies in the land which you don''t know: for you have kindled a fire in my anger which shall burn forever.'),
  ('1f3aaf5b-59dc-537c-a6ad-efae74a8431a', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 5, 5, 'Thus says Yahweh: Cursed is the man who trusts in man, and makes flesh his arm, and whose heart departs from Yahweh.'),
  ('da37d4fe-20e2-5528-abee-f0c2223ab47a', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 6, 6, 'For he shall be like the heath in the desert, and shall not see when good comes, but shall inhabit the parched places in the wilderness, a salt land and not inhabited.'),
  ('1a27fca8-4e2b-586f-af7c-45e62af13c1f', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 7, 7, 'Blessed is the man who trusts in Yahweh, and whose trust Yahweh is.'),
  ('575193e0-b6eb-50e5-a1d9-71433d9ae9f5', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 8, 8, 'For he shall be as a tree planted by the waters, who spreads out its roots by the river, and shall not fear when heat comes, but its leaf shall be green; and shall not be careful in the year of drought, neither shall cease from yielding fruit.'),
  ('4ef29701-cdf2-50d9-aa40-e0d460fc4c3d', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 9, 9, 'The heart is deceitful above all things, and it is exceedingly corrupt: who can know it?'),
  ('42ffb99f-e035-567e-a3b7-2982085a4119', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 10, 10, 'I, Yahweh, search the mind, I try the heart, even to give every man according to his ways, according to the fruit of his doings.'),
  ('4d51757b-90cf-5e8d-a2bd-9c727c5201dc', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 11, 11, 'As the partridge that sits on [eggs] which she has not laid, so is he who gets riches, and not by right; in the midst of his days they shall leave him, and at his end he shall be a fool.'),
  ('5968a85b-cdee-5c34-ad8c-88227be26b3d', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 12, 12, 'A glorious throne, [set] on high from the beginning, is the place of our sanctuary.'),
  ('6465656b-b6a4-5c14-ad9a-885c16e9e5b3', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 13, 13, 'Yahweh, the hope of Israel, all who forsake you shall be disappointed. Those who depart from me shall be written in the earth, because they have forsaken Yahweh, the spring of living waters.'),
  ('4bbe8b02-6ad4-5cd0-ad12-aeed5af6e583', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 14, 14, 'Heal me, O Yahweh, and I shall be healed; save me, and I shall be saved: for you are my praise.'),
  ('8e8fdb5d-623c-56c0-a7e7-fc8cb602914e', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 15, 15, 'Behold, they tell me, Where is the word of Yahweh? let it come now.'),
  ('f3a3b0f8-1a21-5e75-afaa-8fc8cb75c0f8', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 16, 16, 'As for me, I have not hurried from being a shepherd after you; neither have I desired the woeful day; you know: that which came out of my lips was before your face.'),
  ('26c086bc-b607-5e56-ab1d-a567a64cbb2e', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 17, 17, 'Don''t be a terror to me: you are my refuge in the day of evil.'),
  ('2b2996f5-68c8-59bf-a2cd-f8a8b229bb3b', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 18, 18, 'Let them be disappointed who persecute me, but let not me be disappointed; let them be dismayed, but don''t let me be dismayed; bring on them the day of evil, and destroy them with double destruction.'),
  ('a44d3ce0-084c-57c8-a127-46d5f4516911', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 19, 19, 'Thus said Yahweh to me: Go, and stand in the gate of the children of the people, through which the kings of Judah come in, and by which they go out, and in all the gates of Jerusalem;'),
  ('94c400de-4822-50e7-aa30-0dd0f401ad96', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 20, 20, 'and tell them, Hear the word of Yahweh, you kings of Judah, and all Judah, and all the inhabitants of Jerusalem, that enter in by these gates:'),
  ('3b6e0a53-1c14-5939-aafd-c59f969544da', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 21, 21, 'Thus says Yahweh, Take heed to yourselves, and bear no burden on the Sabbath day, nor bring it in by the gates of Jerusalem;'),
  ('70456028-9585-5612-a99a-472314031978', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 22, 22, 'neither carry forth a burden out of your houses on the Sabbath day holy, neither do any work: but make the Sabbath day, as I commanded your fathers.'),
  ('38761b4d-f807-595e-ae12-0c67d9a20eab', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 23, 23, 'But they didn''t listen, neither turn their ear, but made their neck stiff, that they might not hear, and might not receive instruction.'),
  ('6e6126c7-908b-505c-ac77-81fadf59b6de', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 24, 24, 'It shall happen, if you diligently listen to me, says Yahweh, to bring in no burden through the gates of this city on the Sabbath day, but to make the Sabbath day holy, to do no work therein;'),
  ('9597a0da-854e-522d-a431-4dd0bcbf2e4d', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 25, 25, 'then shall there enter in by the gates of this city kings and princes sitting on the throne of David, riding in chariots and on horses, they, and their princes, the men of Judah, and the inhabitants of Jerusalem; and this city shall remain forever.'),
  ('7f29ae98-7257-52fd-a865-c6db7d237885', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 26, 26, 'They shall come from the cities of Judah, and from the places around Jerusalem, and from the land of Benjamin, and from the lowland, and from the hill country, and from the South, bringing burnt offerings, and sacrifices, and meal offerings, and frankincense, and bringing [sacrifices of] thanksgiving, to the house of Yahweh.'),
  ('1e9ff959-4cb6-5206-a2fe-f6eaa05b0e28', '0d2e6555-17f1-5f5f-a19a-9f23ecc5dcd2', NULL, 27, 27, 'But if you will not listen to me to make the Sabbath day holy, and not to bear a burden and enter in at the gates of Jerusalem on the Sabbath day; then will I kindle a fire in its gates, and it shall devour the palaces of Jerusalem, and it shall not be quenched.'),
  ('0a40e98e-9cf9-5d97-a491-35fb1ce8eea7', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 1, 1, 'The word which came to Jeremiah from Yahweh, saying,'),
  ('129c0339-8be7-58ef-aba1-0a15b333a55e', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 2, 2, 'Arise, and go down to the potter''s house, and there I will cause you to hear my words.'),
  ('85f06ca9-0fff-5df2-a77f-5e75ca4521d4', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 3, 3, 'Then I went down to the potter''s house, and behold, he was making a work on the wheels.'),
  ('465529da-9f14-5d39-a431-1931e2e1376d', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 4, 4, 'When the vessel that he made of the clay was marred in the hand of the potter, he made it again another vessel, as seemed good to the potter to make it.'),
  ('95a03cb2-69d4-59ad-adbd-1bef5b8ca0ec', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 5, 5, 'Then the word of Yahweh came to me, saying,'),
  ('1fc609d4-6257-5a64-a41a-fc9cf37d870b', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 6, 6, 'House of Israel, can''t I do with you as this potter? says Yahweh. Behold, as the clay in the potter''s hand, so are you in my hand, house of Israel.'),
  ('37208a70-18df-50fa-a20b-db5eb0f119d6', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 7, 7, 'At what instant I shall speak concerning a nation, and concerning a kingdom, to pluck up and to break down and to destroy it;'),
  ('e9d28b9b-c1d0-516b-a85f-8ca3d8722b28', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 8, 8, 'if that nation, concerning which I have spoken, turn from their evil, I will repent of the evil that I thought to do to them.'),
  ('525fa936-c20d-5583-affd-8b0d0db98b87', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 9, 9, 'At what instant I shall speak concerning a nation, and concerning a kingdom, to build and to plant it;'),
  ('16c64720-8563-5b20-a173-86e68cc8b1d9', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 10, 10, 'if they do that which is evil in my sight, that they not obey my voice, then I will repent of the good, with which I said I would benefit them.'),
  ('9790ebfb-a6af-5ac5-a3c9-13b6c085d0c8', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 11, 11, 'Now therefore, speak to the men of Judah, and to the inhabitants of Jerusalem, saying, Thus says Yahweh: Behold, I frame evil against you, and devise a device against you: return you now everyone from his evil way, and amend your ways and your doings.'),
  ('37ad9f29-f5f4-50e0-acdd-dc1247e9c070', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 12, 12, 'But they say, It is in vain; for we will walk after our own devices, and we will do everyone after the stubbornness of his evil heart.'),
  ('31b90ed5-4f61-5d44-ae97-18ff5a5e082b', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 13, 13, 'Therefore thus says Yahweh: Ask now among the nations, who has heard such things; the virgin of Israel has done a very horrible thing.'),
  ('c355bb16-d2f8-58e9-abec-a8ea927de041', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 14, 14, 'Shall the snow of Lebanon fail from the rock of the field? [or] shall the cold waters that flow down from afar be dried up?'),
  ('dacf575e-7e9e-5398-aa12-3b791be05d27', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 15, 15, 'For my people have forgotten me, they have burned incense to false [gods]; and they have been made to stumble in their ways, in the ancient paths, to walk in byways, in a way not built up;'),
  ('212ca35f-5933-520d-a217-f9b5ee96c0ce', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 16, 16, 'to make their land an astonishment, and a perpetual hissing; everyone who passes thereby shall be astonished, and shake his head.'),
  ('cafdfe44-d9ec-5aa8-a07b-a50f06150786', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 17, 17, 'I will scatter them as with an east wind before the enemy; I will show them the back, and not the face, in the day of their calamity.'),
  ('ca5c3db6-6e2d-5a7d-a121-63ed289d86f4', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 18, 18, 'Then they said, Come, and let us devise devices against Jeremiah; for the law shall not perish from the priest, nor counsel from the wise, nor the word from the prophet. Come, and let us strike him with the tongue, and let us not give heed to any of his words.'),
  ('1f94a873-a183-5296-aaef-765c71e3fab6', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 19, 19, 'Give heed to me, Yahweh, and listen to the voice of those who contend with me.'),
  ('7f517d4f-8f37-50ef-a378-ca22a477e497', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 20, 20, 'Shall evil be recompensed for good? for they have dug a pit for my soul. Remember how I stood before you to speak good for them, to turn away your wrath from them.'),
  ('49ec9849-e8e5-592a-af25-b195eb90b536', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 21, 21, 'Therefore deliver up their children to the famine, and give them over to the power of the sword; and let their wives become childless, and widows; and let their men be slain of death, [and] their young men struck of the sword in battle.'),
  ('32b13914-7178-5ae8-a5fe-4f8274da0c5f', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 22, 22, 'Let a cry be heard from their houses, when you shall bring a troop suddenly on them; for they have dug a pit to take me, and hid snares for my feet.'),
  ('2aa4e1a6-67fb-5bff-a9de-cd3f95103191', 'ae64d00a-b18d-53d9-afdf-06c7d96a1363', NULL, 23, 23, 'Yet, Yahweh, you know all their counsel against me to kill me; don''t forgive their iniquity, neither blot out their sin from your sight; but let them be overthrown before you; deal you with them in the time of your anger.'),
  ('aee1ecc6-35c4-51f1-ad2e-f0e45744c0ee', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 1, 1, 'Thus said Yahweh, Go, and buy a potter''s earthen bottle, and [take] of the elders of the people, and of the elders of the priests;'),
  ('bfd04911-2a90-512f-af02-7c12bf5a39d5', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 2, 2, 'and go forth to the valley of the son of Hinnom, which is by the entry of the gate Harsith, and proclaim there the words that I shall tell you;'),
  ('d7480d05-db50-5fdb-a195-17bc40827eae', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 3, 3, 'and say, Hear the word of Yahweh, kings of Judah, and inhabitants of Jerusalem: thus says Yahweh of Armies, the God of Israel, Behold, I will bring evil on this place, which whoever hears, his ears shall tingle.'),
  ('22d1d003-9b9c-54ff-aaf1-67f47f68587d', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 4, 4, 'Because they have forsaken me, and have estranged this place, and have burned incense in it to other gods, that they didn''t know, they and their fathers and the kings of Judah; and have filled this place with the blood of innocents,'),
  ('6fa088cf-b88d-5ab8-afbf-7da8a623a882', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 5, 5, 'and have built the high places of Baal, to burn their sons in the fire for burnt offerings to Baal; which I didn''t command, nor spoke it, neither came it into my mind:'),
  ('1b6fe2c6-cd07-5bcf-a86f-e5769a56c950', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 6, 6, 'therefore, behold, the days come, says Yahweh, that this place shall no more be called Topheth, nor The valley of the son of Hinnom, but The valley of Slaughter.'),
  ('84e4f12d-9a72-52f9-a688-e5d31e0e6e8d', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 7, 7, 'I will make void the counsel of Judah and Jerusalem in this place; and I will cause them to fall by the sword before their enemies, and by the hand of those who seek their life: and their dead bodies will I give to be food for the birds of the sky, and for the animals of the earth.'),
  ('86ad9fc8-1627-5c27-a72a-dcf4ed43dd14', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 8, 8, 'I will make this city an astonishment, and a hissing; everyone who passes thereby shall be astonished and hiss because of all its plagues.'),
  ('c3a949a3-87a7-5544-ae95-4b012157137e', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 9, 9, 'I will cause them to eat the flesh of their sons and the flesh of their daughters; and they shall eat everyone the flesh of his friend, in the siege and in the distress, with which their enemies, and those who seek their life, shall distress them.'),
  ('7bbc1d9a-eb6b-5c19-a903-325fc5271f27', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 10, 10, 'Then you shall break the bottle in the sight of the men who go with you,'),
  ('f554954e-ad2f-5e97-ae6a-f95906b9f861', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 11, 11, 'and shall tell them, Thus says Yahweh of Armies: Even so will I break this people and this city, as one breaks a potter''s vessel, that can''t be made whole again; and they shall bury in Topheth, until there be no place to bury.'),
  ('8c5d41a1-f89d-5894-a15e-f251ef5b8c18', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 12, 12, 'Thus will I do to this place, says Yahweh, and to its inhabitants, even making this city as Topheth:'),
  ('ffad7bfe-3c38-59ef-a233-e31ab54024cd', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 13, 13, 'and the houses of Jerusalem, and the houses of the kings of Judah, which are defiled, shall be as the place of Topheth, even all the houses on whose roofs they have burned incense to all the army of the sky, and have poured out drink offerings to other gods.'),
  ('cebf1ea9-ff37-5825-acce-e247063301ae', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 14, 14, 'Then came Jeremiah from Topheth, where Yahweh had sent him to prophesy; and he stood in the court of Yahweh''s house, and said to all the people:'),
  ('0fcb3593-e8e2-5de7-a881-cc11ff355826', '6395997d-81d1-5add-a3ba-17b25a46ad4a', NULL, 15, 15, 'Thus says Yahweh of Armies, the God of Israel, Behold, I will bring on this city and on all its towns all the evil that I have pronounced against it; because they have made their neck stiff, that they may not hear my words.'),
  ('6f491acf-e146-554b-a3e3-ef381e025f3c', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 1, 1, 'Now Pashhur, the son of Immer the priest, who was chief officer in the house of Yahweh, heard Jeremiah prophesying these things.'),
  ('0b3c0d65-59c5-548f-a36d-d6412fef0e42', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 2, 2, 'Then Pashhur struck Jeremiah the prophet, and put him in the stocks that were in the upper gate of Benjamin, which was in the house of Yahweh.'),
  ('18b47d2c-1149-5eb2-a340-cb6283dfe9bf', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 3, 3, 'It happened on the next day, that Pashhur brought forth Jeremiah out of the stocks. Then Jeremiah said to him, Yahweh has not called your name Pashhur, but Magormissabib.'),
  ('906b6cde-634f-5d51-a868-2ec68556664e', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 4, 4, 'For thus says Yahweh, Behold, I will make you a terror to yourself, and to all your friends; and they shall fall by the sword of their enemies, and your eyes shall see it; and I will give all Judah into the hand of the king of Babylon, and he shall carry them captive to Babylon, and shall kill them with the sword.'),
  ('700faf80-89ab-5f6e-ab07-502790ae6909', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 5, 5, 'Moreover I will give all the riches of this city, and all its gains, and all the precious things of it, yes, all the treasures of the kings of Judah will I give into the hand of their enemies; and they shall make them a prey, and take them, and carry them to Babylon.'),
  ('8163226f-0af2-5acd-abe2-91574569d253', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 6, 6, 'You, Pashhur, and all who dwell in your house shall go into captivity; and you shall come to Babylon, and there you shall die, and there you shall be buried, you, and all your friends, to whom you have prophesied falsely.'),
  ('d080d882-1c0d-51d5-a3ac-555199b90100', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 7, 7, 'Yahweh, you have persuaded me, and I was persuaded; you are stronger than I, and have prevailed: I am become a laughing-stock all the day, every one mocks me.'),
  ('0a3b71c3-2cdb-554e-a1ec-3a0d08f686ef', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 8, 8, 'For as often as I speak, I cry out; I cry, Violence and destruction! because the word of Yahweh is made a reproach to me, and a derision, all the day.'),
  ('18a66e7d-cf72-53c3-a713-b51cb8c73f2a', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 9, 9, 'If I say, I will not make mention of him, nor speak any more in his name, then there is in my heart as it were a burning fire shut up in my bones, and I am weary with forbearing, and I can''t [contain].'),
  ('6997a41b-8b7a-5918-abeb-fa9bfeb8a65c', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 10, 10, 'For I have heard the defaming of many, terror on every side. Denounce, and we will denounce him, [say] all my familiar friends, those who watch for my fall; perhaps he will be persuaded, and we shall prevail against him, and we shall take our revenge on him.'),
  ('b993a37e-58c4-559c-a1f8-45247236f4d1', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 11, 11, 'But Yahweh is with me as an awesome mighty one: therefore my persecutors shall stumble, and they shall not prevail; they shall be utterly disappointed, because they have not dealt wisely, even with an everlasting dishonor which shall never be forgotten.'),
  ('bae252c1-447a-58e0-acd3-2bf1b45c5749', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 12, 12, 'But, Yahweh of Armies, who tests the righteous, who sees the heart and the mind, let me see your vengeance on them; for to you have I revealed my cause.'),
  ('55a0609a-9530-5237-aa09-40f777ef59c4', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 13, 13, 'Sing to Yahweh, praise Yahweh; for he has delivered the soul of the needy from the hand of evildoers.'),
  ('785e10d9-495b-56df-af2e-5f9d61c6301f', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 14, 14, 'Cursed is the day in which I was born: don''t let the day in which my mother bore me be blessed.'),
  ('8e3ff7e7-c81c-5d60-abb8-a5a878b5bdae', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 15, 15, 'Cursed is the man who brought news to my father, saying, A boy is born to you; making him very glad.'),
  ('71be1d92-f583-5dcf-aa03-c7a35a7c3393', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 16, 16, 'Let that man be as the cities which Yahweh overthrew, and didn''t repent: and let him hear a cry in the morning, and shouting at noontime;'),
  ('6bcb7323-7cc0-5c13-ac39-405ae1e9195f', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 17, 17, 'because he didn''t kill me from the womb; and so my mother would have been my grave, and her womb always great.'),
  ('8eb8ca14-abd0-54f6-a408-261716b5dd6e', 'e1e7b596-9120-5883-ab5c-d11f6d264b58', NULL, 18, 18, 'Why came I forth out of the womb to see labor and sorrow, that my days should be consumed with shame?'),
  ('bbc32891-142d-5bbc-aaba-8c1791bab120', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 1, 1, 'The word which came to Jeremiah from Yahweh, when king Zedekiah sent to him Pashhur the son of Malchijah, and Zephaniah the son of Maaseiah, the priest, saying,'),
  ('f9429d46-1a56-5646-aa74-2b4b1cd79a65', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 2, 2, 'Please inquire of Yahweh for us; for Nebuchadnezzar king of Babylon makes war against us: perhaps Yahweh will deal with us according to all his wondrous works, that he may go up from us.'),
  ('6b14c73a-7949-5b56-a966-51a8c3d418df', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 3, 3, 'Then Jeremiah said to them, You shall tell Zedekiah:'),
  ('21ebeae7-71b1-58ac-a7e0-625b59f02a5c', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 4, 4, 'Thus says Yahweh, the God of Israel, Behold, I will turn back the weapons of war that are in your hands, with which you fight against the king of Babylon, and against the Chaldeans who besiege you, without the walls; and I will gather them into the midst of this city.'),
  ('f68a4593-fb69-5f47-a8de-c1df495fc911', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 5, 5, 'I myself will fight against you with an outstretched hand and with a strong arm, even in anger, and in wrath, and in great indignation.'),
  ('cdf7b517-5103-5b44-a481-2b8cceb99e8a', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 6, 6, 'I will strike the inhabitants of this city, both man and animal: they shall die of a great pestilence.'),
  ('feefd2ed-f4c9-57d7-af4c-fd5ef6be33d6', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 7, 7, 'Afterward, says Yahweh, I will deliver Zedekiah king of Judah, and his servants, and the people, even such as are left in this city from the pestilence, from the sword, and from the famine, into the hand of Nebuchadnezzar king of Babylon, and into the hand of their enemies, and into the hand of those who seek their life: and he shall strike them with the edge of the sword; he shall not spare them, neither have pity, nor have mercy.'),
  ('b51751df-013f-5e44-a60a-c8b7add6c810', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 8, 8, 'To this people you shall say, Thus says Yahweh: Behold, I set before you the way of life and the way of death.'),
  ('0ae80280-0962-5fcb-a947-d9b8df2ad316', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 9, 9, 'He who remains in this city shall die by the sword, and by the famine, and by the pestilence; but he who goes out, and passes over to the Chaldeans who besiege you, he shall live, and his life shall be to him for a prey.'),
  ('ba95c9a2-934d-5314-a635-5da0d912cb7c', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 10, 10, 'For I have set my face on this city for evil, and not for good, says Yahweh: it shall be given into the hand of the king of Babylon, and he shall burn it with fire.'),
  ('6e4ff32a-2fe7-5540-a722-83d3faef08ec', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 11, 11, 'Touching the house of the king of Judah, hear the word of Yahweh:'),
  ('8a9b8476-c28b-5180-a3a5-f97039419c7c', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 12, 12, 'House of David, thus says Yahweh, Execute justice in the morning, and deliver him who is robbed out of the hand of the oppressor, lest my wrath go forth like fire, and burn so that none can quench it, because of the evil of your doings.'),
  ('5a9ed041-50c9-5dd1-a0b3-7626f4d435a0', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 13, 13, 'Behold, I am against you, O inhabitant of the valley, [and] of the rock of the plain, says Yahweh; you that say, Who shall come down against us? or who shall enter into our habitations?'),
  ('c2927951-8521-5e74-a636-fddc91ab4000', '19ce0b48-5e63-5367-a8bd-4e749de9ba8d', NULL, 14, 14, 'I will punish you according to the fruit of your doings, says Yahweh; and I will kindle a fire in her forest, and it shall devour all that is around her.'),
  ('56681667-5f1e-577e-afb5-266be3e53374', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 1, 1, 'Thus said Yahweh: Go down to the house of the king of Judah, and speak there this word,'),
  ('a50d3747-7b10-5ab8-afb9-df471ea12fd1', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 2, 2, 'Say, Hear the word of Yahweh, king of Judah, who sits on the throne of David, you, and your servants, and your people who enter in by these gates.'),
  ('30917496-39c2-53a2-a984-8ac53a1faf83', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 3, 3, 'Thus says Yahweh: Execute justice and righteousness, and deliver him who is robbed out of the hand of the oppressor: and do no wrong, do no violence, to the foreigner, the fatherless, nor the widow; neither shed innocent blood in this place.'),
  ('a0cbf804-f03a-5c37-a291-f0ab76e9cba1', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 4, 4, 'For if you do this thing indeed, then shall there enter in by the gates of this house kings sitting on the throne of David, riding in chariots and on horses, he, and his servants, and his people.'),
  ('7dedde1d-d16e-5390-a104-514dee32760a', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 5, 5, 'But if you will not hear these words, I swear by myself, says Yahweh, that this house shall become a desolation.'),
  ('d6abc19d-5331-5aec-adfc-92b14fc0ecdd', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 6, 6, 'For thus says Yahweh concerning the house of the king of Judah: You are Gilead to me, [and] the head of Lebanon; [yet] surely I will make you a wilderness, [and] cities which are not inhabited.'),
  ('48bb05cb-da68-5822-ad56-2f940cd8e05c', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 7, 7, 'I will prepare destroyers against you, everyone with his weapons; and they shall cut down your choice cedars, and cast them into the fire.'),
  ('a2a516bb-f4c0-5bb5-abe1-ee26292543bc', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 8, 8, 'Many nations shall pass by this city, and they shall say every man to his neighbor, Why has Yahweh done thus to this great city?'),
  ('32c6fd26-837b-5ce7-ad96-8367268f6316', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 9, 9, 'Then they shall answer, Because they forsook the covenant of Yahweh their God, and worshiped other gods, and served them.'),
  ('7a413082-194f-5d42-a914-8b32d3dec968', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 10, 10, 'Don''t weep for the dead, neither bemoan him; but weep bitterly for him who goes away; for he shall return no more, nor see his native country.'),
  ('0e9304cd-04e1-58bc-a931-6fcd0e5d19b1', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 11, 11, 'For thus says Yahweh touching Shallum the son of Josiah, king of Judah, who reigned instead of Josiah his father, [and] who went forth out of this place: He shall not return there any more.'),
  ('2b2dd0c7-5559-5192-afa6-fccc04bed6cd', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 12, 12, 'But in the place where they have led him captive, there shall he die, and he shall see this land no more.'),
  ('fb630338-eb74-5fed-a95f-8c1fda439096', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 13, 13, 'Woe to him who builds his house by unrighteousness, and his rooms by injustice; who uses his neighbor''s service without wages, and doesn''t give him his hire;'),
  ('0415f4af-9fc3-53d5-adca-69190b804d80', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 14, 14, 'who says, I will build me a wide house and spacious rooms, and cuts him out windows; and it is ceiling with cedar, and painted with vermilion.'),
  ('f532632b-12e5-5527-a761-0142201bf582', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 15, 15, 'Shall you reign, because you strive to excel in cedar? Didn''t your father eat and drink, and do justice and righteousness? then it was well with him.'),
  ('9f928ca3-37c6-586a-aa98-12b2f2f24a87', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 16, 16, 'He judged the cause of the poor and needy; then it was well. Wasn''t this to know me? says Yahweh.'),
  ('8fb30091-afad-5817-aa96-2b683e706304', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 17, 17, 'But your eyes and your heart are not but for your covetousness, and for shedding innocent blood, and for oppression, and for violence, to do it.'),
  ('0340e174-a2c0-5c85-a228-88fe2775b38e', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 18, 18, 'Therefore thus says Yahweh concerning Jehoiakim the son of Josiah, king of Judah: they shall not lament for him, [saying], Ah my brother! or, Ah sister! They shall not lament for him, [saying] Ah lord! or, Ah his glory!'),
  ('cabf01a7-2817-55c4-a118-e5b39f00f76e', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 19, 19, 'He shall be buried with the burial of a donkey, drawn and cast forth beyond the gates of Jerusalem.'),
  ('a7f3ebf4-d778-5732-abd7-28c181ffa1fb', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 20, 20, 'Go up to Lebanon, and cry; and lift up your voice in Bashan, and cry from Abarim; for all your lovers are destroyed.'),
  ('8ef1ebfa-e439-59f0-afff-76e2c25e1a44', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 21, 21, 'I spoke to you in your prosperity; but you said, I will not hear. This has been your way from your youth, that you didn''t obey my voice.'),
  ('ea6b455a-a962-5aea-a13e-e22f80af7284', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 22, 22, 'The wind shall feed all your shepherds, and your lovers shall go into captivity: surely then you will be ashamed and confounded for all your wickedness.'),
  ('a13faab4-f999-57ea-a41c-8754e4541c45', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 23, 23, 'Inhabitant of Lebanon, who makes your nest in the cedars, how greatly to be pitied you will be when pangs come on you, the pain as of a woman in travail!'),
  ('b93a7d5a-cac4-5096-a0ac-4e86353d926d', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 24, 24, 'As I live, says Yahweh, though Coniah the son of Jehoiakim king of Judah were the signet on my right hand, yet would I pluck you there;'),
  ('b7e931ee-7368-5784-a84a-1e4e1f4b0611', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 25, 25, 'and I will give you into the hand of those who seek your life, and into the hand of them of whom you are afraid, even into the hand of Nebuchadnezzar king of Babylon, and into the hand of the Chaldeans.'),
  ('2a2f2a5b-cc78-5074-a5d2-054ffb1f35be', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 26, 26, 'I will cast you out, and your mother who bore you, into another country, where you were not born; and there you will die.'),
  ('a0abce9d-1fe8-5ad8-a0a0-b0fa731befb7', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 27, 27, 'But to the land whereunto their soul longs to return, there shall they not return.'),
  ('81701557-da45-55bf-a93c-7bc3ac45bad2', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 28, 28, 'Is this man Coniah a despised broken vessel? is he a vessel in which none delights? why are they cast out, he and his seed, and are cast into the land which they don''t know?'),
  ('08225a85-cd23-5e65-a5cb-d430139c9d31', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 29, 29, 'O earth, earth, earth, hear the word of Yahweh.'),
  ('8a9797a7-70d0-52b4-a487-ec78be73d5ee', 'ac5796cb-141b-5ab7-aabe-1711b538d934', NULL, 30, 30, 'Thus says Yahweh, Write you this man childless, a man who shall not prosper in his days; for no more shall a man of his seed prosper, sitting on the throne of David, and ruling in Judah.'),
  ('c5b4e060-55bf-565b-ad9b-0620897fe81b', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 1, 1, 'Woe to the shepherds who destroy and scatter the sheep of my pasture! says Yahweh.'),
  ('d56cb7a0-5744-5e5e-a5ae-45031ef9a2a3', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 2, 2, 'Therefore thus says Yahweh, the God of Israel, against the shepherds who feed my people: You have scattered my flock, and driven them away, and have not visited them; behold, I will visit on you the evil of your doings, says Yahweh.'),
  ('ac8863e5-a5ef-569f-a9dd-7260ce7b016e', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 3, 3, 'I will gather the remnant of my flock out of all the countries where I have driven them, and will bring them again to their folds; and they shall be fruitful and multiply.'),
  ('87263b37-997c-5e18-abde-c32433925b54', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 4, 4, 'I will set up shepherds over them, who shall feed them; and they shall fear no more, nor be dismayed, neither shall any be lacking, says Yahweh.'),
  ('f55c79c1-2c07-5414-ac3f-b9106a136120', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 5, 5, 'Behold, the days come, says Yahweh, that I will raise to David a righteous Branch, and he shall reign as king and deal wisely, and shall execute justice and righteousness in the land.'),
  ('6df6add3-64a2-5b64-acee-34be46902baa', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 6, 6, 'In his days Judah shall be saved, and Israel shall dwell safely; and this is his name by which he shall be called: Yahweh our righteousness.'),
  ('d5e33772-75f1-5cc0-ab7a-a2fb17527aff', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 7, 7, 'Therefore, behold, the days come, says Yahweh, that they shall no more say, As Yahweh lives, who brought up the children of Israel out of the land of Egypt;'),
  ('3f6965ca-8e8b-5ad1-a2c2-808d12139b90', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 8, 8, 'but, As Yahweh lives, who brought up and who led the seed of the house of Israel out of the north country, and from all the countries where I had driven them. They shall dwell in their own land.'),
  ('0ba5638d-597f-565f-a0bb-98bfbaf3080c', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 9, 9, 'Concerning the prophets. My heart within me is broken, all my bones shake; I am like a drunken man, and like a man whom wine has overcome, because of Yahweh, and because of his holy words.'),
  ('e20aa278-abb6-5d73-aec0-a7c43fc5dafe', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 10, 10, 'For the land is full of adulterers; for because of swearing the land mourns; the pastures of the wilderness are dried up. Their course is evil, and their might is not right;'),
  ('fbdb8318-a616-51e2-a746-73fb771787da', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 11, 11, 'for both prophet and priest are profane; yes, in my house have I found their wickedness, says Yahweh.'),
  ('e06874d9-b4c9-513d-a9ec-bbe05f057512', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 12, 12, 'Therefore their way shall be to them as slippery places in the darkness: they shall be driven on, and fall therein; for I will bring evil on them, even the year of their visitation, says Yahweh.'),
  ('41e498c3-f14c-5e1f-a033-cc37c0564fa3', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 13, 13, 'I have seen folly in the prophets of Samaria; they prophesied by Baal, and caused my people Israel to err.'),
  ('f704aab0-a722-5e25-aa31-c04bef0baf21', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 14, 14, 'In the prophets of Jerusalem also I have seen a horrible thing: they commit adultery, and walk in lies; and they strengthen the hands of evildoers, so that none does return from his wickedness: they are all of them become to me as Sodom, and its inhabitants as Gomorrah.'),
  ('e982fa68-bbcb-5e72-a973-88a1bca8e77e', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 15, 15, 'Therefore thus says Yahweh of Armies concerning the prophets: Behold, I will feed them with wormwood, and make them drink the water of gall; for from the prophets of Jerusalem is ungodliness gone forth into all the land.'),
  ('b884a3d6-1c13-5fba-a1fa-a6d61acc610c', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 16, 16, 'Thus says Yahweh of Armies, Don''t listen to the words of the prophets who prophesy to you: they teach you vanity; they speak a vision of their own heart, and not out of the mouth of Yahweh.'),
  ('316b58f7-b0af-55a6-a53a-f5e5e42724a3', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 17, 17, 'They say continually to those who despise me, Yahweh has said, You shall have peace; and to everyone who walks in the stubbornness of his own heart they say, No evil shall come on you.'),
  ('62a98601-4a01-594b-a867-0a3110c61aed', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 18, 18, 'For who has stood in the council of Yahweh, that he should perceive and hear his word? who has marked my word, and heard it?'),
  ('37630c36-beb1-5284-afd5-19359210d953', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 19, 19, 'Behold, the storm of Yahweh, [even his] wrath, is gone forth, yes, a whirling storm: it shall burst on the head of the wicked.'),
  ('4c1483a7-3e84-5101-a67a-abe2e3467eab', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 20, 20, 'The anger of Yahweh shall not return, until he has executed, and until he have performed the intents of his heart: in the latter days you shall understand it perfectly.'),
  ('7677d645-3009-56b5-ad3b-274ca5ad16c4', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 21, 21, 'I sent not these prophets, yet they ran: I didn''t speak to them, yet they prophesied.'),
  ('910d6765-7a22-5f64-a180-4b8155e4d2c6', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 22, 22, 'But if they had stood in my council, then had they caused my people to hear my words, and had turned them from their evil way, and from the evil of their doings.'),
  ('1c9cc04e-3c74-5f93-a2ce-4cc7e9126163', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 23, 23, 'Am I a God at hand, says Yahweh, and not a God afar off?'),
  ('a5b76720-8e32-5c97-a0d8-972dcea9e938', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 24, 24, 'Can any hide himself in secret places so that I shall not see him? says Yahweh. Don''t I fill heaven and earth? says Yahweh.'),
  ('8be7e6f2-f770-59e3-a01e-3f4247b26d13', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 25, 25, 'I have heard what the prophets have said, who prophesy lies in my name, saying, I have dreamed, I have dreamed.'),
  ('c11a3084-a7f3-59c0-ad44-1ab890877d74', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 26, 26, 'How long shall this be in the heart of the prophets who prophesy lies, even the prophets of the deceit of their own heart?'),
  ('7f0b681c-87aa-54d5-a320-a17ed54ed91f', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 27, 27, 'who think to cause my people to forget my name by their dreams which they tell every man to his neighbor, as their fathers forgot my name for Baal.'),
  ('b12ecf2c-1d4a-58ae-af07-20a2c4114308', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 28, 28, 'The prophet who has a dream, let him tell a dream; and he who has my word, let him speak my word faithfully. What is the straw to the wheat? says Yahweh.'),
  ('b45cb489-2db6-5314-a040-76bd11da65fe', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 29, 29, 'Isn''t my word like fire? says Yahweh; and like a hammer that breaks the rock in pieces?'),
  ('85e63512-ba87-55bd-ad03-0a896c0d3416', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 30, 30, 'Therefore, behold, I am against the prophets, says Yahweh, who steal my words everyone from his neighbor.'),
  ('b743c5f1-c97b-5811-abc2-cf73af9e3275', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 31, 31, 'Behold, I am against the prophets, says Yahweh, who use their tongues, and say, He says.'),
  ('bd413dc3-4707-5f50-a263-1482c2cd4f38', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 32, 32, 'Behold, I am against those who prophesy lying dreams, says Yahweh, and do tell them, and cause my people to err by their lies, and by their vain boasting: yet I didn''t send them, nor commanded them; neither do they profit this people at all, says Yahweh.'),
  ('14b519c1-9513-5c1f-aa1a-2ef7708699af', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 33, 33, 'When this people, or the prophet, or a priest, shall ask you, saying, What is the burden of Yahweh? Then you shall tell them, What burden! I will cast you off, says Yahweh.'),
  ('dc8e3884-3f3e-5f82-a67c-e91d0eb6631c', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 34, 34, 'As for the prophet, and the priest, and the people, who shall say, The burden of Yahweh, I will even punish that man and his house.'),
  ('5813c9b8-a8ba-50c7-a7fb-0670134ab73e', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 35, 35, 'You shall say everyone to his neighbor, and everyone to his brother, What has Yahweh answered? and, What has Yahweh spoken?'),
  ('8e7370e5-d2d5-558f-af96-c133c2448338', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 36, 36, 'You shall mention the burden of Yahweh no more: for every man''s own word shall be his burden; for you have perverted the words of the living God, of Yahweh of Armies our God.'),
  ('f11af180-0cd7-5a6f-a93d-175e7d9b29fe', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 37, 37, 'You shall say to the prophet, What has Yahweh answered you? and, What has Yahweh spoken?'),
  ('b6e894c0-8e27-5504-acfc-80c7e6442eda', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 38, 38, 'But if you say, The burden of Yahweh; therefore thus says Yahweh: Because you say this word, The burden of Yahweh, and I have sent to you, saying, You shall not say, The burden of Yahweh;'),
  ('f3f9f91f-6e5e-5973-a95f-8e20b2cda006', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 39, 39, 'therefore, behold, I will utterly forget you, and I will cast you off, and the city that I gave to you and to your fathers, away from my presence:'),
  ('626058f9-3dbd-50d1-afdf-848315228802', '82a1a702-f761-53bd-a9b5-6c7b430026ad', NULL, 40, 40, 'and I will bring an everlasting reproach on you, and a perpetual shame, which shall not be forgotten.'),
  ('7df2d268-b387-5f5b-ad9c-5e615db075f8', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 1, 1, 'Yahweh showed me, and behold, two baskets of figs set before the temple of Yahweh, after that Nebuchadnezzar king of Babylon had carried away captive Jeconiah the son of Jehoiakim, king of Judah, and the princes of Judah, with the craftsmen and smiths, from Jerusalem, and had brought them to Babylon.'),
  ('64534be1-6da0-5f0c-a697-6a4e66aa6a7a', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 2, 2, 'One basket had very good figs, like the figs that are first-ripe; and the other basket had very bad figs, which could not be eaten, they were so bad.'),
  ('4a8849bb-0799-529f-a1a0-3e5f06c7aac1', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 3, 3, 'Then Yahweh said to me, What do you see, Jeremiah? I said, Figs; the good figs, very good; and the bad, very bad, that can''t be eaten, they are so bad.'),
  ('c5cce32d-df78-5469-add0-4ec33eb6e948', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 4, 4, 'The word of Yahweh came to me, saying,'),
  ('77c869f9-3afa-5e75-a007-b591f3b3b3fe', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 5, 5, 'Thus says Yahweh, the God of Israel: Like these good figs, so will I regard the captives of Judah, whom I have sent out of this place into the land of the Chaldeans, for good.'),
  ('b9fd85d1-bf45-56a8-a7a9-1eabfc169f2e', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 6, 6, 'For I will set my eyes on them for good, and I will bring them again to this land: and I will build them, and not pull them down; and I will plant them, and not pluck them up.'),
  ('4fc9d7e4-a687-54d5-a3d7-fa0066e87de2', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 7, 7, 'I will give them a heart to know me, that I am Yahweh: and they shall be my people, and I will be their God; for they shall return to me with their whole heart.'),
  ('1fe3e535-6a9c-5d74-a8c0-fce39596b2d3', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 8, 8, 'As the bad figs, which can''t be eaten, they are so bad, surely thus says Yahweh, So will I give up Zedekiah the king of Judah, and his princes, and the residue of Jerusalem, who remain in this land, and those who dwell in the land of Egypt,'),
  ('56962f02-a904-5d8b-aaaf-bf6ae1f33e7b', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 9, 9, 'I will even give them up to be tossed back and forth among all the kingdoms of the earth for evil; to be a reproach and a proverb, a taunt and a curse, in all places where I shall drive them.'),
  ('6756ca9b-c6af-539a-ac0b-4fc2091ac38f', '07af11f1-9ed6-5192-afa1-19468873cc90', NULL, 10, 10, 'I will send the sword, the famine, and the pestilence, among them, until they be consumed from off the land that I gave to them and to their fathers.'),
  ('72dc617b-a1d5-5524-aa95-8d18854f10e8', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 1, 1, 'The word that came to Jeremiah concerning all the people of Judah, in the fourth year of Jehoiakim the son of Josiah, king of Judah (the same was the first year of Nebuchadnezzar king of Babylon),'),
  ('eaef2341-9b06-52b6-abd7-9ea887a9ebc8', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 2, 2, 'which Jeremiah the prophet spoke to all the people of Judah, and to all the inhabitants of Jerusalem, saying:'),
  ('419c8236-d007-5970-ae3b-2d5f7f322702', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 3, 3, 'From the thirteenth year of Josiah the son of Amon, king of Judah, even to this day, these twenty-three years, the word of Yahweh has come to me, and I have spoken to you, rising up early and speaking; but you have not listened.'),
  ('9fe89dfd-c9df-57fc-abb9-89a5db7bb777', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 4, 4, 'Yahweh has sent to you all his servants the prophets, rising up early and sending them (but you have not listened, nor inclined your ear to hear)'),
  ('de67016d-07d1-5fe7-a5f4-2dc971818ca5', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 5, 5, 'saying, Return now everyone from his evil way, and from the evil of your doings, and dwell in the land that Yahweh has given to you and to your fathers, from of old and even forevermore;'),
  ('4708e58a-e8d5-5b3e-a38a-0323fe16b29c', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 6, 6, 'and don''t go after other gods to serve them or worship them, and don''t provoke me to anger with the work of your hands; and I will do you no harm.'),
  ('005a1895-847c-5323-a754-050073e7c526', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 7, 7, 'Yet you have not listened to me, says Yahweh; that you may provoke me to anger with the work of your hands to your own hurt.'),
  ('a09fbba7-56af-5218-a15d-fc70f64a9545', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 8, 8, 'Therefore thus says Yahweh of Armies: Because you have not heard my words,'),
  ('e86feafc-b8a6-5668-a44a-206ddcdc9712', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 9, 9, 'behold, I will send and take all the families of the north, says Yahweh, and [I will send] to Nebuchadnezzar the king of Babylon, my servant, and will bring them against this land, and against its inhabitants, and against all these nations around; and I will utterly destroy them, and make them an astonishment, and a hissing, and perpetual desolations.'),
  ('41c4c479-18b1-5fc7-a37d-bac8ca474892', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 10, 10, 'Moreover I will take from them the voice of mirth and the voice of gladness, the voice of the bridegroom and the voice of the bride, the sound of the millstones, and the light of the lamp.'),
  ('66001344-b5e3-5924-a9d4-bdbcd1c6fd03', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 11, 11, 'This whole land shall be a desolation, and an astonishment; and these nations shall serve the king of Babylon seventy years.'),
  ('d9dba1be-7399-551b-ac00-3506c077dd30', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 12, 12, 'It shall happen, when seventy years are accomplished, that I will punish the king of Babylon, and that nation, says Yahweh, for their iniquity, and the land of the Chaldeans; and I will make it desolate forever.'),
  ('0bbf860d-d12a-5d34-ae37-aee5a4e3000d', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 13, 13, 'I will bring on that land all my words which I have pronounced against it, even all that is written in this book, which Jeremiah has prophesied against all the nations.'),
  ('3523972e-c7da-56d3-ab0e-0ba48c580d36', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 14, 14, 'For many nations and great kings shall make bondservants of them, even of them; and I will recompense them according to their deeds, and according to the work of their hands.'),
  ('e76dded0-6a43-57f8-a855-945ba6c697f5', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 15, 15, 'For thus says Yahweh, the God of Israel, to me: take this cup of the wine of wrath at my hand, and cause all the nations, to whom I send you, to drink it.'),
  ('2ba5dcb3-a2ab-5ecb-aaba-f349db6ef3cc', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 16, 16, 'They shall drink, and reel back and forth, and be mad, because of the sword that I will send among them.'),
  ('06c868c6-6736-57f0-a7a4-38831dfe2964', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 17, 17, 'Then took I the cup at Yahweh''s hand, and made all the nations to drink, to whom Yahweh had sent me:'),
  ('794f47d1-d892-5dc1-a3a3-db1568c7f212', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 18, 18, '[to wit], Jerusalem, and the cities of Judah, and its kings, and its princes, to make them a desolation, an astonishment, a hissing, and a curse, as it is this day;'),
  ('b51b6710-38b7-5fda-a29f-fb5bf13c2732', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 19, 19, 'Pharaoh king of Egypt, and his servants, and his princes, and all his people;'),
  ('360fcac4-c2a7-57a1-ab42-8b397413c2db', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 20, 20, 'and all the mixed people, and all the kings of the land of the Uz, and all the kings of the Philistines, and Ashkelon, and Gaza, and Ekron, and the remnant of Ashdod;'),
  ('24c0a9d7-328d-598f-a207-38280213e908', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 21, 21, 'Edom, and Moab, and the children of Ammon;'),
  ('eb4dc953-091c-5413-ae37-a6a9d09d25be', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 22, 22, 'and all the kings of Tyre, and all the kings of Sidon, and the kings of the isle which is beyond the sea;'),
  ('5535fd2b-4600-58a6-a893-11412e151e01', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 23, 23, 'Dedan, and Tema, and Buz, and all who have the corners [of their hair] cut off;'),
  ('0aff2406-2d3d-5197-ab7f-2dea1b1e9de5', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 24, 24, 'and all the kings of Arabia, and all the kings of the mixed people who dwell in the wilderness;'),
  ('bae18edb-0cdf-5f01-a679-7f4abed68797', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 25, 25, 'and all the kings of Zimri, and all the kings of Elam, and all the kings of the Medes;'),
  ('6f0b628a-2efe-55f9-a70c-f5474e8ecc35', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 26, 26, 'and all the kings of the north, far and near, one with another; and all the kingdoms of the world, which are on the surface of the earth: and the king of Sheshach shall drink after them.'),
  ('eda8975f-f24a-545e-a14b-b0f00623da5a', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 27, 27, 'You shall tell them, Thus says Yahweh of Armies, the God of Israel: Drink, and be drunk, vomit, fall, and rise no more, because of the sword which I will send among you.'),
  ('975cd4b4-f2b0-56e2-ae1b-7a073fde82e6', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 28, 28, 'It shall be, if they refuse to take the cup at your hand to drink, then you shall tell them, Thus says Yahweh of Armies: You shall surely drink.'),
  ('4b792ad8-2569-53d2-a41e-9e2dc1de9baa', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 29, 29, 'For, behold, I begin to work evil at the city which is called by my name; and should you be utterly unpunished? You shall not be unpunished; for I will call for a sword on all the inhabitants of the earth, says Yahweh of Armies.'),
  ('d8b7b7e7-37e9-57d6-af24-16e2c61b16e9', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 30, 30, 'Therefore prophesy you against them all these words, and tell them, Yahweh will roar from on high, and utter his voice from his holy habitation; he will mightily roar against his fold; he will give a shout, as those who tread [the grapes], against all the inhabitants of the earth.'),
  ('c48a14ab-5eff-51de-a81c-93ba4e7cb090', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 31, 31, 'A noise shall come even to the end of the earth; for Yahweh has a controversy with the nations; he will enter into judgment with all flesh: as for the wicked, he will give them to the sword, says Yahweh.'),
  ('67eb3953-b4fd-51fb-adaa-586027caae96', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 32, 32, 'Thus says Yahweh of Armies, Behold, evil shall go forth from nation to nation, and a great storm shall be raised up from the uttermost parts of the earth.'),
  ('d59d35d6-9186-5950-ad90-943399881d1a', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 33, 33, 'The slain of Yahweh shall be at that day from one end of the earth even to the other end of the earth: they shall not be lamented, neither gathered, nor buried; they shall be dung on the surface of the ground.'),
  ('1dcd24bf-534f-5743-a9ce-e835b796e4f7', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 34, 34, 'Wail, you shepherds, and cry; and wallow [in ashes], you principal of the flock; for the days of your slaughter and of your dispersions are fully come, and you shall fall like a goodly vessel.'),
  ('2f5875ab-4aa2-5ccd-a74f-cac9b0b49d4b', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 35, 35, 'The shepherds shall have no way to flee, nor the principal of the flock to escape.'),
  ('029bd27d-122e-532b-ad0c-684d5c507581', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 36, 36, 'A voice of the cry of the shepherds, and the wailing of the principal of the flock! for Yahweh lays waste their pasture.'),
  ('172f751f-697c-5cb9-a1b7-d5ad479164e7', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 37, 37, 'The peaceable folds are brought to silence because of the fierce anger of Yahweh.'),
  ('a06f45d0-4739-507d-a010-b4eda94b54a6', '55e9ff38-cc46-5280-a749-01f9f2b4a358', NULL, 38, 38, 'He has left his covert, as the lion; for their land is become an astonishment because of the fierceness of the oppressing [sword], and because of his fierce anger.'),
  ('dc3d59df-506c-50bc-ad8a-2543e71198ed', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 1, 1, 'In the beginning of the reign of Jehoiakim the son of Josiah, king of Judah, came this word from Yahweh, saying,'),
  ('28a44baf-304a-5cc8-a2e1-06f43d102c2f', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 2, 2, 'Thus says Yahweh: Stand in the court of Yahweh''s house, and speak to all the cities of Judah, which come to worship in Yahweh''s house, all the words that I command you to speak to them; don''t diminish a word.'),
  ('a35b3845-4c28-5a48-a85c-0fbbf614141a', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 3, 3, 'It may be they will listen, and turn every man from his evil way; that I may repent me of the evil which I purpose to do to them because of the evil of their doings.'),
  ('c48db080-0e9a-5c7f-ae8c-59f698a17743', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 4, 4, 'You shall tell them, Thus says Yahweh: If you will not listen to me, to walk in my law, which I have set before you,'),
  ('29fb9c1f-7aa2-5ccb-a02a-e978f4a2f074', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 5, 5, 'to listen to the words of my servants the prophets, whom I send to you, even rising up early and sending them, but you have not listened;'),
  ('147b1a1b-d0e8-5e63-aee3-77476916cfb6', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 6, 6, 'then will I make this house like Shiloh, and will make this city a curse to all the nations of the earth.'),
  ('3b278b9b-a2e5-5377-a5cc-377ff725ca8a', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 7, 7, 'The priests and the prophets and all the people heard Jeremiah speaking these words in the house of Yahweh.'),
  ('135fdafe-bd80-5034-ab09-9490df0f7a6e', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 8, 8, 'It happened, when Jeremiah had made an end of speaking all that Yahweh had commanded him to speak to all the people, that the priests and the prophets and all the people laid hold on him, saying, You shall surely die.'),
  ('704f5e68-04b6-5800-ae74-795a0f727ff5', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 9, 9, 'Why have you prophesied in the name of Yahweh, saying, This house shall be like Shiloh, and this city shall be desolate, without inhabitant? All the people were gathered to Jeremiah in the house of Yahweh.'),
  ('78b8506a-0596-5bd9-a96e-2f0be76a53f3', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 10, 10, 'When the princes of Judah heard these things, they came up from the king''s house to the house of Yahweh; and they sat in the entry of the new gate of Yahweh''s [house].'),
  ('ba80247b-a7fc-5699-ab44-ea363d870431', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 11, 11, 'Then spoke the priests and the prophets to the princes and to all the people, saying, This man is worthy of death; for he has prophesied against this city, as you have heard with your ears.'),
  ('41879836-afa4-5547-a8b9-017e22eac27e', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 12, 12, 'Then spoke Jeremiah to all the princes and to all the people, saying, Yahweh sent me to prophesy against this house and against this city all the words that you have heard.'),
  ('8db3174c-5784-55de-a135-3c3342ed626f', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 13, 13, 'Now therefore amend your ways and your doings, and obey the voice of Yahweh your God; and Yahweh will repent him of the evil that he has pronounced against you.'),
  ('8f38195d-c5e9-5e1d-a6f2-63348763c0f6', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 14, 14, 'But as for me, behold, I am in your hand: do with me as is good and right in your eyes.'),
  ('43e38120-e406-5365-af3e-99962a077c1d', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 15, 15, 'Only know for certain that, if you put me to death, you will bring innocent blood on yourselves, and on this city, and on its inhabitants; for of a truth Yahweh has sent me to you to speak all these words in your ears.'),
  ('875d2f6e-d79a-525d-a4bf-5f02c622a336', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 16, 16, 'Then the princes and all the people said to the priests and to the prophets: This man is not worthy of death; for he has spoken to us in the name of Yahweh our God.'),
  ('74f795cc-e344-59a7-a50e-e4f231f63feb', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 17, 17, 'Then rose up certain of the elders of the land, and spoke to all the assembly of the people, saying,'),
  ('93653a1f-24a7-587a-af8e-61dd67a45bec', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 18, 18, 'Micah the Morashtite prophesied in the days of Hezekiah king of Judah; and he spoke to all the people of Judah, saying, Thus says Yahweh of Armies: Zion shall be plowed as a field, and Jerusalem shall become heaps, and the mountain of the house as the high places of a forest.'),
  ('8c6ecdde-18f1-5a56-a891-4dcbbd406bc4', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 19, 19, 'Did Hezekiah king of Judah and all Judah put him to death? Didn''t he fear Yahweh, and entreat the favor of Yahweh, and Yahweh relented of the disaster which he had pronounced against them? Thus should we commit great evil against our own souls.'),
  ('1cf13479-33a9-599e-ae98-0db324e63b53', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 20, 20, 'There was also a man who prophesied in the name of Yahweh, Uriah the son of Shemaiah of Kiriath Jearim; and he prophesied against this city and against this land according to all the words of Jeremiah:'),
  ('45699de0-409d-543f-a61d-e2d0ec4e389e', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 21, 21, 'and when Jehoiakim the king, with all his mighty men, and all the princes, heard his words, the king sought to put him to death; but when Uriah heard it, he was afraid, and fled, and went into Egypt:'),
  ('17787f7f-a6c3-53af-ad08-ffdff1a3aa03', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 22, 22, 'and Jehoiakim the king sent men into Egypt, [namely], Elnathan the son of Achbor, and certain men with him, into Egypt;'),
  ('f9c73cb8-8811-523a-a9af-7a366c992559', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 23, 23, 'and they fetched forth Uriah out of Egypt, and brought him to Jehoiakim the king, who killed him with the sword, and cast his dead body into the graves of the common people.'),
  ('e48af63b-ab6c-54e2-ae06-ec09a04a9415', '29f4f3f6-121e-5793-a4b6-8d87b98dce23', NULL, 24, 24, 'But the hand of Ahikam the son of Shaphan was with Jeremiah, that they should not give him into the hand of the people to put him to death.'),
  ('a3710913-0b35-57af-a75e-ba3d18fb9aa6', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 1, 1, 'In the beginning of the reign of Jehoiakim the son of Josiah, king of Judah, came this word to Jeremiah from Yahweh, saying,'),
  ('c4875e52-375d-5b25-ab29-232724e5a98d', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 2, 2, 'Thus says Yahweh to me: Make bonds and bars, and put them on your neck;'),
  ('4fc5397c-bd8a-5697-ae05-8638b8d8aa5a', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 3, 3, 'and send them to the king of Edom, and to the king of Moab, and to the king of the children of Ammon, and to the king of Tyre, and to the king of Sidon, by the hand of the messengers who come to Jerusalem to Zedekiah king of Judah;'),
  ('9e13bbb2-4fe4-5b11-ab4e-3b41dc6f1255', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 4, 4, 'and give them a command to their masters, saying, Thus says Yahweh of Armies, the God of Israel, You shall tell your masters:'),
  ('ef7b7992-ec41-5ba9-a2cb-f3dcbf8fdac3', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 5, 5, 'I have made the earth, the men and the animals that are on the surface of the earth, by my great power and by my outstretched arm; and I give it to whom it seems right to me.'),
  ('01553209-0fb5-587d-ae7f-8bf681b18e3b', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 6, 6, 'Now have I given all these lands into the hand of Nebuchadnezzar the king of Babylon, my servant; and the animals of the field also have I given him to serve him.'),
  ('6ab12ed8-908c-5f77-ae29-b419bc2fe226', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 7, 7, 'All the nations shall serve him, and his son, and his son''s son, until the time of his own land come: and then many nations and great kings shall make him their bondservant.'),
  ('699fc21c-639a-541d-a73e-f37764243b44', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 8, 8, 'It shall happen, that the nation and the kingdom which will not serve the same Nebuchadnezzar king of Babylon, and that will not put their neck under the yoke of the king of Babylon, that nation will I punish, says Yahweh, with the sword, and with the famine, and with the pestilence, until I have consumed them by his hand.'),
  ('4691c69a-4f94-5045-a4fc-0a6574409d32', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 9, 9, 'But as for you, don''t you listen to your prophets, nor to your diviners, nor to your dreams, nor to your soothsayers, nor to your sorcerers, who speak to you, saying, You shall not serve the king of Babylon:'),
  ('53aebf4a-53d1-57e1-a662-c81890275c39', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 10, 10, 'for they prophesy a lie to you, to remove you far from your land, and that I should drive you out, and you should perish.'),
  ('167557bc-fc16-595c-a625-15844b536d01', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 11, 11, 'But the nation that shall bring their neck under the yoke of the king of Babylon, and serve him, that [nation] will I let remain in their own land, says Yahweh; and they shall till it, and dwell therein.'),
  ('da83bfde-9cdd-511b-aaed-04fcf006118e', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 12, 12, 'I spoke to Zedekiah king of Judah according to all these words, saying, Bring your necks under the yoke of the king of Babylon, and serve him and his people, and live.'),
  ('9c7b512c-1152-594b-ae77-9c2de62cde49', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 13, 13, 'Why will you die, you and your people, by the sword, by the famine, and by the pestilence, as Yahweh has spoken concerning the nation that will not serve the king of Babylon?'),
  ('3f36343e-e249-5149-a0b9-1865d7fe3604', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 14, 14, 'Don''t listen to the words of the prophets who speak to you, saying, You shall not serve the king of Babylon; for they prophesy a lie to you.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3022d68a-48e1-5c0f-add4-d9ae1e894f83', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 15, 15, 'For I have not sent them, says Yahweh, but they prophesy falsely in my name; that I may drive you out, and that you may perish, you, and the prophets who prophesy to you.'),
  ('4b1de7aa-25aa-579b-a0bb-7e6ed0f4a4cf', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 16, 16, 'Also I spoke to the priests and to all this people, saying, Thus says Yahweh: Don''t listen to the words of your prophets who prophesy to you, saying, Behold, the vessels of Yahweh''s house shall now shortly be brought again from Babylon; for they prophesy a lie to you.'),
  ('731c9464-7e4c-5bc4-a5ad-a7a222cedbfc', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 17, 17, 'Don''t listen to them; serve the king of Babylon, and live: why should this city become a desolation?'),
  ('6a69b884-252d-5345-a07d-a4f810a6c9c3', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 18, 18, 'But if they be prophets, and if the word of Yahweh be with them, let them now make intercession to Yahweh of Armies, that the vessels which are left in the house of Yahweh, and in the house of the king of Judah, and at Jerusalem, don''t go to Babylon.'),
  ('8971e34a-67ce-5793-ad27-94faa1056bb6', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 19, 19, 'For thus says Yahweh of Armies concerning the pillars, and concerning the sea, and concerning the bases, and concerning the residue of the vessels that are left in this city,'),
  ('dca45b55-59b3-55c6-a3a1-dbf91b76341a', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 20, 20, 'which Nebuchadnezzar king of Babylon didn''t take, when he carried away captive Jeconiah the son of Jehoiakim, king of Judah, from Jerusalem to Babylon, and all the nobles of Judah and Jerusalem;'),
  ('1f521000-60ff-50fa-a885-611c9e021f34', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 21, 21, 'yes, thus says Yahweh of Armies, the God of Israel, concerning the vessels that are left in the house of Yahweh, and in the house of the king of Judah, and at Jerusalem:'),
  ('8d555b34-757b-5dec-a367-53bbc5444ae0', '0785e805-6256-5958-a77b-4fa3bee2405f', NULL, 22, 22, 'They shall be carried to Babylon, and there shall they be, until the day that I visit them, says Yahweh; then will I bring them up, and restore them to this place.'),
  ('9b0307d8-4343-51a8-ae6a-a6864304eafd', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 1, 1, 'It happened the same year, in the beginning of the reign of Zedekiah king of Judah, in the fourth year, in the fifth month, that Hananiah the son of Azzur, the prophet, who was of Gibeon, spoke to me in the house of Yahweh, in the presence of the priests and of all the people, saying,'),
  ('4ac2b8b4-35b7-5e0c-a79c-35aa943677a8', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 2, 2, 'Thus speaks Yahweh of Armies, the God of Israel, saying, I have broken the yoke of the king of Babylon.'),
  ('7e89fed1-1248-59ec-af9f-f68aaea5815b', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 3, 3, 'Within two full years will I bring again into this place all the vessels of Yahweh''s house, that Nebuchadnezzar king of Babylon took away from this place, and carried to Babylon:'),
  ('efd02634-7959-56f4-aae6-9da4cca7da59', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 4, 4, 'and I will bring again to this place Jeconiah the son of Jehoiakim, king of Judah, with all the captives of Judah, who went to Babylon, says Yahweh; for I will break the yoke of the king of Babylon.'),
  ('86aea5eb-82f5-51db-a27d-5e9a7ec60b70', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 5, 5, 'Then the prophet Jeremiah said to the prophet Hananiah in the presence of the priests, and in the presence of all the people who stood in the house of Yahweh,'),
  ('bfb345c4-8d68-55ef-a12c-611c3a72f0fc', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 6, 6, 'even the prophet Jeremiah said, Amen: Yahweh do so; Yahweh perform your words which you have prophesied, to bring again the vessels of Yahweh''s house, and all them of the captivity, from Babylon to this place.'),
  ('8e36450c-5895-5033-aa8c-af277ccd29f0', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 7, 7, 'Nevertheless hear you now this word that I speak in your ears, and in the ears of all the people:'),
  ('e229f074-569c-578f-a9c3-9e4194ca6bb9', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 8, 8, 'The prophets who have been before me and before you of old prophesied against many countries, and against great kingdoms, of war, and of evil, and of pestilence.'),
  ('a9dda604-018b-5c2b-accc-e9764b9b338f', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 9, 9, 'The prophet who prophesies of peace, when the word of the prophet shall happen, then shall the prophet be known, that Yahweh has truly sent him.'),
  ('6cd8a59c-9c0c-56ee-a116-7c7b11584951', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 10, 10, 'Then Hananiah the prophet took the bar from off the prophet Jeremiah''s neck, and broke it.'),
  ('e7d62908-bb8a-5a1c-a120-f2a23a6df169', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 11, 11, 'Hananiah spoke in the presence of all the people, saying, Thus says Yahweh: Even so will I break the yoke of Nebuchadnezzar king of Babylon within two full years from off the neck of all the nations. The prophet Jeremiah went his way.'),
  ('23648bdb-85f9-569b-ad57-e2ac091bbba8', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 12, 12, 'Then the word of Yahweh came to Jeremiah, after that Hananiah the prophet had broken the bar from off the neck of the prophet Jeremiah, saying,'),
  ('6556abce-7acf-5fd1-a4fb-09673522de9a', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 13, 13, 'Go, and tell Hananiah, saying, Thus says Yahweh: You have broken the bars of wood; but you have made in their place bars of iron.'),
  ('d85e273c-efc8-5197-a853-7574a55205de', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 14, 14, 'For thus says Yahweh of Armies, the God of Israel: I have put a yoke of iron on the neck of all these nations, that they may serve Nebuchadnezzar king of Babylon; and they shall serve him: and I have given him the animals of the field also.'),
  ('9fbb9073-a125-5e8d-a0f1-53666afa62e0', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 15, 15, 'Then the prophet Jeremiah said to Hananiah the prophet, Hear now, Hananiah: Yahweh has not sent you; but you make this people to trust in a lie.'),
  ('f81dbb96-d4a7-5544-a843-0e250101a6bc', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 16, 16, 'Therefore thus says Yahweh, Behold, I will send you away from off the surface of the earth: this year you shall die, because you have spoken rebellion against Yahweh.'),
  ('0c74c7f0-82cf-51a8-a82a-3790cce6daf6', '8fd1aed9-3ff9-58ff-a8e3-1f964e8afa5d', NULL, 17, 17, 'So Hananiah the prophet died the same year in the seventh month.'),
  ('b780ad9e-5df2-5f50-a18c-9a5a5c74ccef', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 1, 1, 'Now these are the words of the letter that Jeremiah the prophet sent from Jerusalem to the residue of the elders of the captivity, and to the priests, and to the prophets, and to all the people, whom Nebuchadnezzar had carried away captive from Jerusalem to Babylon,'),
  ('a7b80dc0-57bf-5def-a128-9fe5531a06c6', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 2, 2, '(after that Jeconiah the king, and the queen mother, and the eunuchs, [and] the princes of Judah and Jerusalem, and the craftsmen, and the smiths, were departed from Jerusalem),'),
  ('2c766303-e36c-5e06-aac1-233384403ed5', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 3, 3, 'by the hand of Elasah the son of Shaphan, and Gemariah the son of Hilkiah, (whom Zedekiah king of Judah sent to Babylon to Nebuchadnezzar king of Babylon), saying,'),
  ('12507d67-7eb3-5f0c-ad7e-3c0af7a0eb22', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 4, 4, 'Thus says Yahweh of Armies, the God of Israel, to all the captivity, whom I have caused to be carried away captive from Jerusalem to Babylon:'),
  ('7014c184-bea1-52af-a181-3c7f79c675b3', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 5, 5, 'Build houses, and dwell in them; and plant gardens, and eat the fruit of them.'),
  ('b393c3c3-7d25-5d2f-afb3-c36bd3261ca3', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 6, 6, 'Take wives, and father sons and daughters; and take wives for your sons, and give your daughters to husbands, that they may bear sons and daughters; and multiply there, and don''t be diminished.'),
  ('515157d6-b102-597a-acd9-77311de8a41a', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 7, 7, 'Seek the peace of the city where I have caused you to be carried away captive, and pray to Yahweh for it; for in its peace you shall have peace.'),
  ('6beac477-7b28-56eb-adc7-10bd4c726805', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 8, 8, 'For thus says Yahweh of Armies, the God of Israel: Don''t let your prophets who are in the midst of you, and your diviners, deceive you; neither listen to your dreams which you cause to be dreamed.'),
  ('458e6eaf-adc4-51af-a921-8b399301e3a3', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 9, 9, 'For they prophesy falsely to you in my name: I have not sent them, says Yahweh.'),
  ('e5570469-d9f3-54c3-a370-1b6ea9eac49c', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 10, 10, 'For thus says Yahweh, After seventy years are accomplished for Babylon, I will visit you, and perform my good word toward you, in causing you to return to this place.'),
  ('fe5cb85e-a390-5151-abe0-240d4e1f67f7', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 11, 11, 'For I know the thoughts that I think toward you, says Yahweh, thoughts of peace, and not of evil, to give you hope and a future.'),
  ('7af11240-9d90-5192-a212-71e5dfc5d4b5', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 12, 12, 'You shall call on me, and you shall go and pray to me, and I will listen to you.'),
  ('7b1d4bed-a95a-55b6-ae27-ec7a517aa9c0', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 13, 13, 'You shall seek me, and find me, when you shall search for me with all your heart.'),
  ('096ebbcf-4c37-50cb-a359-2c3403088e98', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 14, 14, 'I will be found by you, says Yahweh, and I will turn again your captivity, and I will gather you from all the nations, and from all the places where I have driven you, says Yahweh; and I will bring you again to the place from where I caused you to be carried away captive.'),
  ('447d276b-379c-5434-ac0c-5ff70ee5670e', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 15, 15, 'Because you have said, Yahweh has raised us up prophets in Babylon;'),
  ('56483992-d883-58b8-a784-b6eca65c475d', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 16, 16, 'thus says Yahweh concerning the king who sits on the throne of David, and concerning all the people who dwell in this city, your brothers who haven''t gone forth with you into captivity;'),
  ('29d66ab0-63e4-5913-a5d0-98543bfef90f', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 17, 17, 'thus says Yahweh of Armies; Behold, I will send on them the sword, the famine, and the pestilence, and will make them like vile figs, that can''t be eaten, they are so bad.'),
  ('c617b359-575c-5915-ac05-99ef308212b8', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 18, 18, 'I will pursue after them with the sword, with the famine, and with the pestilence, and will deliver them to be tossed back and forth among all the kingdoms of the earth, to be an object of horror, and an astonishment, and a hissing, and a reproach, among all the nations where I have driven them;'),
  ('d00ebb3b-2caa-5c78-abdb-f8d2a44cf3f5', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 19, 19, 'because they have not listened to my words, says Yahweh, with which I sent to them my servants the prophets, rising up early and sending them; but you would not hear, says Yahweh.'),
  ('429f4e23-aa80-5519-af47-ad6603bd17a3', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 20, 20, 'Hear therefore the word of Yahweh, all you of the captivity, whom I have sent away from Jerusalem to Babylon.'),
  ('56ac3ece-6e12-54b5-abc1-2cc41c75cb50', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 21, 21, 'Thus says Yahweh of Armies, the God of Israel, concerning Ahab the son of Kolaiah, and concerning Zedekiah the son of Maaseiah, who prophesy a lie to you in my name: Behold, I will deliver them into the hand of Nebuchadnezzar king of Babylon; and he shall kill them before your eyes;'),
  ('3b34d318-a363-5eee-a5be-197c3aca0c3a', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 22, 22, 'and of them shall be taken up a curse by all the captives of Judah who are in Babylon, saying, Yahweh make you like Zedekiah and like Ahab, whom the king of Babylon roasted in the fire;'),
  ('ece3cbd1-d351-5899-a00a-5f01a581f2a0', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 23, 23, 'because they have worked folly in Israel, and have committed adultery with their neighbors'' wives, and have spoken words in my name falsely, which I didn''t command them; and I am he who knows, and am witness, says Yahweh.'),
  ('19d89bc4-e8ce-5c2d-a3f3-4ee944398f19', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 24, 24, 'Concerning Shemaiah the Nehelamite you shall speak, saying,'),
  ('2161957b-681b-55b5-a197-0862cda36f5d', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 25, 25, 'Thus speaks Yahweh of Armies, the God of Israel, saying, Because you have sent letters in your own name to all the people who are at Jerusalem, and to Zephaniah the son of Maaseiah, the priest, and to all the priests, saying,'),
  ('e5b50adb-0a93-502a-a5dc-22cf6c0e08be', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 26, 26, 'Yahweh has made you priest in the place of Jehoiada the priest, that there may be officers in the house of Yahweh, for every man who is mad, and makes himself a prophet, that you should put him in the stocks and in shackles.'),
  ('cbf90c71-0ac8-5396-ada4-2ca4e9cbb6dc', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 27, 27, 'Now therefore, why have you not rebuked Jeremiah of Anathoth, who makes himself a prophet to you,'),
  ('fc0a869e-f1d1-5c25-a562-2b4a7ef63d62', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 28, 28, 'because he has sent to us in Babylon, saying, [The captivity] is long: build houses, and dwell in them; and plant gardens, and eat the fruit of them?'),
  ('1d621584-5cde-5157-a27b-78ff5b0ba97f', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 29, 29, 'Zephaniah the priest read this letter in the ears of Jeremiah the prophet.'),
  ('9dbb21a3-a09f-5e38-afdf-1a6e3b2ea204', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 30, 30, 'Then came the word of Yahweh to Jeremiah, saying,'),
  ('68c3c788-c672-59bd-a0ee-0cbd200542fd', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 31, 31, 'Send to all them of the captivity, saying, Thus says Yahweh concerning Shemaiah the Nehelamite: Because Shemaiah has prophesied to you, and I didn''t send him, and he has caused you to trust in a lie;'),
  ('5155b8b6-58a5-5021-a8f7-83e74cacba90', '4d1d4ceb-131d-5a30-a563-2516684807bd', NULL, 32, 32, 'therefore thus says Yahweh, Behold, I will punish Shemaiah the Nehelamite, and his seed; he shall not have a man to dwell among this people, neither shall he see the good that I will do to my people, says Yahweh, because he has spoken rebellion against Yahweh.'),
  ('d66f1d91-94f1-543c-a8c2-ae4cb3d30826', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 1, 1, 'The word that came to Jeremiah from Yahweh, saying,'),
  ('cd2bb299-628f-5425-adb9-8ad3b2a53df8', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 2, 2, 'Thus speaks Yahweh, the God of Israel, saying, Write all the words that I have spoken to you in a book.'),
  ('6618b1c6-1989-56dd-aac4-2f2df407e600', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 3, 3, 'For, behold, the days come, says Yahweh, that I will turn again the captivity of my people Israel and Judah, says Yahweh; and I will cause them to return to the land that I gave to their fathers, and they shall possess it.'),
  ('c8730b0a-0415-51a1-a123-30d85decc71b', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 4, 4, 'These are the words that Yahweh spoke concerning Israel and concerning Judah.'),
  ('bbc6b5e6-8718-57ca-a2f2-ebb267965394', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 5, 5, 'For thus says Yahweh: We have heard a voice of trembling, of fear, and not of peace.'),
  ('c45a4a78-5ebf-5ca4-a958-a424158ff1e4', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 6, 6, 'Ask now, and see whether a man does travail with child: why do I see every man with his hands on his waist, as a woman in travail, and all faces are turned into paleness?'),
  ('50cbfeff-38f8-5a6e-a1f6-4fd9f6f4ecb2', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 7, 7, 'Alas! for that day is great, so that none is like it: it is even the time of Jacob''s trouble; but he shall be saved out of it.'),
  ('4b16b06a-e56c-5186-ab4c-c49cebbc2eb8', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 8, 8, 'It shall come to pass in that day, says Yahweh of Armies, that I will break his yoke from off your neck, and will burst your bonds; and strangers shall no more make him their bondservant;'),
  ('c12dcb19-5608-5293-a7af-f2b8a3e68228', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 9, 9, 'but they shall serve Yahweh their God, and David their king, whom I will raise up to them.'),
  ('8d0a6a45-e1c7-529c-af9c-af4e2af7a5e5', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 10, 10, 'Therefore don''t you be afraid, O Jacob my servant, says Yahweh; neither be dismayed, Israel: for, behold, I will save you from afar, and your seed from the land of their captivity; and Jacob shall return, and shall be quiet and at ease, and none shall make him afraid.'),
  ('ffdc4bd8-2b17-5843-a37d-b624d6dc8e39', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 11, 11, 'For I am with you, says Yahweh, to save you: for I will make a full end of all the nations where I have scattered you, but I will not make a full end of you; but I will correct you in measure, and will in no way leave you unpunished.'),
  ('b68c60b6-551e-5bb0-a331-dc242e43e7db', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 12, 12, 'For thus says Yahweh, Your hurt is incurable, and your wound grievous.'),
  ('d0f99868-361b-5ce4-a691-df955910c8ab', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 13, 13, 'There is none to plead your cause, that you may be bound up: you have no healing medicines.'),
  ('7e675289-9e58-5119-ab25-98753a6a00bd', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 14, 14, 'All your lovers have forgotten you; they don''t seek you: for I have wounded you with the wound of an enemy, with the chastisement of a cruel one, for the greatness of your iniquity, because your sins were increased.'),
  ('5698347e-fbce-5a0e-a09c-7e61aa565f5f', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 15, 15, 'Why do you cry for your hurt? Your pain is incurable: for the greatness of your iniquity, because your sins were increased, I have done these things to you.'),
  ('4ee4c472-dcf2-5d39-a56d-da860f63d9da', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 16, 16, 'Therefore all those who devour you shall be devoured; and all your adversaries, everyone of them, shall go into captivity; and those who despoil you shall be a spoil, and all who prey on you will I give for a prey.'),
  ('b1f96569-0d32-56c3-ae2a-47f3952bcb93', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 17, 17, 'For I will restore health to you, and I will heal you of your wounds, says Yahweh; because they have called you an outcast, [saying], It is Zion, whom no man seeks after.'),
  ('c37d69b4-72b5-5931-aadb-3820c793bc77', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 18, 18, 'Thus says Yahweh: Behold, I will turn again the captivity of Jacob''s tents, and have compassion on his dwelling places; and the city shall be built on its own hill, and the palace shall be inhabited in its own way.'),
  ('89aa8fec-2f66-56b4-a392-e416b8974963', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 19, 19, 'Out of them shall proceed thanksgiving and the voice of those who make merry: and I will multiply them, and they shall not be few; I will also glorify them, and they shall not be small.'),
  ('b1cfd679-fe3b-56d4-a014-2015da3cf15d', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 20, 20, 'Their children also shall be as before, and their congregation shall be established before me; and I will punish all who oppress them.'),
  ('886e0e45-bca7-51b8-ad8f-472d2c5484cd', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 21, 21, 'Their prince shall be of themselves, and their ruler shall proceed from the midst of them; and I will cause him to draw near, and he shall approach to me: for who is he who has had boldness to approach to me? says Yahweh.'),
  ('b2d38437-4c5f-5751-a1c0-c618829c4b7e', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 22, 22, 'You shall be my people, and I will be your God.'),
  ('88fa038b-c4fb-580d-afbb-354f3c9d3938', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 23, 23, 'Behold, the storm of Yahweh, [even his] wrath, is gone forth, a sweeping storm: it shall burst on the head of the wicked.'),
  ('d20f0754-7bf6-5e42-adcb-6cb708f708b3', '52f41a04-0f3b-5346-ab9c-47c70e115043', NULL, 24, 24, 'The fierce anger of Yahweh will not return, until he has executed, and until he has performed the intentions of his heart. In the latter days you will understand it.'),
  ('0c9e844f-6bfc-5733-ac47-3eee8a0499ce', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 1, 1, 'At that time, says Yahweh, will I be the God of all the families of Israel, and they shall be my people.'),
  ('3822df74-fb36-5166-a802-9b0ca01b125d', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 2, 2, 'Thus says Yahweh, The people who were left of the sword found favor in the wilderness; even Israel, when I went to cause him to rest.'),
  ('3ddfc177-c83a-553f-a2ab-233e2eb3fe52', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 3, 3, 'Yahweh appeared of old to me, [saying], Yes, I have loved you with an everlasting love: therefore with loving kindness have I drawn you.'),
  ('0841fdea-322c-5082-a62e-0bbb8269fad1', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 4, 4, 'Again will I build you, and you shall be built, O virgin of Israel: again you shall be adorned with your tambourines, and shall go forth in the dances of those who make merry.'),
  ('4de7d320-b2f5-5ef1-a7a3-ac0c07e9fcd2', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 5, 5, 'Again you shall plant vineyards on the mountains of Samaria; the planters shall plant, and shall enjoy [its fruit].'),
  ('fa7984a5-b716-53f7-a305-fbcf97bcdfc8', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 6, 6, 'For there shall be a day, that the watchmen on the hills of Ephraim shall cry, Arise, and let us go up to Zion to Yahweh our God.'),
  ('d12de7d4-8d19-5ccd-afbb-3b0d62f06dad', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 7, 7, 'For thus says Yahweh, Sing with gladness for Jacob, and shout for the chief of the nations: publish, praise, and say, Yahweh, save your people, the remnant of Israel.'),
  ('1103d8a9-1d83-5585-a87d-d1c027df95dc', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 8, 8, 'Behold, I will bring them from the north country, and gather them from the uttermost parts of the earth, [and] with them the blind and the lame, the woman with child and her who travails with child together: a great company shall they return here.'),
  ('b44ac7a6-894d-5805-afbd-a703f9292ef2', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 9, 9, 'They shall come with weeping; and with petitions will I lead them: I will cause them to walk by rivers of waters, in a straight way in which they shall not stumble; for I am a father to Israel, and Ephraim is my firstborn.'),
  ('dd1d779e-a12d-5d0c-abaf-95618de4b41e', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 10, 10, 'Hear the word of Yahweh, you nations, and declare it in the islands afar off; and say, He who scattered Israel will gather him, and keep him, as shepherd does his flock.'),
  ('70c47358-b175-5f7b-abe6-071e15e05975', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 11, 11, 'For Yahweh has ransomed Jacob, and redeemed him from the hand of him who was stronger than he.'),
  ('c749bf88-d055-5ac1-a4d6-6aceb5b89b39', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 12, 12, 'They shall come and sing in the height of Zion, and shall flow to the goodness of Yahweh, to the grain, and to the new wine, and to the oil, and to the young of the flock and of the herd: and their soul shall be as a watered garden; and they shall not sorrow any more at all.'),
  ('36121161-f60d-5f53-a605-0b0427df2a03', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 13, 13, 'Then shall the virgin rejoice in the dance, and the young men and the old together; for I will turn their mourning into joy, and will comfort them, and make them rejoice from their sorrow.'),
  ('4840b420-3f7f-5fd3-a578-05d65163eccc', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 14, 14, 'I will satiate the soul of the priests with fatness, and my people shall be satisfied with my goodness, says Yahweh.'),
  ('8331fa02-7bad-5598-a708-18f69cffd746', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 15, 15, 'Thus says Yahweh: A voice is heard in Ramah, lamentation, and bitter weeping, Rachel weeping for her children; she refuses to be comforted for her children, because they are no more.'),
  ('29f91b0e-6dcf-5eec-a6bb-eb5d6fc83d5a', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 16, 16, 'Thus says Yahweh: Refrain your voice from weeping, and your eyes from tears; for your work shall be rewarded, says Yahweh; and they shall come again from the land of the enemy.'),
  ('c639b203-4975-5ada-a079-4a132a5f1914', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 17, 17, 'There is hope for your latter end, says Yahweh; and [your] children shall come again to their own border.'),
  ('cd2553cc-1a55-5eec-a0ef-46b7dff3e605', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 18, 18, 'I have surely heard Ephraim bemoaning himself [thus], You have chastised me, and I was chastised, as a calf unaccustomed [to the yoke]: turn me, and I shall be turned; for you are Yahweh my God.'),
  ('7ab72cd2-1036-5c64-a658-d1064dfb029e', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 19, 19, 'Surely after that I was turned, I repented; and after that I was instructed, I struck on my thigh: I was ashamed, yes, even confounded, because I did bear the reproach of my youth.'),
  ('b42d57f6-6165-5c7e-a9d3-fd58495c3871', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 20, 20, 'Is Ephraim my dear son? is he a darling child? for as often as I speak against him, I do earnestly remember him still: therefore my heart yearns for him; I will surely have mercy on him, says Yahweh.'),
  ('a0faea48-f841-52ee-af86-cf189bc0941f', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 21, 21, 'Set up road signs, make guideposts; set your heart toward the highway, even the way by which you went: turn again, virgin of Israel, turn again to these your cities.'),
  ('db62a5d6-e94f-5def-af62-4fcbf03df672', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 22, 22, 'How long will you go here and there, you backsliding daughter? for Yahweh has created a new thing in the earth: a woman shall encompass a man.'),
  ('408f2d6d-39e5-593a-aef3-fbe3b8d9b8c7', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 23, 23, 'Thus says Yahweh of Armies, the God of Israel, Yet again shall they use this speech in the land of Judah and in its cities, when I shall bring again their captivity: Yahweh bless you, habitation of righteousness, mountain of holiness.'),
  ('b97454d4-1b4b-5546-a68c-7e69c7c2e633', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 24, 24, 'Judah and all its cities shall dwell therein together, the farmers, and those who go about with flocks.'),
  ('c66c8935-fd6e-50fc-ac44-c635442be754', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 25, 25, 'For I have satiated the weary soul, and every sorrowful soul have I replenished.'),
  ('f740bff4-64c4-5c88-a6a0-1ac47abfe62b', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 26, 26, 'On this I awakened, and saw; and my sleep was sweet to me.'),
  ('8cb67f22-7e6a-5270-aefe-b5120ab036b4', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 27, 27, 'Behold, the days come, says Yahweh, that I will sow the house of Israel and the house of Judah with the seed of man, and with the seed of animal.'),
  ('c807af18-7edb-51e2-a3fb-4e62ace67049', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 28, 28, 'It shall happen that, like as I have watched over them to pluck up and to break down and to overthrow and to destroy and to afflict, so will I watch over them to build and to plant, says Yahweh.'),
  ('0c15132b-2088-5f9d-a974-3097fea90d80', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 29, 29, 'In those days they shall say no more, The fathers have eaten sour grapes, and the children''s teeth are set on edge.'),
  ('52944237-ceb8-5158-a9b5-81ec78616c2c', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 30, 30, 'But everyone shall die for his own iniquity: every man who eats the sour grapes, his teeth shall be set on edge.'),
  ('9c07ad28-7a27-5694-a9cd-2bebbf14ab37', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 31, 31, 'Behold, the days come, says Yahweh, that I will make a new covenant with the house of Israel, and with the house of Judah:'),
  ('39d9968c-8090-5f97-a2ee-a2968a88ad2c', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 32, 32, 'not according to the covenant that I made with their fathers in the day that I took them by the hand to bring them out of the land of Egypt; which my covenant they broke, although I was a husband to them, says Yahweh.'),
  ('0b165e74-c327-5182-a761-5746967b1b60', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 33, 33, 'But this is the covenant that I will make with the house of Israel after those days, says Yahweh: I will put my law in their inward parts, and in their heart will I write it; and I will be their God, and they shall be my people:'),
  ('d061e86c-f1a7-5bff-ae7f-84eb46b5fade', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 34, 34, 'and they shall teach no more every man his neighbor, and every man his brother, saying, Know Yahweh; for they shall all know me, from the least of them to the greatest of them, says Yahweh: for I will forgive their iniquity, and their sin will I remember no more.'),
  ('bf32d8e1-80cb-5b7f-a3c2-ba27f011c639', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 35, 35, 'Thus says Yahweh, who gives the sun for a light by day, and the ordinances of the moon and of the stars for a light by night, who stirs up the sea, so that its waves roar; Yahweh of Armies is his name:'),
  ('5cf77cb8-ad82-5ec3-ab6e-9e125830f913', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 36, 36, 'If these ordinances depart from before me, says Yahweh, then the seed of Israel also shall cease from being a nation before me forever.'),
  ('e5221ca5-e3d7-583d-a37b-d62a78c65820', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 37, 37, 'Thus says Yahweh: If heaven above can be measured, and the foundations of the earth searched out beneath, then will I also cast off all the seed of Israel for all that they have done, says Yahweh.'),
  ('c442c73f-b05c-50ef-ae64-1cd8da46ce54', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 38, 38, 'Behold, the days come, says Yahweh, that the city shall be built to Yahweh from the tower of Hananel to the gate of the corner.'),
  ('0e55d423-0a0a-5401-aefb-610dcb727c2b', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 39, 39, 'The measuring line shall go out further straight onward to the hill Gareb, and shall turn about to Goah.'),
  ('d6749ac4-5a81-5d84-ae75-3df00b80d8a0', 'e82d07c0-6a6c-5182-ab30-4fd859779790', NULL, 40, 40, 'The whole valley of the dead bodies and of the ashes, and all the fields to the brook Kidron, to the corner of the horse gate toward the east, shall be holy to Yahweh; it shall not be plucked up, nor thrown down any more forever.'),
  ('578e1bff-9356-5d3d-a2df-3288a9100056', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 1, 1, 'The word that came to Jeremiah from Yahweh in the tenth year of Zedekiah king of Judah, which was the eighteenth year of Nebuchadnezzar.'),
  ('8eb54dcd-ecd4-541b-a20b-f3d000e2445e', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 2, 2, 'Now at that time the king of Babylon''s army was besieging Jerusalem; and Jeremiah the prophet was shut up in the court of the guard, which was in the king of Judah''s house.'),
  ('ffd3b671-c696-5a5e-a5a9-c08ebe779401', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 3, 3, 'For Zedekiah king of Judah had shut him up, saying, Why do you prophesy, and say, Thus says Yahweh, Behold, I will give this city into the hand of the king of Babylon, and he shall take it;'),
  ('442db454-5336-59de-a006-222dd9e16bb9', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 4, 4, 'and Zedekiah king of Judah shall not escape out of the hand of the Chaldeans, but shall surely be delivered into the hand of the king of Babylon, and shall speak with him mouth to mouth, and his eyes shall see his eyes;'),
  ('50a9345b-261f-5d02-a47d-c69a467f1df8', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 5, 5, 'and he shall bring Zedekiah to Babylon, and he shall be there until I visit him, says Yahweh: though you fight with the Chaldeans, you shall not prosper?'),
  ('16649f1b-1264-581e-ad7f-208f154185da', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 6, 6, 'Jeremiah said, The word of Yahweh came to me, saying,'),
  ('7b74fd56-6616-5b34-aef1-f254a68d4637', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 7, 7, 'Behold, Hanamel the son of Shallum your uncle shall come to you, saying, Buy my field that is in Anathoth; for the right of redemption is yours to buy it.'),
  ('fa06ea55-38d9-5208-a440-e2601439c394', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 8, 8, 'So Hanamel my uncle''s son came to me in the court of the guard according to the word of Yahweh, and said to me, Please buy my field that is in Anathoth, which is in the land of Benjamin; for the right of inheritance is yours, and the redemption is yours; buy it for yourself. Then I knew that this was the word of Yahweh.'),
  ('5dbadddc-f073-535b-a0f3-a317a5bc3f19', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 9, 9, 'I bought the field that was in Anathoth of Hanamel my uncle''s son, and weighed him the money, even seventeen shekels of silver.'),
  ('5787ee86-1be9-5189-a2e1-4c8eea58cbcb', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 10, 10, 'I subscribed the deed, and sealed it, and called witnesses, and weighed him the money in the balances.'),
  ('7d2c7126-f469-5990-aba9-5e67fe570eeb', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 11, 11, 'So I took the deed of the purchase, both that which was sealed, containing the terms and conditions, and that which was open;'),
  ('2c0db165-59f1-5a46-af17-b96fcd235edc', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 12, 12, 'and I delivered the deed of the purchase to Baruch the son of Neriah, the son of Mahseiah, in the presence of Hanamel my uncle''s son, and in the presence of the witnesses who subscribed the deed of the purchase, before all the Jews who sat in the court of the guard.'),
  ('28ac400d-07d7-55ee-a6f2-b81d92c2180b', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 13, 13, 'I commanded Baruch before them, saying,'),
  ('cb5e79ba-ad8c-55dd-a142-02e543a90aaa', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 14, 14, 'Thus says Yahweh of Armies, the God of Israel: Take these deeds, this deed of the purchase which is sealed, and this deed which is open, and put them in an earthen vessel; that they may continue many days.'),
  ('bb756f12-42bc-5a3f-a7f0-21b917e9d6e9', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 15, 15, 'For thus says Yahweh of Armies, the God of Israel: Houses and fields and vineyards shall yet again be bought in this land.'),
  ('c8ed6b23-78da-5820-ac1a-bdb16b7be3e5', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 16, 16, 'Now after I had delivered the deed of the purchase to Baruch the son of Neriah, I prayed to Yahweh, saying,'),
  ('4846369f-f06b-5d78-a8fd-8b3e5ddf7ae8', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 17, 17, 'Ah Lord Yahweh! Behold, you have made the heavens and the earth by your great power and by your outstretched arm; there is nothing too hard for you,'),
  ('06e1c02b-df64-5e94-a0f3-962f3ae49a69', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 18, 18, 'who show loving kindness to thousands, and recompense the iniquity of the fathers into the bosom of their children after them; the great, the mighty God, Yahweh of Armies is his name;'),
  ('27f91c5f-488c-5861-ae9c-49009c8a0fe0', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 19, 19, 'great in counsel, and mighty in work; whose eyes are open on all the ways of the sons of men, to give everyone according to his ways, and according to the fruit of his doings:'),
  ('948b4081-02e8-5371-acb3-15b28513bde7', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 20, 20, 'who performed signs and wonders in the land of Egypt, even to this day, both in Israel and among [other] men; and made yourself a name, as in this day;'),
  ('7966cd9e-362a-506d-a517-9bc4ed829695', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 21, 21, 'and brought forth your people Israel out of the land of Egypt with signs, and with wonders, and with a strong hand, and with an outstretched arm, and with great terror;'),
  ('3a025dbf-4bfc-55e8-a1ea-b7a599d51736', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 22, 22, 'and gave them this land, which you swore to their fathers to give them, a land flowing with milk and honey;'),
  ('487f50a7-d15f-55e4-a613-83063a626cb3', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 23, 23, 'and they came in, and possessed it, but they didn''t obey your voice, neither walked in your law; they have done nothing of all that you commanded them to do: therefore you have caused all this evil to come on them.'),
  ('2cdf442a-1bbe-5b42-a582-ccc380f0d9e6', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 24, 24, 'Behold, the mounds, they are come to the city to take it; and the city is given into the hand of the Chaldeans who fight against it, because of the sword, and of the famine, and of the pestilence; and what you have spoken has happened; and behold, you see it.'),
  ('16f9ffac-5e5d-50ee-a058-b00ca609761b', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 25, 25, 'You have said to me, Lord Yahweh, Buy the field for money, and call witnesses; whereas the city is given into the hand of the Chaldeans.'),
  ('2300c535-3e9b-52b5-af34-380d46cfd364', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 26, 26, 'Then came the word of Yahweh to Jeremiah, saying,'),
  ('6df62799-50aa-5f29-af41-8aeddc0259d6', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 27, 27, 'Behold, I am Yahweh, the God of all flesh: is there anything too hard for me?'),
  ('bccdc28b-1116-5f94-a4fc-a64172eebb2b', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 28, 28, 'Therefore thus says Yahweh: Behold, I will give this city into the hand of the Chaldeans, and into the hand of Nebuchadnezzar king of Babylon, and he shall take it:'),
  ('e5ec091c-c7ed-5b20-a559-3a419445bb1c', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 29, 29, 'and the Chaldeans, who fight against this city, shall come and set this city on fire, and burn it, with the houses, on whose roofs they have offered incense to Baal, and poured out drink offerings to other gods, to provoke me to anger.'),
  ('1c6a0b57-8cc7-5123-a079-5c9ba42e1aec', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 30, 30, 'For the children of Israel and the children of Judah have done only that which was evil in my sight from their youth; for the children of Israel have only provoked me to anger with the work of their hands, says Yahweh.'),
  ('60c55686-7235-5560-a85e-f2833c5ae264', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 31, 31, 'For this city has been to me a provocation of my anger and of my wrath from the day that they built it even to this day; that I should remove it from before my face,'),
  ('ba75fd3c-552d-5357-ae9f-a76926171ccd', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 32, 32, 'because of all the evil of the children of Israel and of the children of Judah, which they have done to provoke me to anger, they, their kings, their princes, their priests, and their prophets, and the men of Judah, and the inhabitants of Jerusalem.'),
  ('5c2d2cc2-9797-594d-ad9c-c51dd43dd6dc', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 33, 33, 'They have turned to me the back, and not the face: and though I taught them, rising up early and teaching them, yet they have not listened to receive instruction.'),
  ('87b110c3-4ddd-5c76-a68d-96529d1adf0e', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 34, 34, 'But they set their abominations in the house which is called by my name, to defile it.'),
  ('26ea304e-e7a2-5f92-a09d-6c72f56365b9', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 35, 35, 'They built the high places of Baal, which are in the valley of the son of Hinnom, to cause their sons and their daughters to pass through [the fire] to Molech; which I didn''t command them, neither did it come into my mind, that they should do this abomination, to cause Judah to sin.'),
  ('a6da65e7-e335-51e8-ab47-fd91921e57dd', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 36, 36, 'Now therefore thus says Yahweh, the God of Israel, concerning this city, about which you say, It is given into the hand of the king of Babylon by the sword, and by the famine, and by the pestilence:'),
  ('e3c06483-c380-59fb-a148-c4890dd13c63', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 37, 37, 'Behold, I will gather them out of all the countries, where I have driven them in my anger, and in my wrath, and in great indignation; and I will bring them again to this place, and I will cause them to dwell safely:'),
  ('cbda0a61-308f-572a-a661-d6d1f1d45222', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 38, 38, 'and they shall be my people, and I will be their God:'),
  ('51bf0306-e4df-52d5-a352-e73094bc099f', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 39, 39, 'and I will give them one heart and one way, that they may fear me forever, for the good of them, and of their children after them:'),
  ('4424e4dd-9a36-5658-ae6b-0d5bdab02116', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 40, 40, 'and I will make an everlasting covenant with them, that I will not turn away from following them, to do them good; and I will put my fear in their hearts, that they may not depart from me.'),
  ('2aa49a64-d8c4-5685-ab98-b8d781fb409d', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 41, 41, 'Yes, I will rejoice over them to do them good, and I will plant them in this land assuredly with my whole heart and with my whole soul.'),
  ('fd26b37e-f6ed-5ef4-a687-5a2653128258', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 42, 42, 'For thus says Yahweh: Like as I have brought all this great evil on this people, so will I bring on them all the good that I have promised them.'),
  ('be49d6c2-98d3-5ef5-a393-4a34f2e248ef', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 43, 43, 'Fields shall be bought in this land, about which you say, It is desolate, without man or animal; it is given into the hand of the Chaldeans.'),
  ('c69eb24f-b4fb-56d4-a75c-4841d162b348', '321089bc-3aff-5db1-a8a1-805b87235cd2', NULL, 44, 44, 'Men shall buy fields for money, and subscribe the deeds, and seal them, and call witnesses, in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, and in the cities of the hill country, and in the cities of the lowland, and in the cities of the South: for I will cause their captivity to return, says Yahweh.'),
  ('68a16690-3de5-5eef-aa75-17c49ed03105', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 1, 1, 'Moreover the word of Yahweh came to Jeremiah the second time, while he was yet shut up in the court of the guard, saying,'),
  ('92c2bece-ab64-53b1-ada4-36a65d405138', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 2, 2, 'Thus says Yahweh who does it, Yahweh who forms it to establish it; Yahweh is his name:'),
  ('0dd0803f-120e-5a42-aed5-ebf3dd28a53e', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 3, 3, 'Call to me, and I will answer you, and will show you great things, and difficult, which you don''t know.'),
  ('aad9e1e4-3d76-57e4-aa1a-732cef8d5bf1', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 4, 4, 'For thus says Yahweh, the God of Israel, concerning the houses of this city, and concerning the houses of the kings of Judah, which are broken down [to make a defense] against the mounds and against the sword;'),
  ('087e15df-f93c-5b1f-a8fa-0170c658a8eb', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 5, 5, 'while [men] come to fight with the Chaldeans, and to fill them with the dead bodies of men, whom I have killed in my anger and in my wrath, and for all whose wickedness I have hidden my face from this city:'),
  ('f210f798-da93-5b91-a0d3-fd8fbb89d185', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 6, 6, 'Behold, I will bring it health and cure, and I will cure them; and I will reveal to them abundance of peace and truth.'),
  ('874b8a30-8202-5d3e-af91-3eb8e57a71ed', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 7, 7, 'I will cause the captivity of Judah and the captivity of Israel to return, and will build them, as at the first.'),
  ('9fa484f4-bc1d-51d1-ac8a-6b0555baf13b', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 8, 8, 'I will cleanse them from all their iniquity, by which they have sinned against me; and I will pardon all their iniquities, by which they have sinned against me, and by which they have transgressed against me.'),
  ('22dfee9b-12f3-555e-aa7c-f250c41f9948', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 9, 9, '[This city] shall be to me for a name of joy, for a praise and for a glory, before all the nations of the earth, which shall hear all the good that I do to them, and shall fear and tremble for all the good and for all the peace that I procure to it.'),
  ('2d2818fc-df9b-52a1-a66b-2b48d2d32131', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 10, 10, 'Thus says Yahweh: Yet again there shall be heard in this place, about which you say, It is waste, without man and without animal, even in the cities of Judah, and in the streets of Jerusalem, that are desolate, without man and without inhabitant and without animal,'),
  ('4ede1823-4bcb-530c-a88f-2e0ae1cfbeac', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 11, 11, 'the voice of joy and the voice of gladness, the voice of the bridegroom and the voice of the bride, the voice of those who say, Give thanks to Yahweh of Armies, for Yahweh is good, for his loving kindness endures forever; [and of them] who bring [sacrifices of] thanksgiving into the house of Yahweh. For I will cause the captivity of the land to return as at the first, says Yahweh.'),
  ('d0df5323-0414-535f-aa95-f69a15179747', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 12, 12, 'Thus says Yahweh of Armies: Yet again shall there be in this place, which is waste, without man and without animal, and in all its cities, a habitation of shepherds causing their flocks to lie down.'),
  ('a03b8664-57c3-50bb-ac4a-9c345a8f1039', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 13, 13, 'In the cities of the hill country, in the cities of the lowland, and in the cities of the South, and in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, shall the flocks again pass under the hands of him who numbers them, says Yahweh.'),
  ('cc4f4819-d090-572c-a891-8aed05efc5e1', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 14, 14, 'Behold, the days come, says Yahweh, that I will perform that good word which I have spoken concerning the house of Israel and concerning the house of Judah.'),
  ('ae652c4b-58c5-5fda-ab42-c10aae5e10e2', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 15, 15, 'In those days, and at that time, will I cause a Branch of righteousness to grow up to David; and he shall execute justice and righteousness in the land.'),
  ('a6a181da-4bce-5520-abb3-8c7fdbb2ff77', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 16, 16, 'In those days shall Judah be saved, and Jerusalem shall dwell safely; and this is [the name] by which she shall be called: Yahweh our righteousness.'),
  ('b2c4886a-94ae-5f9e-aee0-012485231bbb', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 17, 17, 'For thus says Yahweh: David shall never want a man to sit on the throne of the house of Israel;'),
  ('55880644-9da9-5076-a2da-699efc02210c', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 18, 18, 'neither shall the priests the Levites want a man before me to offer burnt offerings, and to burn meal offerings, and to do sacrifice continually.'),
  ('e50a5f18-dc99-5cb2-a2c6-ca8a34269446', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 19, 19, 'The word of Yahweh came to Jeremiah, saying,'),
  ('3d76584b-7591-5dec-aa31-971352622819', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 20, 20, 'Thus says Yahweh: If you can break my covenant of the day, and my covenant of the night, so that there shall not be day and night in their season;'),
  ('a7e885e8-4217-5cc7-af29-f090e2f12a11', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 21, 21, 'then may also my covenant be broken with David my servant, that he shall not have a son to reign on his throne; and with the Levites the priests, my ministers.'),
  ('30f0db4c-00ef-5085-a81f-8f3951b30af0', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 22, 22, 'As the army of the sky can''t be numbered, neither the sand of the sea measured; so will I multiply the seed of David my servant, and the Levites who minister to me.'),
  ('2453c7ac-71c7-5cea-ac30-a08cb7a52171', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 23, 23, 'The word of Yahweh came to Jeremiah, saying,'),
  ('ec6f2d7b-a0d9-5ade-ab0a-c3cdd7cf0dc5', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 24, 24, 'Don''t consider what this people has spoken, saying, The two families which Yahweh did choose, he has cast them off? thus do they despise my people, that they should be no more a nation before them.'),
  ('5b616a71-b94f-52f0-a5d3-1ffad89542cd', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 25, 25, 'Thus says Yahweh: If my covenant of day and night fails, if I have not appointed the ordinances of heaven and earth;'),
  ('483b344c-a920-518c-af7c-fde073389633', '1bb52150-02ac-5e2a-aa41-7a0c532028f2', NULL, 26, 26, 'then will I also cast away the seed of Jacob, and of David my servant, so that I will not take of his seed to be rulers over the seed of Abraham, Isaac, and Jacob: for I will cause their captivity to return, and will have mercy on them.'),
  ('2b53795b-db27-5a44-a7a3-d9b478b70d2b', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 1, 1, 'The word which came to Jeremiah from Yahweh, when Nebuchadnezzar king of Babylon, and all his army, and all the kingdoms of the earth that were under his dominion, and all the peoples, were fighting against Jerusalem, and against all the cities of it, saying:'),
  ('71c389b8-348b-5564-ab0b-404d92a3a1e7', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 2, 2, 'Thus says Yahweh, the God of Israel, Go, and speak to Zedekiah king of Judah, and tell him, Thus says Yahweh, Behold, I will give this city into the hand of the king of Babylon, and he shall burn it with fire:'),
  ('edc710ec-012c-5f9b-a3b7-6ae675bc6c75', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 3, 3, 'and you shall not escape out of his hand, but shall surely be taken, and delivered into his hand; and your eyes shall see the eyes of the king of Babylon, and he shall speak with you mouth to mouth, and you shall go to Babylon.'),
  ('76999f3f-9b98-5cd8-a594-fa992bac676a', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 4, 4, 'Yet hear the word of Yahweh, O Zedekiah king of Judah: thus says Yahweh concerning you, You shall not die by the sword;'),
  ('746abdda-3c9e-5964-a7f9-219cd3346c74', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 5, 5, 'you shall die in peace; and with the burnings of your fathers, the former kings who were before you, so shall they make a burning for you; and they shall lament you, [saying], Ah Lord! for I have spoken the word, says Yahweh.'),
  ('cd2b3f76-b9c5-59b7-afef-bdb1180bd040', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 6, 6, 'Then Jeremiah the prophet spoke all these words to Zedekiah king of Judah in Jerusalem,'),
  ('b3edf55a-1e49-59ae-aac8-33e995b4f41f', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 7, 7, 'when the king of Babylon''s army was fighting against Jerusalem, and against all the cities of Judah that were left, against Lachish and against Azekah; for these [alone] remained of the cities of Judah [as] fortified cities.'),
  ('5f79ccd6-e9b7-5d7f-a584-83b53f3979dd', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 8, 8, 'The word that came to Jeremiah from Yahweh, after that the king Zedekiah had made a covenant with all the people who were at Jerusalem, to proclaim liberty to them;'),
  ('e160159f-096f-5fd9-abe3-1949d79ec5c0', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 9, 9, 'that every man should let his male servant, and every man his female servant, who is a Hebrew or a Hebrewess, go free; that none should make bondservants of them, [to wit], of a Jew his brother.'),
  ('ac8ad3cc-f6db-5d89-a6ef-af81209def7a', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 10, 10, 'All the princes and all the people obeyed, who had entered into the covenant, that everyone should let his male servant, and everyone his female servant, go free, that none should make bondservants of them any more; they obeyed, and let them go:'),
  ('67422ce3-52d5-5d26-ab86-8a8feede17df', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 11, 11, 'but afterwards they turned, and caused the servants and the handmaids, whom they had let go free, to return, and brought them into subjection for servants and for handmaids.'),
  ('67fc29f1-6b44-5274-a862-2ee9958f750b', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 12, 12, 'Therefore the word of Yahweh came to Jeremiah from Yahweh, saying,'),
  ('033f104f-ab90-5a29-a2af-7261b9f1ce99', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 13, 13, 'Thus says Yahweh, the God of Israel: I made a covenant with your fathers in the day that I brought them forth out of the land of Egypt, out of the house of bondage, saying,'),
  ('3c306bb0-c1de-5596-af0b-22df2d2a5807', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 14, 14, 'At the end of seven years you shall let go every man his brother who is a Hebrew, who has been sold to you, and has served you six years, you shall let him go free from you: but your fathers didn''t listen to me, neither inclined their ear.'),
  ('10a8c520-bf45-502d-a667-6545b0b0a2ca', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 15, 15, 'You had now turned, and had done that which is right in my eyes, in proclaiming liberty every man to his neighbor; and you had made a covenant before me in the house which is called by my name:'),
  ('a74049f9-70ef-5cf2-a820-120d3af028ae', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 16, 16, 'but you turned and profaned my name, and caused every man his servant, and every man his handmaid, whom you had let go free at their pleasure, to return; and you brought them into subjection, to be to you for servants and for handmaids.'),
  ('2634b2f5-2b81-5b1b-a265-ac00c4fcc608', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 17, 17, 'Therefore thus says Yahweh: you have not listened to me, to proclaim liberty, every man to his brother, and every man to his neighbor: behold, I proclaim to you a liberty, says Yahweh, to the sword, to the pestilence, and to the famine; and I will make you to be tossed back and forth among all the kingdoms of the earth.'),
  ('68f385af-5cd6-54dc-aba7-d06267087466', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 18, 18, 'I will give the men who have transgressed my covenant, who have not performed the words of the covenant which they made before me, when they cut the calf in two and passed between its parts;'),
  ('f77542a2-bfb0-55bd-a9d6-f97057447fe5', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 19, 19, 'the princes of Judah, and the princes of Jerusalem, the eunuchs, and the priests, and all the people of the land, who passed between the parts of the calf;'),
  ('c5ba1ce2-044a-51af-a583-6354982d3e69', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 20, 20, 'I will even give them into the hand of their enemies, and into the hand of those who seek their life; and their dead bodies shall be for food to the birds of the sky, and to the animals of the earth.'),
  ('c710d75a-5129-5367-a536-c751a617b7c6', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 21, 21, 'Zedekiah king of Judah and his princes will I give into the hand of their enemies, and into the hand of those who seek their life, and into the hand of the king of Babylon''s army, who have gone away from you.'),
  ('c385c658-6880-5b95-a68a-2943da06bd51', 'a2b49db8-53b9-5e82-a001-cf9ab8ee86fb', NULL, 22, 22, 'Behold, I will command, says Yahweh, and cause them to return to this city; and they shall fight against it, and take it, and burn it with fire: and I will make the cities of Judah a desolation, without inhabitant.'),
  ('b95bcf23-6503-5287-ac93-b064a9915977', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 1, 1, 'The word which came to Jeremiah from Yahweh in the days of Jehoiakim the son of Josiah, king of Judah, saying,'),
  ('c1859974-5bdb-5f8e-abaa-4214a3f81a79', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 2, 2, 'Go to the house of the Rechabites, and speak to them, and bring them into the house of Yahweh, into one of the rooms, and give them wine to drink.'),
  ('49796cc8-4774-56cf-a3fb-14b94651cde9', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 3, 3, 'Then I took Jaazaniah the son of Jeremiah, the son of Habazziniah, and his brothers, and all his sons, and the whole house of the Rechabites;'),
  ('6236b1b6-8d95-5c55-adf3-f83b3b9d62d0', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 4, 4, 'and I brought them into the house of Yahweh, into the room of the sons of Hanan the son of Igdaliah, the man of God, which was by the room of the princes, which was above the room of Maaseiah the son of Shallum, the keeper of the threshold.'),
  ('7ae4f34b-7fdb-5218-a167-656b53898b33', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 5, 5, 'I set before the sons of the house of the Rechabites bowls full of wine, and cups; and I said to them, Drink wine!'),
  ('783c6e58-83df-52d0-af1e-f88a9f1e316e', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 6, 6, 'But they said, We will drink no wine; for Jonadab the son of Rechab, our father, commanded us, saying, You shall drink no wine, neither you, nor your sons, forever:'),
  ('ba90e10d-f85b-51a7-aeea-860aa1e68479', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 7, 7, 'neither shall you build house, nor sow seed, nor plant vineyard, nor have any; but all your days you shall dwell in tents; that you may live many days in the land in which you live.'),
  ('3671ee16-3e38-59de-a9b8-c2213be1f205', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 8, 8, 'We have obeyed the voice of Jonadab the son of Rechab, our father, in all that he commanded us, to drink no wine all our days, we, our wives, our sons, or our daughters;'),
  ('52d88cde-fc21-5cd8-a05f-054f3b3950b1', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 9, 9, 'nor to build houses for us to dwell in; neither have we vineyard, nor field, nor seed:'),
  ('83ec680e-ec0e-5ff5-a1ce-5a859dbc7dcb', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 10, 10, 'but we have lived in tents, and have obeyed, and done according to all that Jonadab our father commanded us.'),
  ('b0dd2437-57f6-5089-af05-f93d04a2a74b', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 11, 11, 'But it happened, when Nebuchadnezzar king of Babylon came up into the land, that we said, Come, and let us go to Jerusalem for fear of the army of the Chaldeans, and for fear of the army of the Syrians; so we dwell at Jerusalem.'),
  ('f820dd66-775f-53c8-ac86-130ebcea97cb', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 12, 12, 'Then came the word of Yahweh to Jeremiah, saying,'),
  ('ed0859fb-2770-5176-a976-9dd324df6df8', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 13, 13, 'Thus says Yahweh of Armies, the God of Israel: Go, and tell the men of Judah and the inhabitants of Jerusalem, Will you not receive instruction to listen to my words? says Yahweh.'),
  ('033a345b-0450-5440-a25e-fd98bacf8478', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 14, 14, 'The words of Jonadab the son of Rechab, that he commanded his sons, not to drink wine, are performed; and to this day they drink none, for they obey their father''s commandment: but I have spoken to you, rising up early and speaking; and you have not listened to me.'),
  ('ab45c629-6368-579f-a4b9-b3c43bc8ce83', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 15, 15, 'I have sent also to you all my servants the prophets, rising up early and sending them, saying, Return now every man from his evil way, and amend your doings, and don''t go after other gods to serve them, and you shall dwell in the land which I have given to you and to your fathers: but you have not inclined your ear, nor listened to me.'),
  ('3519c67f-2ffa-55b2-a43a-1090079ce8cb', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 16, 16, 'Because the sons of Jonadab the son of Rechab have performed the commandment of their father which he commanded them, but this people has not listened to me;'),
  ('76449d4b-5eb1-559a-a459-e27d7624883f', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 17, 17, 'therefore thus says Yahweh, the God of Armies, the God of Israel: Behold, I will bring on Judah and on all the inhabitants of Jerusalem all the evil that I have pronounced against them; because I have spoken to them, but they have not heard; and I have called to them, but they have not answered.'),
  ('2e7fda5e-65f7-5574-ae7b-d2213ba301e7', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 18, 18, 'Jeremiah said to the house of the Rechabites, Thus says Yahweh of Armies, the God of Israel: Because you have obeyed the commandment of Jonadab your father, and kept all his precepts, and done according to all that he commanded you;'),
  ('1529c750-6b6d-53dd-a573-815fb76ed4ca', 'e45481b5-dc7f-5ee1-a314-46cfa92ecadf', NULL, 19, 19, 'therefore thus says Yahweh of Armies, the God of Israel: Jonadab the son of Rechab shall not want a man to stand before me forever.'),
  ('67f521bd-978d-5fc7-a1cd-5f04fad47b36', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 1, 1, 'It happened in the fourth year of Jehoiakim the son of Josiah, king of Judah, that this word came to Jeremiah from Yahweh, saying,'),
  ('5e9e9b04-eb55-5769-ab36-286cc57a17c1', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 2, 2, 'Take a scroll of a book, and write therein all the words that I have spoken to you against Israel, and against Judah, and against all the nations, from the day I spoke to you, from the days of Josiah, even to this day.'),
  ('94a411c9-ce24-530e-a8de-1d3965e773a3', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 3, 3, 'It may be that the house of Judah will hear all the evil which I purpose to do to them; that they may return every man from his evil way; that I may forgive their iniquity and their sin.'),
  ('acff7c8c-ae08-5628-a5bc-a287c5315673', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 4, 4, 'Then Jeremiah called Baruch the son of Neriah; and Baruch wrote from the mouth of Jeremiah all the words of Yahweh, which he had spoken to him, on a scroll of a book.'),
  ('6f306286-49dc-52cb-a2d4-c2f528110980', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 5, 5, 'Jeremiah commanded Baruch, saying, I am shut up; I can''t go into the house of Yahweh:'),
  ('1d2c4111-4ed3-500b-acce-7c259fb3d13b', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 6, 6, 'therefore you go, and read in the scroll, which you have written from my mouth, the words of Yahweh in the ears of the people in Yahweh''s house on the fast day; and also you shall read them in the ears of all Judah who come out of their cities.'),
  ('776d5d5b-f16e-5702-a222-29a0974cb443', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 7, 7, 'It may be they will present their supplication before Yahweh, and will return everyone from his evil way; for great is the anger and the wrath that Yahweh has pronounced against this people.'),
  ('6bd8ce2b-16b3-5f22-aebf-45bcd9469c90', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 8, 8, 'Baruch the son of Neriah did according to all that Jeremiah the prophet commanded him, reading in the book the words of Yahweh in Yahweh''s house.'),
  ('3a559764-0c66-5aef-a5a9-a978daa77b7b', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 9, 9, 'Now it happened in the fifth year of Jehoiakim the son of Josiah, king of Judah, in the ninth month, that all the people in Jerusalem, and all the people who came from the cities of Judah to Jerusalem, proclaimed a fast before Yahweh.'),
  ('2f137a8f-2823-531a-a4b1-6d4c77449921', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 10, 10, 'Then read Baruch in the book the words of Jeremiah in the house of Yahweh, in the room of Gemariah the son of Shaphan, the scribe, in the upper court, at the entry of the new gate of Yahweh''s house, in the ears of all the people.'),
  ('04b433bd-d387-5180-a86b-d352669ba44f', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 11, 11, 'When Micaiah the son of Gemariah, the son of Shaphan, had heard out of the book all the words of Yahweh,'),
  ('0c47a60e-fe33-56ba-ade0-c59e63060363', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 12, 12, 'he went down into the king''s house, into the scribe''s room: and behold, all the princes were sitting there, [to wit], Elishama the scribe, and Delaiah the son of Shemaiah, and Elnathan the son of Achbor, and Gemariah the son of Shaphan, and Zedekiah the son of Hananiah, and all the princes.'),
  ('8b4964fc-ae01-511c-a9a8-3c2e55ae1103', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 13, 13, 'Then Micaiah declared to them all the words that he had heard, when Baruch read the book in the ears of the people.'),
  ('47d9589c-ac3d-59eb-ad72-044a6724c099', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 14, 14, 'Therefore all the princes sent Jehudi the son of Nethaniah, the son of Shelemiah, the son of Cushi, to Baruch, saying, Take in your hand the scroll in which you have read in the ears of the people, and come. So Baruch the son of Neriah took the scroll in his hand, and came to them.'),
  ('c5071b31-d552-5bf7-a9ba-3643f7b19c26', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 15, 15, 'They said to him, Sit down now, and read it in our ears. So Baruch read it in their ears.'),
  ('873ae8a5-ce17-5a51-a57c-e76a42f29058', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 16, 16, 'Now it happened, when they had heard all the words, they turned in fear one toward another, and said to Baruch, We will surely tell the king of all these words.'),
  ('6f28bf00-5f1f-5a78-a9e1-cafa6e9be706', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 17, 17, 'They asked Baruch, saying, Tell us now, How did you write all these words at his mouth?'),
  ('b906638d-823c-58c0-a1d3-3a7b7f9db23b', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 18, 18, 'Then Baruch answered them, He pronounced all these words to me with his mouth, and I wrote them with ink in the book.')
